# -*- coding: utf-8 -*-
"""레터본문 — 레터 본편을 「모델을 세운 순서 = 추론의 사슬」로 짠다 (2026-10-16 결정 · 「평가 레터 규칙」).

차례 — 머리 · 3분 레터(별도 요약본: 게이트가 떼어 따로 낸다) · `# 본편`:
   결론 → Narrative → 추정 구조(출발값 · 추정 순서 · 정합 조건 · 변수 연결도 · 평가 방법) → 매출 → 영업비용 → 인건비 →
   설비투자와 감가상각 → 운전자본 → 법인세와 FCFF → 할인율 → Terminal Value → 가치 브리지 → 시나리오 → 민감도 → Reverse DCF →
   모니터링 → 평가자의 이해관계와 평가의 한계 → 모델 점검 → 평가 모델 파일 · 부록.
   해당이 없는 절은 만들지 않는다(「해당 없음은 지운다」) — 인건비를 인원으로 세우지 않은 회사의 인건비 절, 종가가 없는 회사의 Reverse DCF 절.
규칙
 · 절 이름은 「실무 용어 : 그 절이 하는 일」(소제목 규칙 · 2026-10-15 구호 · 비유 금지).
 · 추정 절은 「앞 절에서 넘어온 값 → 이 절의 가정 → 다음 절로 넘기는 값」 한 문단으로 연다(`이음` — 숫자는 장부 키).
 · 추정 절마다 가정 표(가정 · 기준 · 비관 · 낙관 · 근거)를 싣는다 — 근거 칸은 독자층(`독자근거` · `서사연결`)만. 근거 4칸(저자층)은 부록 A 로만.
 · 가정을 소수 지수 · 배수로 적을 때는 무엇의 몇 %인지 함께 적는다 — 정상 수준은 「0.91(2025년 평균의 91%)」, 연동 배율은 「1.15(범용 DRAM
   웨이퍼당 매출의 115%)」. 기준 기간은 `Narrative.독자.눈금`(키 하나 — 없으면 엔진의 기준 기간)이다.
 · 저자 글이 없으면 그 문단은 서지 않는다(지어내지 않는다). 숫자는 모두 장부 키(`맥.수` · `맥.식`).
 · 앞부분 다섯 — 추정 구조 · 역산 · 매출 방법 · 실적 열 · 매출 대비 비중 표(Δ)는 본편에 있다. 게이트 ⑬ 이 빠졌는지 본다(`레터문장.앞부분점검`).
 · 2026-10-25 레터 재구성(연구/레터재구성_20261025 · 조문_본체.md) — 1절은 결론 다섯 줄(`레터이야기.결론줄들` — 3분 레터 맨 앞과 같은 글 · ⑬ 결론점검)로 열고,
   값을 가르는 가정은 한 함수(`레터이야기.지렛대`)가 정한다(결론 · 민감도 · 3분 · 결합 · 격자 — 게이트 ⑮). 항목 절마다 「이 절이 담은 Narrative」 줄(항목 절 판정)과
   「시나리오가 바뀌면 · 바뀌어도」 문장(`이야기문장`), 시나리오 절에 시나리오 × 줄별 변화 표(`전파표` — 게이트 ⑰), 변수 연결도는 동인 그래프의 설명체인에서(`그래프단계가정`),
   가정 표 근거 칸은 근거 한 줄(`근거한줄` — 독자근거 → 서사연결 → 절글 「범위」 첫 문장 → 변수 카드).
"""
from __future__ import annotations

import contextlib
import math
import re

import 어투
import 레터1부 as P
import 레터3분 as T
import 레터궤적 as G
import 레터이야기 as N
import 레터막 as M

본편머리 = "# 본편"
_제목기본 = {
    "결론": "결론 : 주당가치와 그 값을 가르는 가정",
    "Narrative": "Narrative : 회사를 보는 판단과 그 판단이 간 가정",
    "업황": "업황과 경쟁 : 사이클 위치 · 수급 · 경쟁 위치",          # 2026-10-31 요건판 3(독립 검토 L1 · L2)
    "구조": "추정 구조 : 출발값 · 추정 순서 · 정합 조건",
    "매출": "매출 추정 : 매출 구분별 물량과 가격",
    "비용": "영업비용 추정 : 원가 구성과 변동비 · 고정비",
    "인건비": "인건비 추정 : 인원 · 1인당 급여 · 성과급",
    "재투자": "설비투자와 감가상각 : 공장별 투자 일정과 유지 투자",
    "운전자본": "운전자본 추정 : 계정별 회전일수와 미지급 항목",
    "세금": "법인세와 FCFF : 영업이익에서 잉여현금흐름까지",
    "할인율": "할인율 : 자본비용과 Peer group",
    "영구": "Terminal Value : 정상 수준 · 영구 ROIC · 영구성장률의 정합",
    "주주가치": "가치 브리지 : 영업가치에서 주당가치까지",
    "시나리오": "시나리오 분석 : 시나리오별 가정과 결과",
    "민감도": "민감도 분석 : 가정별 주당가치 변동",
    "역산": "Reverse DCF : 주가가 전제한 가정",
    "신호": "모니터링 : 관측 신호와 다음 점검",
    "자리": "평가자의 이해관계와 평가의 한계",
    "점검": "모델 점검 : 자료 간 불일치와 점검 결과",
    "파일": "평가 모델 파일",
    "다리": "지난 평가와의 차이",
}
제목 = dict(_제목기본)
분류말 = {"변동": "변동비", "계단": "준고정비", "준고정": "인건비", "이익": "이익 연동 비용", "고정": "고정비", "조정": "조정"}     # 2026-10-27 — 비용 성격 구분(계단식 고정비 = 준고정비 · 인원 × 급여 = 인건비). 열쇠(계단 · 준고정 …)는 그대로


def _성격붙임(이름, 성):
    """원가 줄 이름 뒤 성격 괄호 — 이름이 이미 성격 말을 품으면(「기본 인건비(성과급 제외)」 · 「(−) 재고자산 변동 조정」) 붙이지 않는다."""
    return 이름 if 분류말[성] in 이름 else "%s (%s)" % (이름, 분류말[성])


def _n(x):
    return P._n(x)


def _글(x):
    return ("%s" % x).strip() if isinstance(x, str) else ""


def _N(맥):
    return 맥.가정.get("Narrative") if isinstance(맥.가정.get("Narrative"), dict) else {}


def _L():
    import 레터                                                 # noqa: PLC0415
    return 레터


def 그림이름(줄들):
    """3분 레터의 그림(「그림 1. 」 · 「그림 2의 값」)을 본편에 다시 실을 때 — 번호는 본편이 새로 매기고(「**그림. 」), 표 머리의 번호는 뗀다."""
    낸 = []
    for x in 줄들:                                            # 번호가 몇이든(그림 1~N) · 표 머리가 무엇이든(값 · 가로선 · 주석 …) 뗀다 — 다른 그림을 가리키지 않게
        x = re.sub(r"^\*\*그림 \d+\. ", "**그림. ", x)
        x = re.sub(r"^\| 그림 \d+의 ", "| 그림의 ", x)
        낸.append(x)
    return 낸


def 머리(키, 번):
    return ["## %d. %s" % (번, 제목[키]), ""]


def 곳(맥, 키):
    """절 키 → 「5절」(없으면 빈 글)."""
    return P.곳(맥, 맥.절[키]) if 맥.절.get(키) else ""


def _입니다(말):
    """「x입니다」 — 읽는 소리가 정해지지 않은 말(WACC)로 끝나면 「x 값입니다」(조사가 바로 붙지 않게 — 문체 검수 「조사」)."""
    return "%s%s" % (말, P._조(말, "입니다", "입니다"))


def 절이름(맥, 키):
    """절 키 → 그 절 제목의 앞말(「매출 추정」 · 「민감도 분석」 — 없으면 빈 글). 레터 v27 문장 — 다른 절은 이름으로 부르고 번호는 문장 끝 괄호로만."""
    return 제목[키].split(" : ")[0] if (맥.절.get(키) and 키 in 제목) else ""


def 이름(맥, 번):
    return N.이름다듬기(_L().가정이름("%s" % 번, 맥.구) or "가정 %s" % 번)


def _시(맥, 번):
    벌 = (맥.가정.get("가정") or {}).get("%s" % 번) or {}
    return "공통" if "공통" in 벌 else None


def 짧은이름(맥, 번):
    """연결도 상자의 가정 이름 — 매출 구분 이름 · 판매단가 명칭의 앞말을 떼고 괄호 덧말을 걷은 짧은 이름(「누적 변동률」 · 「정상 수준」)."""
    이 = 이름(맥, 번)
    for x in 맥.구.get("매출구분") or []:
        구 = ("%s" % (x.get("이름") or "")).strip()
        if 구 and 이.startswith(구 + " "):
            이 = 이[len(구) + 1:]
            break
    for x in 맥.구.get("매출구분") or []:
        명 = ("%s" % (x.get("판매단가명칭") or "")).replace(" 지수", "").strip()
        if 명:
            이 = 이.replace(명 + " ", "").replace(" " + 명 + " 지수", "").replace(" " + 명, "")
    이 = re.sub(r"\s*\([^()]*\)\s*$", "", 이).strip()
    return 이 or "가정"


def 값있나(맥, 번):
    번 = "%s" % 번
    L = _L()
    if 번 in (맥.가정.get("시점가정") or {}):
        return any(_n(L._시점값(맥.가정, 번, s)) is not None for s in P.시나리오들) or 번 == "219"
    if 번 in (맥.가정.get("가정") or {}):
        return bool(L._값든열(맥.가정, 번, 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])))
    return False


# ══════════════════════════════════════════════════════════════════ 값의 글 — 지수 · 배율은 무엇의 몇 %인지 함께

def _구분(맥, s):
    return next((x for x in 맥.구.get("매출구분") or [] if x.get("번호") == s), {})


def 지수덧(맥, 키, s, 꼴="지수2"):
    """판매단가 지수(정상 수준 따위) → 「0.91(2025년 평균의 91%)」 — 기준 기간은 `Narrative.독자.눈금` 키 하나(없으면 엔진의 기준 기간)."""
    if not _n(맥.값(P.눈금키(맥, s))):
        return 맥.수(키, 꼴) if isinstance(키, str) else 맥.식(키, 꼴)
    값 = 맥.수(키, 꼴) if isinstance(키, str) else 맥.식(키, 꼴)
    return "%s(%s의 %s)" % (값, P.눈금이름(맥, _구분(맥, s)), 맥.식(["÷", 키, P.눈금키(맥, s)], "퍼0"))


def 배율덧(맥, 키, s):
    """연동 배율(HBM 연동 배율 따위) → 「1.15(범용 DRAM 웨이퍼당 매출의 115%)」."""
    x = _구분(맥, s)
    따 = x.get("연동구분")
    if not 따:
        return 맥.수(키, "지수2")
    말 = ("%s" % (_구분(맥, 따).get("판매단가명칭") or "판매단가")).replace(" 지수", "")
    return "%s(%s %s의 %s)" % (맥.수(키, "지수2"), _L().구분이름(맥.구, 따), 말, 맥.식(["×", 키, 1], "퍼0"))


def _칸글(맥, 번, 키):
    L = _L()
    if re.fullmatch(r"55[1-5]", 번):                         # 연동 시차(년)
        return 맥.수(키, "수0") + "년"
    m6 = re.fullmatch(r"6([1-5])6", 번)
    if m6:
        return 지수덧(맥, 키, int(m6.group(1)))
    m54 = re.fullmatch(r"54([1-5])", 번)
    if m54 and _구분(맥, int(m54.group(1))).get("단가경로") == "연동":
        return 배율덧(맥, 키, int(m54.group(1)))
    return 맥.수(키, L.가정꼴(번, 맥.구))


def 가정값글(맥, 번, 시="기준"):
    """가정 하나의 시나리오 값 글 — 한 값 가정은 그 값, 열별 가정은 모든 열이 같으면 그 값 · 셋 이하면 열마다 · 넘으면 첫 → 끝."""
    L = _L()
    번 = "%s" % 번
    if 번 in (맥.가정.get("시점가정") or {}):
        if _n(L._시점값(맥.가정, 번, 시)) is None:
            if 번 == "219" and _n(맥.값("R:%s:2.DCF:48" % 시)) is not None:     # 비워 두면 영구기간 ROIC = 영구기간 WACC
                return "영구기간 WACC와 같음(%s)" % 맥.수("R:%s:2.DCF:48" % 시, "퍼2")
            return "—"
        return _칸글(맥, 번, "S:%s:%s" % (번, 시))
    if 번 not in (맥.가정.get("가정") or {}):
        return "—"
    시2 = _시(맥, 번) or 시
    열 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    값들 = [(c, _n(L._가정값(맥.가정, 번, 시2, c))) for c in 열]
    값들 = [(c, v) for c, v in 값들 if v is not None]
    if not 값들:
        return "—"

    def 칸(c):
        return _칸글(맥, 번, "A:%s:%s:%s" % (번, 시2, c))
    if len({round(v, 12) for _c, v in 값들}) == 1:
        return 칸(값들[0][0])
    # 양 끝 열이 0 이고 가운데에만 값이 있는 경로(2026-10-24 W10 · 회차 20261024 — 인원 증가율 21% → 5% 가 「0.0% → 0.0%」 로 찍혔다)
    #   → 값이 있는 구간의 첫 → 끝 + 「그 밖의 열 0」
    안 = [(c, v) for c, v in 값들 if abs(v) > 1e-12]
    덧 = ""
    if len(안) >= 2 and (abs(값들[0][1]) <= 1e-12 or abs(값들[-1][1]) <= 1e-12):
        값들, 덧 = 안, "(그 밖의 열 0)"
    if len(값들) <= 3:
        return " · ".join("%s %s" % (맥.열말(c), 칸(c)) for c, _v in 값들) + 덧
    return "%s %s → %s %s%s" % (맥.열말(값들[0][0]), 칸(값들[0][0]), 맥.열말(값들[-1][0]), 칸(값들[-1][0]), 덧)


def 근거글(맥, 번):
    """가정의 독자용 근거 — `독자근거` 가 있으면 그것, 없으면 `서사연결` 의 문장. 둘 다 없으면 빈 글(지어내지 않는다)."""
    번 = "%s" % 번
    독 = (맥.가정.get("독자근거") or {}).get(번)
    if _글(독):
        g = N.펴기(맥, 독, "독자근거.%s" % 번)
        if g:
            return g
    s = (맥.가정.get("서사연결") or {}).get(번)
    문 = s if isinstance(s, str) else (s or {}).get("문장") if isinstance(s, dict) else None
    if _글(문):
        g = N.펴기(맥, 문, "서사연결.%s" % 번)
        return (g + ".") if g and not g.endswith(".") else g
    return ""


def 시나리오칸(맥, 번, 시, 글, 기글):
    """가정 표의 비관 · 낙관 칸 — 모든 열의 값이 기준과 같을 때만 「같음」. 요약 글(첫 → 끝)이 같아도 가운데 열이 다르면 다른 열을 적는다
    (견본 실측: 2027 · 2028 년만 다른 CAPEX 가 「같음」 으로 찍혔다)."""
    if 글 != 기글:
        return 글
    L = _L()
    번 = "%s" % 번
    if 번 not in (맥.가정.get("가정") or {}):
        return "같음"
    열 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    시2, 기2 = (_시(맥, 번) or 시), (_시(맥, 번) or "기준")
    if 시2 == 기2:
        return "같음"

    def 다름(a, b):
        return (a is None) != (b is None) or (a is not None and abs(a - b) > 1e-12)
    다른 = [c for c in 열 if 다름(_n(L._가정값(맥.가정, 번, 시2, c)), _n(L._가정값(맥.가정, 번, 기2, c)))]
    if not 다른:
        return "같음"
    칸 = ["%s %s" % (맥.열말(c), _칸글(맥, 번, "A:%s:%s:%s" % (번, 시2, c))) for c in 다른[:3]]
    return " · ".join(칸) + (" 외 %d개 열" % (len(다른) - 3) if len(다른) > 3 else "")


def 가정표(맥, 번들, 머="가정"):
    """가정 표 — 가정 · 기준 · 비관 · 낙관(기준과 같으면 「같음」) · 근거(독자층). 값이 없는 가정은 뺀다."""
    줄들 = []
    for 번 in dict.fromkeys("%s" % b for b in 번들):
        if not 값있나(맥, 번):
            continue
        기 = 가정값글(맥, 번, "기준")
        비, 낙 = 가정값글(맥, 번, "비관"), 가정값글(맥, 번, "낙관")
        근 = 근거한줄(맥, 번)
        앞 = next((r[0] for r in 줄들 if r[5] == 근), None) if 근 else None       # 같은 근거 문장은 한 번만(2026-10-25 R7 — 표 칸의 되풀이는 편집이 못 고친다)
        줄들.append([이름(맥, 번), 기, 시나리오칸(맥, 번, "비관", 비, 기), 시나리오칸(맥, 번, "낙관", 낙, 기),
                   ("%s 같음" % P.과(앞)) if 앞 else (근 or "—"), 근])
    if not 줄들:
        return []
    줄들 = [r[:5] for r in 줄들]
    return P._표([머, "기준", "비관", "낙관", "근거"], 줄들, ["l", "r", "r", "r", "l"]) + [""]


def 절글(맥, 키):
    """저자 덧글 `Narrative.절글[키]` — 빈 자리에 붙일 줄들(매출 구분 소절처럼 조각을 따로 지을 때)."""
    return M.절글넣기(맥, 키, [])


def 덧글넣기(맥, L, *키들, 앞=None):
    """저자 덧글 `Narrative.절글[키]` 를 절 전체에 넣는다 — 「뒤」 가 있으면 그 글이 든 줄 다음, 없으면 끝(`레터막.절글넣기`).
    옛 다섯 막 · 깊이 층의 키(막3 · 공장 · 한계 …)도 그 내용이 옮겨 온 절에서 받는다.
    앞(줄 번호)을 주면 자료 · 분류 · 방법 문단은 그 자리(절 머리 바로 뒤)에 넣는다(2026-10-23 W3 — 사슬: 공시가 준 것 → 방법 → … → 범위 → 한계)."""
    자리 = [앞] if 앞 is not None else None
    for 키 in 키들:
        L = M.절글넣기(맥, 키, L, 앞=자리)
    return L


# ══════════════════════════════════════════════════════════════════ 근거 범위가 어디서 왔나 — 변수 카드(2026-10-23 W3)
# 항목 절마다 그 절 가정의 근거 범위 · 같은 업종 상장사 가운데 자리 · 상장사 실적의 움직임 · 업종 값과 회사 자료가 말한 몫을 한 표로.
# 재료(가정 곁 `_raw/변수카드.json` — `변수카드.py`)가 없거나 근거가 하나도 없는 가정은 줄을 세우지 않는다. 숫자는 장부 키 「파일:변수카드:…」.

_움직임말 = {"수렴형": "몇 해 안에 업종 평균 쪽으로 돌아간다", "느린수렴형": "천천히 업종 평균 쪽으로 돌아간다",
          "지속형": "한번 벌어진 수준이 오래 간다"}
