_변수말 = {"매출성장률": "매출 증가율", "영업이익률": "영업이익률", "영업이익률변화": "영업이익률의 변화", "자산회전율": "자산회전율",
        "자산회전율변화": "자산회전율의 변화", "총자산영업이익률": "총자산 영업이익률", "영업이익성장률": "영업이익 증가율",
        "매출채권비율": "매출 대비 매출채권", "재고비율": "매출 대비 재고자산", "CAPEX비율": "매출 대비 CAPEX", "상각률": "상각률",
        # 상세변수(2026-10-24 PM)
        "유효세율_3년": "실현 유효세율(3년)", "유효세율": "실현 유효세율", "유효세율_1년": "실현 유효세율", "평균유효세율_주석": "실현 유효세율",
        "영업이익률_5년평균": "5년 평균 영업이익률", "매출원가율": "매출원가율", "판관비율": "매출 대비 판매비와관리비",
        "재고회전일수_원가": "매출원가 대비 재고 일수", "매입채무회전일수": "매출원가 대비 매입채무 일수", "상각률_기초순액": "상각률",
        "평균내용연수": "평균 내용연수", "기계장치내용연수": "기계장치 내용연수", "설비계수": "설비 계수", "인원증가율": "인원 증가율",
        "1인평균급여": "공시 1인 평균 급여", "1인평균급여증가율": "1인 평균 급여 증가율", "인건비율": "매출 대비 인건비",
        "유지율_취득원가": "취득원가 대비 유형자산 취득", "산업평균연봉": "같은 산업 평균 연봉", "산업임금증가율": "같은 산업 임금 증가율"}


def 카드들(맥):
    """가정 곁 변수 카드 → {번호: (차례 i, 카드)}. 없으면 빈 dict."""
    v = (맥.원.get("파일") or {}).get("변수카드") or {}
    낸 = {}
    for i, c in enumerate(v.get("카드") or []):
        if isinstance(c, dict) and ("%s" % (c.get("번호") or "")).isdigit():
            낸.setdefault("%s" % c["번호"], (i, c))
    return 낸


def 항목절(맥, 번):
    """가정 번호 → 그 가정의 근거를 싣는 항목 절의 키(`레터이야기.절가정` 을 항목 절 단위로 다듬음 — 회전일수는 운전자본, 인원 · 급여는 인건비)."""
    try:
        n = int(번)
    except (TypeError, ValueError):
        return None
    인 = "인건비" if 맥.절.get("인건비") else "비용"
    if n in (178, 182, 186, 190) or 174 <= n < 194 or 900 <= n < 910:
        return "운전자본"
    if 500 <= n < 530 or n in (134, 138, 142):
        return 인
    if n in (168, 172, 701, 702, 703):
        return "비용"
    return N.절가정("%s" % n)


def _집단자리(c):
    """같은 집단 자리 가운데 하나 — 마지막 예측 열 · 가장 좁은 집단(전체 · 같은 규모가 아닌 집단 가운데 이름이 가장 긴 것)."""
    자 = [(j, a) for j, a in enumerate(c.get("같은집단자리") or []) if isinstance(a, dict) and _n(a.get("백분위")) is not None and _글(a.get("집단"))]
    끝 = [t for t in 자 if ("%s" % t[1].get("열")).startswith("끝")] or 자
    좁 = [t for t in 끝 if t[1]["집단"] != "전체" and not ("%s" % t[1]["집단"]).startswith("같은 규모")]
    후 = 좁 or [t for t in 끝 if ("%s" % t[1]["집단"]).startswith("같은 규모")] or 끝
    return max(후, key=lambda t: len("%s" % t[1]["집단"])) if 후 else None


def _범위원천(c):
    """근거 범위의 원천 — 동인 지도 판단 칸이 먼저, 없으면 결합 민감도 손잡이의 범위(변수카드 「결합범위」 · 2026-10-24 W10 — 영구성장률 · 영구기간 ROIC).
    → (장부 키 꼬리, 범위, 척도) 또는 None."""
    k = c.get("판단칸") or {}
    r = k.get("범위")
    if isinstance(r, list) and len(r) == 2 and all(_n(x) is not None for x in r):
        return "판단칸:범위", r, k.get("척도") or ""
    b = c.get("결합범위") or {}
    r = b.get("범위")
    if isinstance(r, list) and len(r) == 2 and all(_n(x) is not None for x in r):
        return "결합범위:범위", r, ""
    return None


def _범위쓰나(맥, 번, c):
    """근거 범위를 그 가정의 값 옆에 실어도 되나 — 수치 둘이고, 같은 잣대로 잰 범위로 보일 때만. 다른 잣대로 잰 범위를 값 옆에 세우면 독자가 오독한다.
    판정(2026-10-24 W10 — 종전 「크기의 절반」 은 너무 느슨해 원가율 28.6→32.4% 옆에 22.9~24.2% 가 실렸다):
      부호가 반대인 값이 범위 폭보다 크면 아니다 · **값 가운데 하나라도 범위 곁(폭의 1/4 안)에 있어야 한다** — 하나도 없으면 다른 잣대로 본다."""
    원 = _범위원천(c)
    if not 원:
        return False
    _꼬리, r, 척 = 원
    lo, hi = sorted(_n(x) for x in r)
    값 = [_n(v) for v in ((c.get("값") or {}).values() if isinstance(c.get("값"), dict) else []) if _n(v) is not None]
    if not 값:
        return False
    폭 = max(hi - lo, 0.1 * max(abs(lo), abs(hi)), 1e-9)
    for v in 값:
        if v * ((lo + hi) / 2.0) < 0 and abs(v) > 폭:
            return False
    return any(lo - 0.25 * 폭 <= v <= hi + 0.25 * 폭 for v in 값)


def _띠같은잣대(c, 띠, 값=None):
    """같은 집단 80% 띠를 그 가정의 값 옆에 실어도 되나(2026-10-24 PM — P1 성공 기준 ③) — 칸 단위 띠이고, 값 가운데 하나라도 띠 안이거나 띠 폭의 1/4 안.
    아니면 이름을 붙여 남긴다(빈칸 금지) — 정의가 다르면 「정의가 다름」, 정의가 같은데 값이 밖이면 숫자와 「띠 밖」.
    값 = 가정 칸의 값들(`_칸값들` — 동인 그래프 밖 칸 · 시점 칸도 잰다). 없으면 카드 값. 값을 하나도 못 읽으면 None(판정하지 않는다)."""
    if not 띠.get("칸단위"):
        return False
    lo, hi = sorted(_n(x) for x in 띠["범위"])
    if not 값:
        값 = [_n(v) for v in ((c.get("값") or {}).values() if isinstance(c.get("값"), dict) else []) if _n(v) is not None]
    if not 값:
        return None
    폭 = max(hi - lo, 1e-9)
    return any(lo - 0.25 * 폭 <= v <= hi + 0.25 * 폭 for v in 값)


def _칸값들(맥, 번):
    """가정 칸의 값들 — 시점 칸은 그 값, 그 밖은 예측 · 영구 열(그 칸이 쓰는 시나리오 · 기본 「기준」). 80% 띠 곁 판정용(`_띠같은잣대`)."""
    L = _L()
    번 = "%s" % 번
    if 번 in (맥.가정.get("시점가정") or {}):
        v = _n(L._시점값(맥.가정, 번, _시(맥, 번) or "기준"))
        return [v] if v is not None else []
    열 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    return [v for v in (_n(L._가정값(맥.가정, 번, _시(맥, 번) or "기준", c)) for c in 열) if v is not None]


def 전부0(맥, 번, 시="기준"):
    """가정의 모든 예측 · 영구 열 값이 0(또는 비었나) — 근거 표 줄을 세우지 않는 조건."""
    L = _L()
    번 = "%s" % 번
    if 번 in (맥.가정.get("시점가정") or {}):
        v = _n(L._시점값(맥.가정, 번, 시))
        return v is None or abs(v) <= 1e-12
    열 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    값 = [_n(L._가정값(맥.가정, 번, _시(맥, 번) or 시, c)) for c in 열]
    return all(v is None or abs(v) <= 1e-12 for v in 값)


def 근거표(맥, 번들, 절키=None):
    """「이 절 가정의 근거 범위가 어디서 왔나」 표 — 번들(차례대로) + 그 절 키의 카드. 근거가 하나도 없는 줄 · 값이 없는 가정은 뺀다."""
    카 = 카드들(맥)
    if not 카:
        return []
    차례 = list(dict.fromkeys("%s" % b for b in 번들))
    if 절키:
        차례 += [b for b in sorted(카, key=lambda x: int(x)) if b not in 차례 and 항목절(맥, b) == 절키]
    줄들, 쓴열, 띠포함키 = [], set(), None
    앞숫자, 이숫자 = set(getattr(맥, "_움직임숫자", None) or ()), set()     # 레터 v27 F6 — 앞 표들이 실은 (변수 · 집단 · 반감 숫자)
    for 번 in 차례:
        if 번 not in 카 or not 값있나(맥, 번):
            continue
        i, c = 카[번]
        if c.get("종류") not in (None, "가정") and not c.get("같은집단띠"):   # 거시 칸(임금상승률 등)은 상장사 띠가 있을 때만 줄을 세운다(2026-10-24 PM)
            continue
        키 = "파일:변수카드:카드:%d:" % i
        칸 = {}
        if _범위쓰나(맥, 번, c):
            꼬리 = _범위원천(c)[0]
            칸["범위"] = "%s ~ %s%s" % (_칸글(맥, 번, 키 + 꼬리 + ":0"), _칸글(맥, 번, 키 + 꼬리 + ":1"),
                                     "(가정을 함께 바꿔 본 범위)" if 꼬리.startswith("결합") else "")
        elif 전부0(맥, 번):                                  # 모든 열이 0 이고 범위도 없는 가정은 줄을 세우지 않는다(W10 — 매출 명칭 구분의 판가 변동률)
            continue
        자 = _집단자리(c)
        if 자:
            j, a = 자
            칸["자리"] = "%s 가운데 백분위 %s" % (맥.엔진글(키 + "같은집단자리:%d:집단" % j), 맥.식(["×", 키 + "같은집단자리:%d:백분위" % j, 100], "수0"))
        형 = (c.get("지속성형태") or {}).get("형태")
        if 형 in _움직임말:                                  # 무엇으로 쟀는지(패널의 변수)를 함께 — 가정과 다른 잣대면 독자가 안다
            지 = c.get("지속성형태") or {}
            변 = _변수말.get(지.get("변수"))
            글 = ("%s %s" % (P.은(변), _움직임말[형])) if 변 else _움직임말[형]
            # 레터 v27 F6 — 띠를 「정의가 다름」 으로 뺀 줄은 같은 변수의 움직임 숫자도 뺀다(형태 말만). 같은 (변수 · 집단 · 숫자)는 앞 표에서 실었으면
            #   숫자를 다시 싣지 않는다(이 표 안의 겹침은 아래 「위와 같음」)
            띠0 = c.get("같은집단띠")
            정의다름 = (isinstance(띠0, dict) and isinstance(띠0.get("범위"), list) and not 띠0.get("칸단위")
                     and (not 띠0.get("변수") or not 지.get("변수") or 띠0.get("변수") == 지.get("변수")))
            숫자키 = (지.get("변수"), 지.get("집단"), round(_n(지.get("반감햇수")) or 0.0, 1))
            if _n(지.get("반감햇수")) is not None and not 정의다름 and 숫자키 not in 앞숫자:     # 2026-10-25 R7 — 숫자(변수 카드 지속성 — 평균과의 차이가 절반이 되는 햇수 · 잰 집단)
                이숫자.add(숫자키)
                집 = (c.get("지속성형태") or {}).get("집단")
                글 += "(평균과의 차이가 절반이 되는 데 %s년%s)" % (맥.수(키 + "지속성형태:반감햇수", "수1"),
                                                     (" · %s" % 맥.엔진글(키 + "지속성형태:집단")) if 집 else "")
            칸["움직임"] = 글
        띠 = c.get("같은집단띠")
        if isinstance(띠, dict) and isinstance(띠.get("범위"), list):
            if 띠포함키 is None and _n(띠.get("포함")) is not None:
                띠포함키 = 키 + "같은집단띠:포함"                # 범례의 「80%」 를 장부 숫자로(게이트 ⑦)
            if 띠.get("칸단위"):                              # 정의가 같은 띠 — 숫자를 싣고, 값이 띠 밖이면 그렇다고 적는다(판단의 신호)
                칸["띠"] = "%s ~ %s(%d년 뒤 · %s%s)%s" % (_칸글(맥, 번, 키 + "같은집단띠:범위:0"), _칸글(맥, 번, 키 + "같은집단띠:범위:1"), 띠.get("k") or 1,
                                                       "비슷한 자리의 회사" if 띠.get("종류") == "지속성" else "같은 집단 전체",
                                                       " · 백테스트로 폭을 맞춤" if 띠.get("보정") else " · 보정 없음",
                                                       " · 이 값은 구간 밖" if _띠같은잣대(c, 띠, _칸값들(맥, 번)) is False else "")
            else:
                칸["띠"] = "정의가 다름 — %s 기준" % (_변수말.get(띠.get("변수")) or 띠.get("변수") or "상장사 자료")
        elif isinstance(띠, dict) and 띠.get("없음"):              # 대응 변수는 있는데 띠가 안 섰다 — 빈칸 대신 까닭
            칸["띠"] = "같은 정의의 상장사 자료 없음" if all("패널에 없음" in x for x in 띠["없음"]) else "같은 집단 표본이 모자라 분포 구간 없음"
        for j, s in enumerate(c.get("사전제안") or []):
            if isinstance(s, dict) and _n(s.get("값")) is not None:
                글 = "업종 값 %s" % _칸글(맥, 번, 키 + "사전제안:%d:값" % j)
                if _n(s.get("w")) is not None:
                    글 += " · 회사 자료가 말한 몫 %s" % 맥.수(키 + "사전제안:%d:w" % j, "퍼0")
                칸["업종"] = 글
                break
        if not 칸:
            continue
        딱 = c.get("출처딱지")
        칸["출처"] = 딱 if 딱 and 딱 != "미사용" else "—"
        쓴열 |= set(칸)
        줄들.append((번, 칸))
    if not 줄들:
        return []
    맥._움직임숫자 = 앞숫자 | 이숫자
    열들 = [(k, 말) for k, 말 in (("범위", "근거 범위"), ("자리", "같은 업종 상장사 가운데 백분위"), ("띠", "상장사 80% 구간"),     # v27 문장 — 표 머리 「자리 · 움직임」 → 「백분위 · 평균 회귀 속도」
                                 ("움직임", "상장사 실적에서 본 평균 회귀 속도"), ("업종", "업종 값과 회사 자료가 말한 몫"), ("출처", "출처")) if k in 쓴열]
    표줄 = [[이름(맥, 번), 가정값글(맥, 번)] + [칸.get(k) or "—" for k, _말 in 열들] for 번, 칸 in 줄들]
    if "움직임" in 쓴열:                                      # 2026-10-25 R7 — 같은 움직임 글(같은 변수로 잰 줄)은 두 번째부터 「위와 같음」
        j = 2 + [k for k, _말 in 열들].index("움직임")
        본 = set()
        for r in 표줄:
            if r[j] != "—" and r[j] in 본:
                r[j] = "위와 같음"
            본.add(r[j])
    # 레터 v27 문장 — 표의 읽는 법은 본문 문장이 아니라 표 제목(표 바로 위 「**표. 」 — 번호는 레터.py)과 표 주석(표 바로 아래 문단)으로
    첫표 = not getattr(맥, "_근거범례", False)                 # 읽는 법(주석)은 첫 표에 한 번(같은 문형을 되풀이하지 않는다)
    맥._근거범례 = True
    L = ["**표. %s**" % ("가정별 근거 범위와 그 출처" if 첫표 else "가정별 근거 범위"), ""]
    주 = []
    if 첫표:
        주 += ["백분위는 같은 업종 상장사를 그 비율의 크기순으로 나열했을 때 최종 예측 연도 가정값의 위치입니다. "
               "평균 회귀 속도는 상장사 실적에서 그 비율이 평균으로 돌아가는 속도입니다. 두 지표는 판단에 참고한 자료이며, 가정값을 직접 결정하지는 않습니다."]
    if "띠" in 쓴열 and not getattr(맥, "_띠범례", False):      # 80% 띠 열의 읽는 법 — 그 열이 처음 서는 표에 한 번
        맥._띠범례 = True
        if 띠포함키 is None:                                  # 이 표의 띠가 모두 「자료 없음」 이면 다른 카드의 포함 목표를 읽는다
            띠포함키 = next(("파일:변수카드:카드:%d:같은집단띠:포함" % i2 for i2, c2 in sorted(카.values(), key=lambda t: t[0])
                          if _n(((c2.get("같은집단띠") or {}).get("포함"))) is not None), None)
        팔 = 맥.수(띠포함키, "퍼0") if 띠포함키 else "80%"
        주 += ["%s 구간은 비교 대상 상장사의 %s 속한 범위입니다. 몇 년 뒤의 값을 비교했는지는 표에 함께 적었습니다." % (팔, P.이(팔)),
               "%s 구간은 현재의 대상회사와 백분위가 비슷했던 상장사로 먼저 산정했고, 그 자료가 부족하면 비교 대상 상장사 전체로 산정했습니다." % 팔,
               "「백테스트로 폭을 맞춤」은 과거 실적으로 검증해 실제로 %s 들어가도록 조정한 구간입니다. "
               "「보정 없음」은 그 검증을 통과하지 못했거나 자료 기간이 짧아 조정하지 않은 구간입니다." % P.이(팔),
               "「정의가 다름」은 상장사 자료의 정의가 가정과 달라 비교하지 않은 항목입니다. 「구간 밖」은 정의는 같지만 가정값이 %s 구간을 벗어난 항목입니다." % 팔]
    L += P._표(["가정", "이 평가의 값"] + [말 for _k, 말 in 열들], 표줄, ["l", "r"] + ["l"] * len(열들))
    L.append("")
    if 주:
        L += [" ".join(주), ""]
    return L


def _손잡이절(맥, 대상들):
    """결합 민감도 손잡이의 대상 → 항목 절 키(번호면 `항목절`, 이름이면 낱말로)."""
    for t in 대상들 or []:
        s = ("%s" % t).replace("A-", "")
        if s.isdigit():
            k = 항목절(맥, s)
            if k:
                return {"주주가치": None}.get(k, k)
        for 말, 키 in (("WACC", "할인율"), ("영구", "영구"), ("매출", "매출"), ("판매", "매출"), ("정상", "매출"), ("원가", "비용"), ("마진", "비용"),
                      ("이익률", "비용"), ("CAPEX", "재투자"), ("투자", "재투자"), ("상각", "재투자"), ("회전", "운전자본"), ("운전", "운전자본"), ("세율", "세금")):
            if 말 in s:
                return 키
    return None


_손잡이이름 = {"매출성장": "예측기간 매출 증가율", "영구ROIC": "영구기간 ROIC", "영구성장률": "영구성장률", "WACC.예측기간": "예측기간 WACC", "WACC.영구기간": "영구기간 WACC"}


def 결합몫글(맥, 절키):
    """근거 범위 안에서 가정을 함께 움직인 판들(결합 민감도)에서 이 절 가정이 주당가치 흔들림에서 차지한 몫 한 문장. 손잡이가 둘 미만이면 빈 목록."""
    결 = (맥.원.get("파일") or {}).get("결합민감도") or {}
    주 = (결.get("분해") or {}).get("주효과") or []
    손 = {h.get("이름"): h for h in 결.get("손잡이") or [] if isinstance(h, dict)}
    if len(주) < 2:
        return []
    고른, 이름들 = [], []
    for i, x in enumerate(주):
        if not isinstance(x, dict) or _n(x.get("몫")) is None:
            continue
        대 = (손.get(x.get("이름")) or {}).get("대상") or []
        if _손잡이절(맥, 대) != 절키:
            continue
        고른.append("파일:결합민감도:분해:주효과:%d:몫" % i)
        for t in 대:
            s = ("%s" % t).replace("A-", "")
            이 = 이름(맥, s) if s.isdigit() and 값있나(맥, s) else _손잡이이름.get(s)
            if 이 and 이 not in 이름들:
                이름들.append(이)
    if not 고른 or not 이름들 or (_n(맥.식값(["합"] + 고른)) or 0.0) < 0.01:      # 1% 미만이면 싣지 않는다(「0%를 설명했다」 는 소리만 낸다)
        return []
    # 레터 v27 문장(교열 74 · 138) — 「이 절에서 다룬 가정」 은 절 이름으로
    절말 = 절이름(맥, 절키) or _범위띠말.get(절키, "")
    return ["근거 범위 안에서 가정들을 동시에 바꿔 계산했을 때, 주당가치 변동의 %s %s 가정이 차지했습니다. 그 가정은 %s." % (
        P.을(맥.식(["합"] + 고른, "퍼0")), ("%s의" % 절말) if 절말 else "이 절의", _입니다(" · ".join(이름들[:3]) + (" 외 %d개" % (len(이름들) - 3) if len(이름들) > 3 else ""))), ""]


def 근거블록(맥, 번들, 절키):
    """항목 절 끝(가정 표 다음)에 붙는 근거 — 근거 표 · 그 절의 같은 집단 분포 그림 · 결합 민감도 몫 한 문장."""
    return 근거표(맥, 번들, 절키) + 범위띠그림(맥, 번들, 절키) + 출처붙여(맥, 분포자리그림, 맥, 절키) + 결합몫글(맥, 절키)     # 2026-10-25 R5 — 근거 범위 띠


# ══════════════════════════════════════════════════════════════════ 이음 — 앞 절에서 넘어온 값 → 이 절의 가정 → 다음 절로 넘기는 값

def _끝(맥):
    return 맥.끝예측


def 세액공제값있나(맥):
    """세액공제가 값으로 법인세를 움직이나(200 · 940 의 예측 열 · 941 평가기준일 잔액 가운데 0 아닌 값) — 절 머리 「세율과 세액공제를」 의 인쇄 조건.
    구조 스위치만 켜져 있고 값이 모두 0 인 회사에 세액공제를 말하지 않는다(2026-10-24 W10 · 회차 20261024)."""
    import 레터 as _L                                       # noqa: PLC0415
    for b in ("200", "940"):
        for 시 in ("비관", "기준", "낙관"):
            for 열 in getattr(맥, "예측열", None) or [맥.끝예측]:
                if _n(_L._가정값(맥.가정, b, 시, 열)):
                    return True
    return bool(_n(_L._시점값(맥.가정, "941", "기준")))


def 이음(맥, 키):
    """추정 절 머리 한 문단 — 그 절이 무엇을 바탕으로 어떻게 추정했는지와 그 결과 금액(장부 키). 해당하는 말이 없으면 빼고, 다 빠지면 빈 목록.
    레터 v27 문장(교열 56 · 76 · 92 · 93 · 101 · 102 · 112 · 118 · 119 · 139 · 273 · 274) — 「N절의 …를 받아 …를 정한다 · N절로 간다」(문서 · 모델을
    설명하는 말 · 사람처럼 행동하는 값)를 걷고 회사 · 금액을 주어로 합쇼체로 쓴다. 다른 절은 번호로 넘기지 않는다(필요하면 문장 끝 괄호)."""
    끝, TV = _끝(맥), 맥.영구열
    D = "R:기준:2.DCF:%s"
    글 = ""

    def 값들(이름, 키틀, TV있나=True):
        """「2030년 매출은 2,518억 원, 영구기간 매출은 2,556억 원으로 추정됩니다」."""
        앞 = "%s %s %s" % (맥.열말(끝), P.은(이름), 맥.수(키틀 % 끝, "금액"))
        if TV and TV있나:
            앞 += ", 영구기간 %s %s" % (P.은(이름), 맥.수(키틀 % TV, "금액"))
        return "%s 추정됩니다." % P.으로(앞)
    if 키 == "매출":
        # 경로를 따른다(2026-10-23 W3 — 증가율 경로 · 매출 명칭 회사에 「물량과 가격」 · 「과 판매량」 이 거짓으로 찍혔다)
        꼴, _물량 = 매출꼴(맥)
        한 = {"수준": "물량과 가격을", "판매량": "판매량과 판매단가의 증가율을", "섞임": "판매량과 판매단가의 증가율 또는 매출 증가율을",
             "매출": "매출 증가율을"}[꼴]
        글 = "매출은 매출 구분%s %s 가정해 추정했습니다. %s" % ("에 따라" if 꼴 == "섞임" else "마다", 한, 값들("매출", "R:기준:4.Sales:54:%s"))
    elif 키 == "비용":
        # 인쇄 조건(2026-10-24 W10 · 회차 20261024) — 「판매량」 은 판매량을 읽는 원가 줄이 있을 때만, 「설비 취득원가」 는 설비계수 산식(주 · 보조)이
        # 있을 때만. 「매출과 판매량과 …」 의 조사 겹침을 막으려고 같은 절의 둘은 가운뎃점으로 잇는다
        줄들 = 맥.구.get("원가줄") or []
        량 = any(x.get("산식") == "물량단위원가" or x.get("보조산식") == "물량단위원가"
                or (x.get("산식") == "매출액비율" and x.get("연동기준") == "판매량") for x in 줄들)
        설 = any(x.get("산식") == "설비계수" or x.get("보조산식") == "설비계수" for x in 줄들)
        앞 = [x for x in (("매출 · 판매량" if 량 else "매출") if 곳(맥, "매출") else "",
                         ("설비 취득원가 · 감가상각비" if 설 else "감가상각비") if 곳(맥, "재투자") else "",
                         "인건비" if 곳(맥, "인건비") else "") if x]
        글 = "영업비용은 %s 바탕으로 추정했습니다. %s" % (
            P.을(P._나열(앞)) if 앞 else "매출을", 값들("영업이익", D % "15:%s", TV있나=False))        # v27 — 영구기간 영업이익(15:TV)은 부록 D 의 같은 이름(43)과 값이 달라 싣지 않는다(⑱)
    elif 키 == "인건비":                                      # 인쇄 조건 — 인원 경로(물량연동이면 생산능력) · 성과급(없음이면 성과급 말을 빼고) · 미지급 성과급(미지급 항목에 있을 때)
        인 = 맥.구.get("인건비") or {}
        성 = (인.get("성과급") or "없음") != "없음"
        미성 = any(x.get("발생") == "성과급" for x in ((맥.구.get("운전자본") or {}).get("미지급항목") or []))
        받 = [x for x in ("인원은 생산능력에" if 인.get("인원경로") == "물량연동" else "",
                         "성과급은 성과급 차감 전 영업이익에" if 성 else "") if x]
        곳들 = [x for x in (곳(맥, "비용"), 곳(맥, "운전자본") if (성 and 미성) else "") if x]
        글 = "인건비는 인원 · 1인당 급여%s 가정해 추정했습니다. %s인건비는 영업비용에 포함했%s(%s)." % (
            " · 성과급을" if 성 else "를", ("%s 연동했습니다. " % ", ".join(받)) if 받 else "",
            "고, 미지급 성과급의 잔액 변화는 운전자본에 반영했습니다" if (성 and 미성) else "습니다", " · ".join(곳들))
        글 = 글.replace("()", "")
    elif 키 == "재투자":                                      # 인쇄 조건 — 설비 취득원가가 원가로 가는 것은 설비계수 산식의 원가 줄이 있을 때만
        능 = any(x.get("판매량산정") == "능력" for x in 맥.구.get("매출구분") or [])
        설 = [x.get("이름") for x in 맥.구.get("원가줄") or [] if x.get("산식") == "설비계수" and x.get("이름")]
        일정 = 능 or bool((맥.구.get("투자") or {}).get("프로젝트"))     # 인쇄 조건(W10) — 라인 · 프로젝트 일정이 없으면 유지 투자만이다
        글 = "%s FCFF를 계산할 때 감가상각비는 더하고 CAPEX는 뺐습니다.%s" % (
            ("투자 일정은 공장별 생산능력 일정에 맞춰 정했습니다." if 능 else "투자 일정은 매출 추정에 맞춰 정했습니다.") if 일정 else "유지 투자는 매출 추정에 맞춰 정했습니다.",
            (" 설비 취득원가는 %s 추정에 반영했습니다%s." % (P._나열(설), ("(%s)" % 곳(맥, "비용")) if 곳(맥, "비용") else "")) if 설 else "")
    elif 키 == "운전자본":
        글 = "운전자본 잔액은 매출과 매출원가에 회전일수를 적용해 추정했습니다. FCFF를 계산할 때 순운전자본 증가액은 빼고 감소액은 더했습니다.%s" % (
            " 미지급 항목 증감도 FCFF에 반영했습니다." if (맥.구.get("운전자본") or {}).get("미지급항목") else "")
    elif 키 == "세금":
        글 = "영업이익에 %s 적용해 NOPLAT을 산정했습니다. NOPLAT에서 설비투자와 운전자본의 재투자를 빼면 FCFF입니다. 예측기간 FCFF의 현재가치 합은 %s." % (
            "세율과 세액공제를" if 세액공제값있나(맥) else "세율을", P.입니다(맥.수(D % "40", "금액")))
    elif 키 == "할인율":
        글 = "FCFF와 Terminal Value는 WACC 값으로 할인해 현재가치로 환산했습니다. WACC 값은 예측기간 %s, 영구기간 %s 산정했습니다." % (     # 「WACC」 뒤에 조사를 바로 붙이지 않는다(문체 검수)
            맥.수("R:기준:WACC:예측기간:WACC", "퍼2"), P.으로(맥.수("R:기준:WACC:영구기간:WACC", "퍼2")))
    elif 키 == "영구":
        # 영구기간 손익의 출발은 구조를 따른다(2026-10-23 — 수준 경로가 없는 회사에도 「판매량과 정상 수준 가격」 이 찍혔다)
        수준 = any(x.get("경로") == "수준" and (x.get("번호") or 6) < 6 for x in 맥.구.get("매출구분") or [])
        입력 = ((맥.구.get("영구가치") or {}).get("영구이익기준") == "입력")
        손익말 = ("영구기간 손익은 최종 예측 연도 말의 매출에 Normalization 영업이익률을 적용해 추정했습니다." if 입력 else
                ("영구기간 손익은 최종 예측 연도 말의 판매량과 정상 수준 가격, 정상 수준의 원가에서 추정했습니다." if 수준 else
                 "영구기간 손익은 최종 예측 연도 말의 매출과 원가에서 추정했습니다."))
        # 2026-11-01 — 같은 이름에 값 둘을 막는다(게이트 ⑱): 「Terminal Value의 현재가치」 는 표 · 가치 브리지와 같은 54행이고, 영업가치에서
        # 예측기간 현재가치를 뺀 몫(58 − 40)이 그와 다르면(그 밖의 영업가치 조정) 그 값은 「조정 후」 로 이름을 갈라 덧붙인다
        if _n(맥.값(D % "58")) is None:
            값말 = ""
        else:
            뒤몫 = _n(맥.식값(["−", D % "58", D % "40"])) or 0.0
            tv = _n(맥.값(D % "54"))
            if tv is not None and abs(뒤몫 - tv) <= 1e-6 * max(1.0, abs(tv)):
                값말 = 맥.수(D % "54", "금액")
            elif tv is not None:
                값말 = "%s(영업가치 조정을 더한 조정 후 %s)" % (맥.수(D % "54", "금액"), 맥.식(["−", D % "58", D % "40"], "금액"))
            else:
                값말 = 맥.식(["−", D % "58", D % "40"], "금액")
        글 = 손익말 + " 재투자는 영구성장률과 영구기간 ROIC으로 산정했습니다." + ((" Terminal Value의 현재가치는 %s." % P.입니다(값말)) if 값말 else "")
    elif 키 == "주주가치":
        글 = ("영업가치 %s FCFF의 현재가치와 Terminal Value의 현재가치를 더한 금액입니다. "
             "주주가치는 영업가치에 비영업자산과 현금을 더하고 이자부부채 등을 빼서 산정했습니다." % P.은(맥.수(D % "58", "금액")))
    if not 글:
        return []
    return [re.sub(r"\s+", " ", 글).strip(), ""]


# ══════════════════════════════════════════════════════════════════ 1. 결론

def 결론절(맥, 번):
    """1절 — 두괄식(2026-10-25 R2 · 계약 0절 3): 띠 → (DCF 적합성 고지) → 결론 다섯 줄(`레터이야기.결론줄들` — 3분 레터 맨 앞과 같은 글) →
    세 시나리오 표 → 종가 행 풀이 · 보조 시나리오 · 가르는 가정의 근거와 값이 있는 절. 결론 줄이 없는 판(옛 짜임)은 종전처럼 기준 · 범위 문장으로 연다."""
    L = 머리("결론", 번)
    b = T.바닥(맥)
    L += ["<!-- 합본:3분과같음 -->", ""]                       # 2026-10-26 합본 — 결론 다섯 줄은 3분 레터와 같은 글(합친 한 장에서는 3분 레터로 갈음)
    띠줄 = T.띠(맥, b)                                       # 2026-10-31 L8 — 띠는 3분 레터에 없다(3분 레터의 표는 손익 요약 하나) — 합본 표지 밖에 둔다
    기 = "R:기준:2.DCF:68"
    이름들 = ((맥.가정.get("서술") or {}).get("이름") or {})

    def 시이름(s):
        나 = 맥.원고글(이름들.get(s), "서술.이름.%s" % s) if _글(이름들.get(s)) else ""
        return "%s 시나리오%s" % (s, (" 「%s」" % 나) if 나 else "")
    적 = T.적합성글(맥, "깊이")                              # 2026-10-25 — DCF 적합성 경보(`DCF적합성.py`) — 값보다 먼저 그 값이 무엇에 매달리는지
    if 적:
        L += [" ".join(적), ""]
    줄 = N.결론줄들(맥)
    if 줄:
        for _자리, 글 in 줄:
            L += [글, ""]
        L += ["<!-- /합본:3분과같음 -->", ""]
    else:
        L += ["<!-- /합본:3분과같음 -->", ""]
        문 = ["%s의 주당가치는 %s." % (시이름("기준"), P.입니다("%s(약 %s)" % (맥.수(기, "주당"), 맥.수(기, "어림주당"))))]
        문.append("주당가치의 범위는 %s의 %s에서 %s의 %s까지입니다." % (시이름("비관"), 맥.수("R:비관:2.DCF:68", "주당"), 시이름("낙관"), 맥.수("R:낙관:2.DCF:68", "주당")))
        L += [" ".join(문), ""]
    L += 띠줄
    날 = T.날짜들(맥).strip()                                  # 2026-10-31 L8 — 날짜 문장은 3분 레터에서 1절로
    if 날:
        L += P.고지싸기([날])                                 # 1.1.20 — 평가 날짜 · 자료 날짜 문장은 기준일 고지라 고지 표지 안에(구조 검사 ④ 가 빼고 잰다)
    보 = T.보조시나리오들(맥)
    머 = ["구분", "주당가치", "주주가치"] + (["%s 대비" % P.종가말(맥)] if 맥.종가키 else [])
    줄들 = []
    for s in ("비관", "기준", "낙관"):
        줄_ = [시이름(s), 맥.수("R:%s:2.DCF:68" % s, "주당"), 맥.수("R:%s:2.DCF:66" % s, "금액")]
        if 맥.종가키:
            줄_.append(맥.식(["÷", "R:%s:2.DCF:68" % s, 맥.종가키], "퍼0"))
        줄들.append(줄_)
    for 이, 키 in 보:
        줄_ = ["%s(보조 시나리오)" % 이, 맥.수(키, "주당"), "—"]
        if 맥.종가키:
            줄_.append(맥.식(["÷", 키, 맥.종가키], "퍼0"))
        줄들.append(줄_)
    if 맥.종가키:
        줄들.append([P.종가말(맥), 맥.수(맥.종가키, "주당"), 맥.식(["÷", ["×", 맥.종가키, P.주식키(맥)],         # 날짜 둘 — 평가기준일 주식 수
                                                                   "상:%d" % int(_L().단위배(맥.메타))], "금액"), 맥.수("상:1", "퍼0")])
    L += ["**표. 세 시나리오의 주당가치와 주주가치**", ""] if 줄 else []          # v27 문장(교열 14 · 15) — 표 설명은 표 제목 · 표 주석으로
    L += P._표(머, 줄들, ["l", "r", "r"] + (["r"] if 맥.종가키 else []))
    L.append("")
    if 맥.종가키:
        L += ["%s의 주주가치는 그 주가에 적용 주식수를 곱한 시가총액입니다." % P.종가말(맥), ""]
    if 맥.종가키 and b and b["풀이"] and _n(맥.값("가:역셀:%d:2.DCF:43" % b["i"])) is not None:
        L += ["영구기간 영업이익은 기준 시나리오에서 %s이고, %s 성립하려면 %s 필요합니다." % (맥.수("R:기준:2.DCF:43", "금액"), P.이(P.종가말(맥)),
                                                                     P.이(맥.수("가:역셀:%d:2.DCF:43" % b["i"], "금액"))), ""]
    elif 맥.종가키 and not 줄:
        L += ["%s %s." % (P.은(P.종가말(맥)), P.입니다(맥.수(맥.종가키, "주당"))), ""]
    낙키 = "R:낙관:2.DCF:68"
    if (맥.종가키 and P._밖파일(맥) and (_n(맥.값("가:밖:틈")) or 0) > 0 and 맥.절.get("역산")
            and (_n(맥.값(맥.종가키)) or 0) > (_n(맥.값(낙키)) or 0)):
        # 2026-11-01 — 3분 레터가 결론 다섯 줄 · 손익 요약으로 줄면서 빠진 「공시 밖 사업이 메워야 할 값」 한 줄을 본편 1절에 둔다(역산 절로 잇는다)
        L += [P.갭문장(맥), ""]
    for 이, 키 in 보:
        L += ["보조 시나리오 %s의 주당가치는 %s." % (이, P.입니다(맥.수(키, "주당"))), ""]
    문 = []
    동 = N.동인글(맥, "깊이")
    if 동:
        문 += 동[:2]
    근곳, 값곳 = 축안내(맥)                              # 인쇄 조건 — 그 가정이 실제로 서는 절만(견본 실측: 민감도 · 역산에 없는 축에 「14절 · 15절」)
    # v27 문장(교열 16 · 검토 메모 2) — 다른 절은 이름으로 부르고 번호는 문장 끝 괄호로만
    번이름 = {곳(맥, k): 절이름(맥, k) for k in 맥.절 if k in 제목 and 곳(맥, k)}
    근말, 값말 = 번이름.get(근곳, ""), P._나열([번이름.get(x, "") for x in 값곳])
    if N.지렛대(맥) and 근곳 and 값곳 and 근말 and 값말:
        문.append("주당가치를 좌우하는 가정의 근거와 범위는 %s에서, 그 가정을 바꿨을 때의 주당가치는 %s에서 다룹니다(%s)." % (
            근말, 값말, " · ".join([근곳] + list(값곳))))
    elif N.지렛대(맥) and 근곳 and 근말:
        문.append("주당가치를 좌우하는 가정의 근거와 범위는 %s에서 다룹니다(%s)." % (근말, 근곳))
    if 문:
        L += [" ".join(문), ""]
    # 2026-10-31 L8 — 3분 레터에서 내려온 말 풀이 · 낱말(1절이 3분 레터를 다시 싣지 않는다 — 결론 다섯 줄만 ⑯ 대조로 같은 글을 둔다)
    풀 = T._말풀이(맥)
    if len(풀) > 3:
        L += 풀
    낱 = T.낱말(맥)
    if 낱:
        L += [낱, ""]
    # v27 문장(교열 23) — 「두 쪽짜리 요약본(3분 레터)은 … 따로 냈다」 는 지웠다(3분 레터가 같은 문서의 앞에 있다).
    # 주당가치와 정상 수준의 그림(자)은 역산 절에 한 번(모션 M3 의 짝)
    맥.서술("요약")
    return L


def 축안내(맥):
    """→ (근거 절, [값이 바뀔 때를 보이는 절]) — 값을 가르는 가정(`레터이야기.지렛대` — 2026-10-25 R3)이 실제로 서는 절.
    근거 절은 그 가정을 숫자로 옮기는 항목 절, 값 절은 그 가정이 민감도 표 Ⅲ · 역산 표 Ⅳ 의 손잡이 대상이거나 근거 범위 후보(시나리오 · 토네이도)면
    민감도 절, 역산 표 Ⅳ 면 역산 절, 시나리오 driver 면 시나리오 절."""
    d = N.지렛대(맥) or {}
    번들 = ["%s" % x for x in d.get("번호들") or []]
    if not 번들:
        return "", []
    민 = 맥.민 or {}

    def 든(표):
        줄 = 민.get(표)
        줄 = 줄 if isinstance(줄, list) else (줄 or {}).get("줄") or []
        return any(set("%s" % t for t in (r.get("대상") or [])) & set(번들) for r in 줄 if isinstance(r, dict))
    근 = next((곳(맥, 항목절(맥, b) or N.절가정(b)) for b in 번들 if 곳(맥, 항목절(맥, b) or N.절가정(b) or "")), "") or \
        (곳(맥, "할인율") if "WACC" in 번들 else 곳(맥, "매출"))
    값 = [x for x, 있 in ((곳(맥, "민감도"), 든("표3") or d.get("잣대") in ("시나리오", "범위", "대안")), (곳(맥, "역산"), 든("표4"))) if x and 있]
    if not 값:
        이야기 = 맥.가정.get("시나리오이야기") or {}
        if any(set("%s" % d_ for d_ in ((이야기.get(s) or {}).get("driver") or [])) & set(번들) for s in ("비관", "낙관")) and 곳(맥, "시나리오"):
            값 = [곳(맥, "시나리오")]
    return 근, 값


# ══════════════════════════════════════════════════════════════════ 2. Narrative — 세 문단, 문단마다 그 판단이 간 가정

def _연결이름(맥, 절키, n=3):
    """서사연결 가운데 그 절(매출 · 비용 · …)의 가정 이름 — 값을 크게 움직이는 차례로 n 개(이름 묶기)."""
    줄들 = [x for x in N.연결줄들(맥) if any(N.절가정(b) == 절키 for b in x["번호들"])]
    줄들 = sorted(줄들, key=lambda x: -N._연결점수(맥, x["번호들"]))
    번들 = []
    for x in 줄들:
        for b in x["번호들"]:
            if N.절가정(b) == 절키 and b not in 번들:
                번들.append(b)
    이름들 = list(dict.fromkeys(N.가정말(맥, b) for b in 번들))
    if not 이름들:
        return ""
    for k in range(min(n, len(이름들)), 0, -1):              # 레터 v27 6단계 — 「→ 이 판단은」 줄이 120자를 넘지 않게 이름이 길면 앞에서부터 줄인다
        글 = N.이름묶기(맥, 이름들[:k])
        if len(글) <= 연결이름상한 or k == 1:
            return 글
    return ""


연결이름상한 = 72                                            # 「→ 이 판단은 「<절 이름>」의 … 가정에 반영했습니다(<n>절).」 의 이름 몫 — 문장 120자 안


def _시나리오축(맥, n=3):
    """시나리오를 가르는 축 — 폭포의 묶음 가운데 걸음이 큰 차례로 n 개의 이름."""
    걸 = N.폭포걸음(맥)
    if not 걸:
        return ""
    고른 = sorted(걸.items(), key=lambda t: -t[1])[:n]
    return P._나열([P._묶음이름(맥, 이) for (이, _b), _v in 고른])


def 연결줄(맥, 절키, 이름들):
    if not 이름들 or not 곳(맥, 절키):
        return []
    # v27 문장 — 판단이 가정으로 「간다」(사람처럼 행동하는 판단)를 「반영했습니다」 로, 절 번호는 문장 끝 괄호로(검토 메모 2)
    return ["→ 이 판단은 「%s」의 %s 가정에 반영했습니다(%s)." % (제목[절키].split(" : ")[0], 이름들, 곳(맥, 절키)), ""]


def 접속어로여나(글):
    """원고 조각이 접속 부사로 여는가(1.1.20 — ADDER80 백테스트: 교열이 「그러나 …」 를 「또한 …」 으로 고치자 코드가 「그러나 또한 …」 을 찍었다).
    낱말 목록이 아니라 꼴로 본다 — 첫 어절이 한글 두 ~ 네 글자이고 조사(은 · 는 · 이 · 가 · 을 · 를 · 의 · 에 · 로 · 와 · 과 · 도)로 끝나지 않으며 바로 뒤에
    띄어쓰기가 오면 접속 부사로 본다(문장을 여는 명사구는 조사를 단다). 지시어 「그」 에서 온 접속 부사(그러나 · 그런데 · 그럼에도 · 그렇지만 · 그래서)는
    조사 꼴로 끝나도 참이다."""
    t = ("%s" % (글 or "")).strip()
    if t.startswith("그러나") or re.match(r"^그(?:러|런|럼|렇|래)[가-힣]{0,3}[,]?\s", t):
        return True
    m = re.match(r"^([가-힣]{2,4})[,]?\s", t)
    return bool(m) and not re.search(r"[은는이가을를의에로와과도]$", m.group(1))


def 서사절(맥, 번):
    L = 머리("Narrative", 번)
    Nn = _N(맥)
    첫 = [x for x in (N.펴기(맥, Nn.get("정체성"), "Narrative.정체성"), N.펴기(맥, Nn.get("구성"), "Narrative.구성")) if x]
    둘 = []
    우 = N.펴기(맥, Nn.get("우위"), "Narrative.우위")
    그 = N.펴기(맥, Nn.get("그러나"), "Narrative.그러나")
    if 우:
        둘.append(우 if (우.startswith("강점") or N.주제말있나(우)) else "강점은 %s" % 우)     # v27 구조 ⑧ — 원고 문장에 제 주제어가 있으면 머리말을 잇지 않는다
    if 그:
        둘.append(그 if 접속어로여나(그) else "그러나 %s" % 그)      # 1.1.20 — 원고가 접속 부사(「또한」 · 「다만」 …)로 열면 「그러나」 를 덧붙이지 않는다
    if not 첫 and not 둘 and 맥.개요:
        첫 = 맥.개요[:1]
        둘 = 맥.개요[1:2]
    if 첫:
        L += [" ".join(첫), ""] + 연결줄(맥, "매출", _연결이름(맥, "매출"))
    if 둘:
        L += [" ".join(둘), ""] + 연결줄(맥, "비용", _연결이름(맥, "비용") or "원가")
    셋 = N.생애주기문단(맥)
    틀, 이 = N.틀림문장(맥)
    # 1.1.21 — 셋째 판단 문단에 1절 결론의 「주당가치를 가장 크게 좌우하는 가정은 …」 을 다시 찍지 않는다(반복 · 원칙 11 · ADDER80 백테스트) —
    #   생애주기 문단이 있으면 그 문단만, 없으면 문단을 세우지 않는다(그 가정 이름은 1절 결론 · 17절 「먼저 틀릴 가정」 이 이미 말한다. 앞부분 점검은 판단 문단마다
    #   「→ 이 판단은」 이 붙었는지만 본다 — 문단 둘이면 줄 둘)
    if 셋:
        L += [셋[0].strip(), ""] + 연결줄(맥, "시나리오", _시나리오축(맥) or 이)
    elif 이 and not (첫 or 둘):                              # 앞의 두 판단 문단이 없는 판 — 이 문단이 Narrative 의 유일한 판단(「→ 이 판단은」 이 기댈 문장)이다.
        #                                                      이름은 저자 선언(`Narrative.틀림.가정`)이라 그 뜻대로 「먼저 틀릴 가정」(「가장 크게 좌우」 는 결론 지렛대의 말)
        L += ["이 평가가 틀린다면 먼저 틀릴 가정은 %s." % P.입니다(이), ""] + 연결줄(맥, "시나리오", _시나리오축(맥) or 이)
    elif 맥.개요[2:3]:
        L += [맥.개요[2], ""] + (연결줄(맥, "시나리오", _시나리오축(맥)) if _시나리오축(맥) else [])
    위 = [(i, x) for i, x in enumerate((맥.가정.get("관측") or {}).get("위험") or []) if isinstance(x, dict) and _글(x.get("위험"))]
    if 위:                                                   # 사실 · 위험 · 모니터링 · 출처 네 목록. 위험은 ②(우위가 깨지는 지점) 바로 뒤에 ·
        #                                                      소제목 아래에 둔다(앞부분점검이 세는 「판단 문단」 은 그림 · 표 · 머리 앞까지 — 표 머리 글이 판단 문단으로 세어지지 않게)
        L += ["### 주요 위험과 전파 경로", "", "**표. 주요 위험, 그 위험이 가정에 미치는 경로, 선행 지표**", ""]     # v27 문장(교열 24) — 표 제목으로
        L += P._표(["위험", "근거", "전파 경로", "선행 지표", "그 위험만 켰을 때 주당가치"],
                  [[맥.원고글(x.get("위험")) + ((" " + 맥.원고글(x.get("태그"))) if _글(x.get("태그")) else ""), 맥.원고글(x.get("근거") or "—"),
                    N.펴기(맥, x.get("전파") or "—", "관측.위험[%d].전파" % i), N.펴기(맥, x.get("선행지표") or "—", "관측.위험[%d].선행지표" % i),
                    위험영향칸(맥, i, x)] for i, x in 위], ["l", "l", "l", "l", "r"]) + [""]     # 1.1.4(R12 · R21) — 표 칸도 장부 키(「{키|꼴}」)를 편다
    # 2026-10-31 L1 — 사이클 위치 그림(시계)은 업황 절로 옮겼다(외부 관측 지표 셋 이상이 있을 때만 — `업황절`).
    # 독법 단락은 Narrative 세 판단 문단(「→ 이 판단은」 이 붙는 문단)과 갈라 소제목 아래에 둔다 — 종전에는 시계 그림이 그 사이를 갈랐다(⑬ 앞부분 다섯)
    독 = M.독법문단(맥)
    if 독:
        L += ["### 같은 사실을 읽는 법", ""] + 독
    표 = N.연결표(맥)
    if 표:                                                   # 2026-10-31 — 소제목 아래에 둔다(시계 그림이 업황 절로 옮겨 세 판단 문단과 이 안내문 사이가 비었다 · ⑬ 앞부분 다섯)
        L += ["### 가정으로 간 Narrative 문장", ""]
        전부수 = len(N.연결줄들(맥))
        표줄수 = sum(1 for x in 표 if x.startswith("| ") and not x.startswith("| Narrative |"))
        # v27 문장(교열 25 · 26) — 표 제목으로. 1.1.20 — 「나머지 Narrative 문장 N개는 부록 I에 있습니다」(문서 안내 · 원칙 3 — 서른 곳 모두 같은 글)를 지우고
        # 몇 개 가운데 몇 개를 실었는지를 표 제목에 둔다(정보는 남는다 · 부록 차례가 자리를 말한다)
        L += ["**표. 주당가치에 영향이 큰 Narrative 문장과 그 문장을 반영한 가정%s**" % (
            "(%d개 가운데 %d개)" % (전부수, 표줄수) if 전부수 > 표줄수 else ""), ""]
        L += 표
        if 표 and 표[-1] != "":
            L += [""]
        맥.서술("Narrative.표")
    밖 = N.값밖문단(맥)
    if 밖:                                                   # 2026-10-31 — 판단 문단과 가른다(시계 그림이 업황 절로 옮겨 이 문단이 판단 문단으로 세어졌다 · ⑬ 앞부분 다섯)
        L += ["### 값에 넣지 않은 것", ""] + 밖
    맥.서술("Narrative")
    return L


def 위험영향칸(맥, i, x):
    """1.1.2 — 위험 표의 「그 위험만 켰을 때 주당가치」: 원고 `관측.위험[i].바꿈`(반대 논거와 같은 꼴 — 가정 · 방식 · 값)을 엔진으로 셈한 값
    (장부 키 「위:i」 — 기준 대비 %와 함께). 바꿈이 없으면 `영향없음`(셈하지 않은 까닭) 글, 둘 다 없으면 「—」(원고 요건이 막는다)."""
    import 레터 as _L                                       # noqa: PLC0415
    if x.get("바꿈") or x.get("가정") is not None:
        try:
            _L.반대바꿈(x)
        except Exception as e:                               # noqa: BLE001
            맥.알림.append("관측.위험[%d] — %s" % (i, e))
            return "—"
        try:                                                 # 1.1.8 — 위험 하나만 켠 값이 비관 시나리오보다 낮으면 알린다(열을 하나만 주면 뒤 해는 기준값으로 남는다)
            v, 비 = _n(맥.값("위:%d" % i)), _n(맥.값("R:비관:2.DCF:68"))
        except Exception:                                    # noqa: BLE001 — 알림을 못 내도 칸은 찍는다
            v = 비 = None
        if v is not None and 비 is not None and v < 비:
            맥.알림.append("관측.위험[%d] — 그 위험만 켠 주당가치가 비관 시나리오 주당가치보다 낮다 — 바꿈의 값 · 열이 비관 경로보다 가혹하지 않은지 본다"
                         "(의도한 꼬리 위험이면 위험 근거에 그 까닭)" % i)
        return "%s (%s)" % (맥.수("위:%d" % i, "주당"), 맥.식(["괴리", "위:%d" % i, "R:기준:2.DCF:68"], "증1"))
    if _글(x.get("영향없음")):
        return 맥.원고글(x["영향없음"], "관측.위험[%d].영향없음" % i)
    return "—"


# ══════════════════════════════════════════════════════════════════ 업황과 경쟁 — 사이클 위치 · 수급 · 경쟁 위치 (2026-10-31 요건판 3 · 독립 검토 L1 · L2)

def _관(맥, 키):
    관 = 맥.가정.get("관측") if isinstance(맥.가정.get("관측"), dict) else {}
    return 관.get(키)


def _원표(맥, 표, 자리):
    """원고의 {머리, 줄} 표 → 마크다운 줄(칸 글은 원고글 — 문체 검수 · 장부). 꼴이 틀리면 빈 목록."""
    if not (isinstance(표, dict) and isinstance(표.get("머리"), list) and isinstance(표.get("줄"), list)):
        return []
    머 = [맥.원고글("%s" % h, "%s.머리" % 자리) for h in 표["머리"]]
    줄들 = [[(N.펴기(맥, "%s" % c, "%s.줄" % 자리) or "—") if c not in (None, "") else "—" for c in r] for r in 표["줄"] if isinstance(r, list)]     # 칸의 장부 자리표시를 편다
    줄들 = [r + ["—"] * (len(머) - len(r)) for r in 줄들]
    if not 줄들:
        return []
    수꼴 = re.compile(r"^[−+\-]?[\d,.]+\s*(%|%p|배|일|년)?$")
    정렬 = ["l"] + ["r" if all(수꼴.match(("%s" % r[j]).strip()) or ("%s" % r[j]).strip() in ("—", "") for r in 줄들) else "l" for j in range(1, len(머))]
    return P._표(머, 줄들, 정렬) + [""]


def 업황지표표(맥):
    """외부 관측 지표 표 — 지표 · 지금 값(기준일) · 읽기 · 출처. 출처가 이 평가의 가정뿐인 줄은 싣지 않는다(`레터원고._업황지표셈` 과 같은 판정)."""
    import 레터원고 as W                                     # noqa: PLC0415
    v = _관(맥, "업황지표")
    셈, _까 = W._업황지표셈(v)
    줄들 = []
    for x in v if isinstance(v, list) else []:
        if isinstance(x, dict) and ("%s" % (x.get("지표") or "")).strip() in 셈:
            줄들.append([맥.원고글(x.get("지표")), 맥.원고글(W.업황지표말.get(x.get("종류"), x.get("종류"))),
                       "%s(%s)" % (맥.원고글("%s" % x.get("값")), 맥.원고글("%s" % x.get("기준일"))), 맥.원고글(x.get("읽기")), 맥.원고글(x.get("출처"))])
    if not 줄들:
        return []
    # 1.1.20 — 「사이클 위치는 외부 관측 지표 N개로 판정했습니다. 예측기간의 가정은 이 판정에 맞춰 설정했습니다.」(서른 곳 모두 같은 방법 설명 · 원칙 12)를
    # 표 제목으로 옮겼다. 판정과 그 판정이 간 가정은 바로 뒤 원고 문단이 쓴다
    return (["**표. 사이클 위치를 판정한 외부 관측 지표 %d개**" % len(줄들), ""]
            + P._표(["지표", "종류", "지금 값(기준일)", "읽기", "출처"], 줄들, ["l", "l", "l", "l", "l"]) + [""])


def 과거사이클표(맥):
    """과거 사이클을 시작 계기 · 증설 · 종료 계기로 되짚고 지금과 견준 표. 해당없음이면 그 까닭 한 문장."""
    import 레터원고 as W                                     # noqa: PLC0415
    v = _관(맥, "과거사이클")
    까 = W.해당없음글(v)
    if 까:
        return [맥.원고글(까, "관측.과거사이클.해당없음"), ""]
    줄들 = []
    for x in v if isinstance(v, list) else []:
        if not isinstance(x, dict) or not _글(x.get("사이클")):
            continue
        줄들.append([맥.원고글(x.get("사이클")) + (" ◀ 지금" if x.get("지금") is True and "지금" not in ("%s" % x.get("사이클")) else ""), 맥.원고글(x.get("시작계기") or "—"),
                   맥.원고글(x.get("증설") or "—"), 맥.원고글(x.get("종료계기") or ("아직" if x.get("지금") is True else "—")),
                   맥.원고글(x.get("출처") or "—")])
    if not 줄들:
        return 지난낙폭(맥)
    return (["**표. 지난 사이클과 현재의 비교: 시작 계기 · 증설 · 종료 계기**", ""]     # v27 문장(교열 29) — 표 제목으로
            + P._표(["사이클", "시작 계기", "증설", "종료 계기", "출처"], 줄들, ["l", "l", "l", "l", "l"]) + [""] + 지난낙폭(맥))


def 지난낙폭(맥):
    """과거 사이클 소절 끝의 낙폭 한 문장 — 저자가 `Narrative.독자.지난사이클`({"이름", "낙폭"})을 적었을 때만(2026-11-01 — 3분 레터에서
    내린 문장을 본편 업황과 경쟁 절로 옮겼다). 없으면 아무것도 싣지 않는다."""
    지 = T._독자(맥).get("지난사이클")
    if not (isinstance(지, dict) and _n(지.get("낙폭")) is not None and _글(지.get("이름"))):
        return []
    이 = 맥.원고글(지["이름"], "Narrative.독자.지난사이클.이름")
    if not 이:
        return []
    b = T.바닥(맥)
    말 = (T.가격말(맥, b) if b else "") or "판매단가"
    return ["지난 사이클(%s)에는 %s 정점에서 %s 줄었습니다." % (이, P.이(말), 맥.수("N:독자:지난사이클:낙폭", "퍼0")), ""]


def 경쟁표(맥):
    """경쟁 위치 표 둘 — ① 고객이 고르는 기준(사양 · 원가 · 납기 · 인증)과 점유율 시계열 ② 경쟁사별 추가 물량 판정."""
    import 레터원고 as W                                     # noqa: PLC0415
    v = _관(맥, "경쟁")
    줄 = [x for x in (v if isinstance(v, list) else []) if isinstance(x, dict) and _글(x.get("회사"))]
    if not 줄:
        return []
    줄 = sorted(줄, key=lambda x: 0 if x.get("대상") is True else 1)
    기간 = []
    for x in 줄:
        for k in (x.get("점유율") or {}) if isinstance(x.get("점유율"), dict) else {}:
            if k not in 기간:
                기간.append(k)
    기간 = sorted(기간)[-4:]                                  # 점유율 시계열은 마지막 네 기간까지
    기준들 = W.경쟁기준목록(맥.가정)                           # 1.1.2 — 업종별 기준 열(원고 `관측.경쟁기준` → 원형 → 기본)
    머 = ["회사"] + list(기준들) + ["점유율 %s" % k for k in 기간] + ["출처"]
    줄들 = []
    for x in 줄:
        기 = x.get("기준") if isinstance(x.get("기준"), dict) else {}
        점 = x.get("점유율") if isinstance(x.get("점유율"), dict) else {}
        없 = 맥.원고글(x.get("점유율없음")) if _글(x.get("점유율없음")) else "—"
        줄들.append([맥.원고글(x["회사"]) + (" (대상회사)" if x.get("대상") is True else "")]
                   + [맥.원고글(기.get(k) or "—") for k in 기준들]
                   + [맥.원고글("%s" % 점[k]) if k in 점 and ("%s" % 점[k]).strip() else 없 for k in 기간] + [맥.원고글(x.get("출처") or "—")])
    L = ["**표. 대상회사와 경쟁사의 비교: 고객의 공급사 선정 기준과 점유율**", ""]     # v27 문장(교열 30) — 표 제목으로
    L += P._표(머, 줄들, ["l"] * len(머)) + [""]
    공 = _관(맥, "조사공백")                                   # 1.1.2 — 칸 절반 이상이 비었던 줄은 표 대신 조사 공백 목록으로
    공 = [x for x in (공 if isinstance(공, list) else []) if (isinstance(x, dict) and _글(x.get("항목") or x.get("회사"))) or _글(x)]
    if 공:
        L += ["다음 항목은 조사하지 못했습니다.", ""]          # v27 문장(교열 31)
        L += ["- %s" % (맥.원고글(x) if isinstance(x, str) else "%s — %s" % (맥.원고글(x.get("항목") or x.get("회사")), 맥.원고글(x.get("까닭") or x.get("필요자료") or "자료를 찾지 못했습니다")))
              for x in 공] + [""]
    추 = [x for x in 줄 if x.get("대상") is not True and isinstance(x.get("추가물량"), dict)]
    if 추:
        L += ["**표. 경쟁사가 물량을 더 낼 수 있는지 — 가용 능력 · 투자 여력 · 규제 · 철수**", ""]     # 1.1.20 — 방법 설명 문장(원칙 12)을 표 제목으로
        L += P._표(["경쟁사"] + [W.추가물량말.get(k, k) for k in W.추가물량칸],
                   [[맥.원고글(x["회사"])] + [맥.원고글(x["추가물량"].get(k) or "—") for k in W.추가물량칸] for x in 추], ["l"] * (1 + len(W.추가물량칸))) + [""]
    return L


def 경쟁문단(맥):
    """절글.경쟁 — 문단 끝에 닿는 가정 칸을 이름으로 붙인다(「→ 닿는 가정: …」). 요소 「경쟁」 문단만 가정을 붙이고 나머지는 글 그대로."""
    목 = (_N(맥).get("절글") or {}).get("경쟁") if isinstance(_N(맥).get("절글"), dict) else None
    문단 = []                                                  # [(글, 가정 이름들)] — 꼬리 문장은 아래에서 모아 붙인다(1.1.19)
    for i, x in enumerate(목 if isinstance(목, list) else []):
        if isinstance(x, dict) and isinstance(x.get("표"), dict):
            continue
        글 = N.펴기(맥, x.get("글") if isinstance(x, dict) else x, "Narrative.절글.경쟁[%d]" % i)
        if not 글:
            continue
        if isinstance(getattr(맥, "원고자리", None), dict):          # 게이트 ⑭ 편집대조 — 편집본에서 이 문단이 살아 있는지(`레터막.절글넣기` 와 같은 꼴)
            요 = x.get("요소") if isinstance(x, dict) else None
            맥.원고자리["경쟁[%d]" % i] = {"글": 글, "요소": [요] if isinstance(요, str) else [e for e in (요 or []) if isinstance(e, str)]}
        번들 = ["%s" % b for b in ((x.get("가정") or []) if isinstance(x, dict) else [])]
        이름들 = [("WACC" if b == "WACC" else 이름(맥, b.replace("A-", ""))) for b in 번들 if b == "WACC" or 값있나(맥, b.replace("A-", ""))]
        문단.append((글, list(dict.fromkeys(이름들))))
    return 경쟁가정붙임(문단)


경쟁꼬리상한 = 2                                           # 1.1.19 — 「이 판단은 … 가정에 반영했습니다」 꼬리 문장을 몇 번까지 쓰나(지시서 L 「같은 구조의 문장을 세 번 이상 쓰지 않는다」)


def 경쟁가정붙임(문단):
    """[(글, 가정 이름들)] → 줄 목록. 이어진 문단이 같은 가정에 닿으면 꼬리 문장은 그 무리의 끝 문단에 한 번만 붙인다. 꼬리 문장이 `경쟁꼬리상한` 을 넘으면
    (같은 틀의 문장이 세 번 이상) 문단마다 붙이지 않고 문단 뒤에 표 하나로 모은다 — 문단 차례 · 반영한 가정(ADDER80 묶음 2 — 경쟁 절 네 문단 끝마다
    같은 틀이 되풀이돼 교열이 풀지 못했다)."""
    무리 = []                                                  # [(첫 문단 번호, 끝 문단 번호, 이름들)] — 1부터
    for k, (_글, 이) in enumerate(문단, 1):
        if not 이:
            continue
        if 무리 and 무리[-1][1] == k - 1 and 무리[-1][2] == 이:
            무리[-1] = (무리[-1][0], k, 이)
        else:
            무리.append((k, k, 이))
    L = []
    if len(무리) <= 경쟁꼬리상한:
        끝 = {b: 이 for _a, b, 이 in 무리}
        for k, (글, _이) in enumerate(문단, 1):
            if k in 끝:
                이 = 끝[k]
                글 = "%s 이 판단은 %s 가정에 반영했습니다." % (글.rstrip(), " · ".join(이[:3]) + (" 외 %d개" % (len(이) - 3) if len(이) > 3 else ""))
            L += [글, ""]
        return L
    for 글, _이 in 문단:
        L += [글, ""]
    줄들 = [[("%d번째 문단" % a) if a == b else ("%d~%d번째 문단" % (a, b)), " · ".join(이)] for a, b, 이 in 무리]
    L += ["**표. 경쟁 판단을 반영한 가정**", ""] + P._표(["경쟁 판단(문단 차례)", "반영한 가정"], 줄들, ["l", "l"]) + [""]
    return L


def 업황절(맥, 번):
    """업황과 경쟁 절(2026-10-31 · 독립 검토 L1 · L2) — 업황 · 수급(외부 관측 지표로 판정한 사이클 위치 · 과거 사이클과의 견줌 · 사이클 위치 그림)과
    경쟁 위치(고객이 고르는 기준 · 점유율 시계열 · 경쟁사별 추가 물량 판정 · 경쟁력 문장마다 닿는 가정). 사이클 위치 그림은 외부 지표가 셋 이상일 때만
    싣는다 — 이 평가의 가정만으로 제 위치를 정한 그림은 싣지 않는다(`그림규칙.json` 「자기출처위치」)."""
    import 레터원고 as W                                     # noqa: PLC0415
    L = 머리("업황", 번)
    업 = 덧글넣기(맥, 업황지표표(맥), "업황")
    if W.업황지표충분(맥.가정):
        업 += 출처붙여(맥, M.시계그림, 맥, 외부=True)
    업 += 과거사이클표(맥)
    경 = 경쟁표(맥) + 경쟁문단(맥)
    if 업:                                                   # 소제목은 그 밑에 글이 있을 때만(빈 소제목을 세우지 않는다 — 원고 생략 픽스처)
        L += ["### 업황 : 사이클 위치와 수급", ""] + 업
    if 경:
        L += ["### 경쟁 : 고객이 고르는 기준과 점유율", ""] + 경
    # 갈래(⑧ 선언한 갈래만)로 세지 않는다 — 업황 절은 구조 선언이 아니라 원고 요건(요건판 3)이 세운다
    return L


# ══════════════════════════════════════════════════════════════════ 3. 추정 구조 — 출발값 · 추정 순서 · 정합 조건 · 변수 연결도

def _수준구분들(맥):
    return [x for x in 맥.구.get("매출구분") or [] if x.get("경로") == "수준" and isinstance(x.get("번호"), int) and x["번호"] < 6]


def _가격말(x):
    return ("%s" % (x.get("판매단가명칭") or "판매단가 지수")).strip()


def _물량말(x):
    return ("%s" % (x.get("판매량명칭") or "판매량")).strip()


def 연결도(맥):
    """변수 연결도(그림 「연결」) — 물량 → 가격 → 매출 → 원가 → 영업이익 → 세금 · 재투자 → FCFF → 할인 → 가치. 상자마다 그 칸의 가정 번호 · 값.
    표: 단계 · 변수 · 가정 · 넘기는 값. 같은 단계의 줄은 그림에서 나란히 선다."""
    L_ = _L()
    끝, TV = 맥.끝예측, 맥.영구열
    S = 맥.기["4.Sales"]
    줄들 = []

    def 가(번, 짧게=False):
        """상자의 가정 한 줄 — 본편 가정 표의 이름과 기준값(2026-10-25 레터 재구성 마무리 — 내부 번호 「(A-30)」 는 부록 A 에만).
        짧게 = 매출 구분 하나의 물량 · 가격 상자(변수 칸이 구분 이름을 이미 말한다)는 짧은 이름, 여러 구분 · 원가 줄이 섞이는 상자는 본편 이름 그대로
        (짧은 이름은 구분 · 괄호 덧말을 떼어 「변동률」 · 「인건비 배분율」 처럼 같은 말이 겹친다 — 그 자리를 번호가 가르고 있었다)."""
        return ("%s %s" % (짧은이름(맥, 번) if 짧게 else 이름(맥, 번), 가정값글(맥, 번))) if 값있나(맥, 번) else ""
    for x in _수준구분들(맥):
        s = x["번호"]
        이 = L_.구분이름(맥.구, s)
        if x.get("판매량산정") == "능력" and (S.get("1%d2" % s) or {}):
            라인 = [j.get("이름") for j in x.get("라인") or [] if _글(j.get("이름"))]
            if x.get("배분라인"):
                몫 = [가("1%d%02d" % (s, int(j.get("번호"))), True) for j in x.get("배분라인") or []]
                가정 = "배분율 " + " · ".join(m for m in 몫 if m) if any(몫) else "배분율"
            else:
                가정 = "%s의 생산능력 일정" % " · ".join(라인) if 라인 else "생산능력 일정"
            줄들.append(["물량", "%s %s" % (이, _물량말(x)), 가정, "%s %s%s" % (맥.열말(끝), 맥.수("R:기준:4.Sales:1%d2:%s" % (s, 끝), "수1"), _글(x.get("판매량단위")))])
        if x.get("단가경로") == "연동" and x.get("연동구분"):
            따 = L_.구분이름(맥.구, x["연동구분"])
            가정 = " · ".join(m for m in (가("54%d" % s, True), 가("55%d" % s, True), 가("6%d3" % s, True)) if m) or "%s 연동" % 따
            줄들.append(["가격", "%s %s" % (이, _가격말(x)), "%s 연동 — %s" % (따, 가정),
                       "영구기간 %s" % 지수덧(맥, "R:기준:4.Sales:1%d5:%s" % (s, TV), s) if TV and _n((S.get("1%d5" % s) or {}).get(TV)) is not None else "—"])
        elif x.get("단가경로") == "수렴":
            가정 = " · ".join(m for m in (가("6%d3" % s, True), 가("6%d8" % s, True), 가("6%d6" % s, True), 가("6%d9" % s, True)) if m)
            줄들.append(["가격", "%s %s" % (이, _가격말(x)), 가정 or "—",
                       "영구기간 %s" % 지수덧(맥, "R:기준:4.Sales:1%d5:%s" % (s, TV), s) if TV and _n((S.get("1%d5" % s) or {}).get(TV)) is not None else "—"])
    단계 = 그래프단계가정(맥)                                 # 2026-10-25 R4 — 회사마다 설명체인에서(없으면 종전 고정 목록)
    if 단계 is None:
        맥.알림.append("변수 연결도 — _raw/동인그래프.json 이 없어 가정 칸을 고정 번호 목록으로 지었다(동인그래프.py 를 돌리면 회사의 설명체인으로 짓는다)")
    수준번 = {b for x in _수준구분들(맥) for b in ("6%d3" % x["번호"], "6%d6" % x["번호"], "6%d8" % x["번호"], "6%d9" % x["번호"],
                                             "54%d" % x["번호"], "55%d" % x["번호"])}

    def 단계가정(단, n):
        번들 = [b for b in ((단계 or {}).get(단) or []) if b not in 수준번] if 단계 is not None else list(_연결고정.get(단, ()))
        return [m for m in (가(b) for b in 번들) if m][:n]
    매출가정 = " · ".join(단계가정("매출", 4))
    증구 = [x for x in 맥.구.get("매출구분") or [] if x.get("경로") == "증가율" and (x.get("번호") or 6) < 6]
    매식 = ("매출 = 매출 구분마다 판매량 × %s" % _가격말(_수준구분들(맥)[0]) if _수준구분들(맥) else
           ("매출 = 매출 구분마다 전기 매출 × (1 + 매출 증가율)" if 증구 and not any(가격나뉨(맥, x) for x in 증구) else
            "매출 = 매출 구분마다 판매량 × 판매단가"))       # 증가율 경로 · 판매량명칭이 매출이면 판매량 × 판매단가가 아니다(회차 20261023 NVDA) · 1.1.19 판매단가 변동률이 모두 0 이어도(`가격나뉨`)
    줄들.append(["매출", 매식,
               매출가정 or "—", "%s %s%s" % (맥.열말(끝), 맥.수("R:기준:4.Sales:54:%s" % 끝, "금액"),
                                        (" · 영구기간 %s" % 맥.수("R:기준:4.Sales:54:%s" % TV, "금액")) if TV else "")])
    원 = 단계가정("원가", 5)
    D = "R:기준:2.DCF:%s"
    인 = 맥.구.get("인건비") or {}
    성과 = 인.get("산정방식") == "인원" and 인.get("성과급") != "없음" and 인.get("인원경로") != "수준"     # 선언한 갈래만(레터.갈래말과 같은 판정)
    # 원가 줄의 이름은 이 회사의 구조에서(2026-10-23 — 「재료비 및 경비」 고정 문구가 기능별 표시 회사에도 찍혔다)
    원이름 = [L_.원가줄이름(맥.구, x["번호"]) for x in 맥.구.get("원가줄") or [] if P._원가줄쓰나(맥, x)] or ["재료비 및 경비"]
    원이름 += ["감가상각비"] + (["인건비"] if 인.get("산정방식") in ("인원", "매출액비율") else []) + (["성과급"] if 성과 else [])
    줄들.append(["원가", " · ".join(원이름), " · ".join(원[:5]) or "—",
               "영구기간 영업비용 %s" % 맥.식(["−", D % "11:%s" % TV, D % "15:%s" % TV], "금액") if TV and _n(맥.값(D % "15:%s" % TV)) is not None else "—"])
    줄들.append(["영업이익", "영업이익 = 매출 − 영업비용", "—",
               ("영구기간 영업이익률 %s" % 맥.수(D % "42", "퍼1")) if _n(맥.값(D % "42")) is not None else "—"])
    재 = 단계가정("세금 · 재투자", 4)
    줄들.append(["세금 · 재투자", "법인세 · CAPEX · 순운전자본", " · ".join(재[:4]) or "—",
               "%s FCFF %s" % (맥.열말(끝), 맥.수(D % "23:%s" % 끝, "금액")) if _n(맥.값(D % "23:%s" % 끝)) is not None else "—"])
    할 = ["WACC %s" % 맥.수("R:기준:WACC:예측기간:WACC", "퍼2")] + 단계가정("할인", 2)
    줄들.append(["할인", "FCFF의 현재가치 · Terminal Value", " · ".join(할), "영업가치 %s" % 맥.수(D % "58", "금액")])
    줄들.append(["가치", "주주가치 · 주당가치", "비영업자산 · 이자부부채 · 적용 주식수", "주당가치 %s" % 맥.수(D % "68", "주당")])
    L = ["<!-- 그림:연결 -->", "**그림. 변수 연결도(기준 시나리오)** — 위에서 아래로 값이 넘어갑니다. 상자마다 그 칸을 정하는 가정(이름 · 기준값)과 다음 칸으로 넘기는 값을 적었습니다."
         "%s" % (" 상자의 가정은 평가 모델의 산식이 그 칸으로 읽는 가정이고, 시나리오마다 값을 다르게 둔 가정을 먼저 적었습니다."
                                                        if 단계 is not None else ""), ""]
    L = 출처달기(맥, L, ["R:기준:2.DCF:58", "A:가정:기준"])           # 2026-10-25 R5 — 출처 줄
    L += P._표(["단계", "변수", "가정", "넘기는 값"], 줄들, ["l", "l", "l", "l"])
    L.append("")
    return L


_엔진산출 = (
    ("매출원가율 · 영업이익률", "매출과 원가 가정이 정한 결과", "R:기준:2.DCF:42"),
    ("유효세율", "법정 한계세율에서 세액공제를 뺀 결과", None),
    ("영구기간 재투자율", "영구성장률 ÷ 영구기간 ROIC", "R:기준:2.DCF:49"),
    ("Levered Beta · WACC", "Unlevered Beta와 {자본구조} · 무위험이자율 · MRP로 계산한 값", "R:기준:WACC:예측기간:WACC"),
)


def 구조표(맥):
    """정합 조건 표 — 변수 · 성격(설정한 가정 / 산출된 값) · 기준 · 정한 법. 저자가 산출로 선언한 가정(`Narrative.추정구조.변수`)은 산출로 싣는다."""
    선 = (_N(맥).get("추정구조") or {}) if isinstance(_N(맥).get("추정구조"), dict) else {}
    산출번 = {}
    for k, x in enumerate(선.get("변수") or []):
        if isinstance(x, dict) and x.get("성격") == "산출":
            for b in x.get("가정") or []:
                산출번["%s" % b] = (k, x)
    줄들 = []
    번들 = []
    for x in _수준구분들(맥):
        s = x["번호"]
        번들 += ["6%d3" % s, "6%d8" % s, "6%d6" % s, "6%d9" % s, "54%d" % s, "55%d" % s]
        for j in x.get("배분라인") or []:
            번들.append("1%d%02d" % (s, int(j.get("번호"))))
    번들 += ["711", "712", "714", "503", "504", "510", "521", "850", "178", "182", "186", "196", "212", "219"]
    본 = set()
    for 번 in 번들:
        if 번 in 본 or not 값있나(맥, 번):
            continue
        본.add(번)
        if 번 in 산출번:
            k, x = 산출번[번]
            법 = N.펴기(맥, x.get("정한법"), "Narrative.추정구조.변수[%d].정한법" % k) or "—"
            줄들.append([이름(맥, 번), "산출된 값", 가정값글(맥, 번), 법])
        else:
            줄들.append([이름(맥, 번), "설정한 가정", 가정값글(맥, 번), 근거한줄(맥, 번) or "—"])
    for k, x in enumerate(선.get("변수") or []):                 # 저자가 따로 적은 산출 변수(가정 번호가 없는 것)
        if isinstance(x, dict) and x.get("성격") == "산출" and not x.get("가정") and _글(x.get("이름")):
            이 = 맥.원고글(x["이름"], "Narrative.추정구조.변수[%d].이름" % k)
            법 = N.펴기(맥, x.get("정한법"), "Narrative.추정구조.변수[%d].정한법" % k)
            값 = N.펴기(맥, x.get("값"), "Narrative.추정구조.변수[%d].값" % k) if _글(x.get("값")) else "—"
            if 이 and 법:
                줄들.append([이, "산출된 값", 값, 법])
    for 이, 법, 키 in _엔진산출:
        법 = 법.replace("{자본구조}", "목표 자본구조" if _n(((맥.가정.get("WACC") or {}).get("예측기간") or {}).get("DE")) is not None else "평가기준일 자본구조")
        if 키 is None and 이.startswith("유효세율") and 맥.끝예측:
            키 = "R:기준:10.Tax:16:%s" % 맥.끝예측
        if 키 is None or _n(맥.값(키)) is None:
            continue
        값 = 맥.수(키, "퍼1" if any(t in 키 for t in (":42", ":49", "10.Tax")) else "퍼2")
        if 이.startswith(("매출원가율", "유효세율")):
            값 = "%s %s" % ("영구기간 영업이익률" if 이.startswith("매출원가율") else 맥.열말(맥.끝예측), 값)
        줄들.append([이, "산출된 값", 값, 법])
    return P._표(["변수", "성격", "기준", "정한 법 · 근거"], 줄들, ["l", "l", "r", "l"]) + [""]


def 구조절(맥, 번):
    L = 머리("구조", 번)
    선 = (_N(맥).get("추정구조") or {}) if isinstance(_N(맥).get("추정구조"), dict) else {}
    # 1.1.20 — 「검토할 대상은 산출된 값이 아니라 직접 설정한 가정입니다」(절 첫 문장이 어느 회사에나 참 · 원칙 11)는 지웠다 — 설정한 가정과 산출된 값의
    # 구분은 아래 「정합 조건」 표가 보인다
    # 출발값
    L += ["### 출발값 : 실적과 %s의 재무상태" % P.재무날말(맥), ""]          # 날짜 둘 — 재무상태표는 재무 자료 기준일의 것
    출 = N.펴기(맥, 선.get("출발값"), "Narrative.추정구조.출발값")
    if 출:
        L += [출, ""]
    L += P.실적절(맥, 번)[2:]
    해 = M.해들(맥)
    if len(해) >= 3:
        국 = M.국면들(맥, 해)
        L += 출처붙여(맥, M.계단그림, 맥, 해, 국)
        L += M.기울기문장(맥, 해, 국)
    # 추정 순서
    L += ["### 추정 순서 : 무엇을 먼저 정하고 무엇을 산출했나", ""]
    순 = N.펴기(맥, 선.get("순서"), "Narrative.추정구조.순서")
    if 순:
        L += [순, ""]
    else:
        맥.알림.append("Narrative.추정구조.순서(추정 순서와 그 순서를 택한 까닭)가 없다 — 3절에 모델의 차례만 실었다")
    수 = _수준구분들(맥)
    if 수:
        이들 = " · ".join(_L().구분이름(맥.구, x["번호"]) for x in 수)
        # 1.1.20 — 「추정은 물량 → 가격 → … 순서로 진행했습니다」(모델의 계산 차례 · 원칙 3)는 지웠다 — 차례는 장 머리 「추정 흐름」 표가 보인다
        L += ["%s의 물량은 %s, 가격은 %s 정했습니다." % (
            이들, "생산능력 일정에서 먼저 정했고" if any(x.get("판매량산정") == "능력" for x in 수) else "판매량 추정에서 정했고",
            "기준 기간 대비 변동률 · 유지 종료 연도 · 정상 수준 · 도달 연도 네 가지로 경로를" if any(x.get("단가경로") == "수렴" for x in 수)
            else "판매단가 경로로"), ""]
    흐름 = 추정흐름(맥)                                       # 레터 v27 6단계 — 장 머리 「추정 흐름」 표가 연결도와 「설정한 가정 / 산출된 값」 표를 갈음한다
    if not 흐름:
        L += 연결도(맥)
    # 정합 조건
    L += ["### 정합 조건 : 설정한 가정과 산출된 값", ""]
    정 = 정합머리고침(N.펴기(맥, 선.get("정합"), "Narrative.추정구조.정합"))
    if 정:
        L += [정, ""]
    if 흐름:
        L += 흐름
    else:
        구표 = 구조표(맥)
        L += 구표
        if sum(1 for x in 구표 if x.startswith("|")) > 2:          # v27 문장(교열 41 · 42) — 표 읽는 법은 표 주석(표 바로 아래)으로
            L += ["「설정한 가정」은 근거를 두고 직접 정한 값이고, 「산출된 값」은 그 가정을 충족하도록 계산한 값입니다. "
                  "산출된 값을 바꾸려면 그 값의 계산에 쓴 가정을 바꿔야 합니다.", ""]
    # 평가 방법
    L += ["### 평가 방법과 사용 자료", ""]
    L += 사용자료(맥, "수집")                                   # 무엇을 모았나(수치층) → 방법 → 그 자료가 간 길(저자 「자료」 문단) → 인용 문서
    L += P.방법절(맥, 번)[2:]
    L += 사용자료(맥, "인용")
    L = 덧글넣기(맥, L, "구조", "실적", "방법")
    맥.서술("추정구조")
    return L


def 정합머리고침(글):
    """1.1.21 — 정합 원고의 머리 문장 「산출된 값은 N 조건에 맞췄습니다.」(원고 요건 「산출된 값을 어떤 조건에 맞췄나」 를 그대로 옮긴 꼴 · ADDER80 백테스트
    스무 곳) 뒤에는 가정이 온다(첫째, … 가정했습니다) — 「추정은 다음 N가지 조건을 지키도록 세웠습니다.」 로 바꾼다(어긋남 · 원칙 5). 다른 머리는 그대로."""
    m = re.match(r"^산출된 값은 ([가-힣]+|\d+)(?:\s*가지)? 조건(?:에|을) 맞췄습니다\.\s*", 글 or "")
    if not m:
        return 글
    수 = m.group(1)
    return "추정은 다음 %s 조건을 지키도록 세웠습니다. %s" % (("%s가지" % 수) if 수.isdigit() else ("%s 가지" % 수), 글[m.end():])


def 추정흐름(맥):
    """모델 설계 장 머리의 「추정 흐름」 표(`레터추정표.추정흐름표` — 블록 열 줄 · 일곱 열). 근거표가 없으면 빈 목록."""
    import 레터원고 as W                                     # noqa: PLC0415
    import 레터추정표 as Q                                   # noqa: PLC0415
    근 = W.근거표(맥)
    if not 근:
        return []
    return Q.펴기(맥, Q.추정흐름표(근)).split("\n") + [""]


def 사용자료(맥, 쪽="수집"):
    """평가 방법과 사용 자료 — 「수집」: 자료 수집 표(회차 `_raw` 의 조사 산출물을 센 것 · `레터자료.수집표`) · 「인용」: 끌고 온 문서 목록
    (`관측.출처목록` — 독자층). 없으면 줄을 세우지 않는다(출처목록이 비면 `레터원고` 가 원고 누락으로 초안을 막는다)."""
    import os
    import 레터자료                                          # noqa: PLC0415
    L = []
    회 = os.path.dirname(os.path.abspath(맥.경로)) if getattr(맥, "경로", None) else None
    수 = 레터자료.수집표(회, 맥.가정) if 쪽 == "수집" else []
    if 수:
        L += ["**표. 평가에 쓴 자료의 수집 범위와 그 자료를 반영한 가정**", ""]       # v27 문장(교열 43) — 표 제목으로
        L += P._표(["자료", "수집 범위", "반영한 가정"], 수, ["l", "l", "l"]) + [""]    # 셈은 건 · 개 — 게이트 ⑦ 의 값 꼴이 아니다
    출 = [x for x in ((맥.가정.get("관측") or {}).get("출처목록") or []) if isinstance(x, dict) and _글(x.get("문서"))] if 쪽 == "인용" else []
    if 출:
        태말 = {"[공시]": "공시", "[회사주장]": "회사 자료", "[외부평가]": "외부 평가", "[관측]": "관측", "[계산]": "계산", "[법령]": "법령", "[판단]": "판단"}
        태들 = [t for t in dict.fromkeys(태말.get(("%s" % (x.get("태그") or "")).strip(), "") for x in 출) if t]   # 인쇄 조건 — 목록에 실제로 있는 구분만
        L += ["**표. 가정의 근거로 인용한 문서와 그 문서를 반영한 가정**", ""]       # v27 문장(교열 55) — 표 제목 · 표 주석으로
        L += P._표(["문서", "구분", "반영한 가정"], [[맥.원고글(x.get("문서")), 맥.원고글(x.get("태그") or "—"), 맥.원고글(x.get("쓴곳") or "—")] for x in 출],
                  ["l", "l", "l"]) + [""]
        if 태들:
            L += [("구분은 %s 가운데 하나입니다." % " · ".join(태들)) if len(태들) > 1 else ("구분은 모두 %s." % P.입니다(태들[0])), ""]
    return L


# ══════════════════════════════════════════════════════════════════ 4. 매출 — 매출 구분마다 공시 · 방법 · 물량 · 가격 · 그림

def _기준기간(맥, x):
    return P._기준기간이름(맥, x)


def 공시방법글(맥, x):
    """매출 구분 하나 — 공시가 주는 것과 그래서 택한 방법(구조의 선언에서 — 조건 없는 문장 없음)."""
    L_ = _L()
    s = x["번호"]
    이 = L_.구분이름(맥.구, s)
    문 = []
    기 = _기준기간(맥, x)
    if 기 and x.get("경로") != "증가율":                       # 기준 기간은 판매단가 지수(수준 경로)의 눈금 — 증가율 경로 구분에는 싣지 않는다(2026-10-23)
        문.append("기준 기간은 %s." % P.입니다(기))
    if x.get("판매량공시") == "아니오":
        문.append("회사는 %s의 %s 공시하지 않습니다." % (이, P.을(_물량말(x))))
    elif x.get("판매량공시") == "예" and 선언판매량공시(맥, s) == "예":   # 엔진 기본값 「예」 는 선언이 아니다 — 저자가 적은 판만(견본 실측)
        문.append("회사는 %s의 %s 공시합니다." % (이, P.을(_물량말(x))))
    if x.get("판매량산정") == "능력":
        라인 = [j.get("이름") for j in x.get("라인") or [] if _글(j.get("이름"))]
        if x.get("배분라인"):
            팹 = [y.get("이름") for z in _수준구분들(맥) for y in z.get("라인") or [] if y.get("번호") in [j.get("번호") for j in x.get("배분라인") or []]]
            문.append("판매량은 %s의 생산능력 가운데 %s에 배분하는 비율(배분율)로 계산했습니다." % (" · ".join(dict.fromkeys(팹)) or "공유 팹", 이))
        elif 라인:
            문.append("판매량은 %s의 생산능력에 가동률을 곱해 계산했습니다." % " · ".join(라인))
    if x.get("단가경로") == "수렴":
        문.append("%s 기준 기간 대비 변동률을 유지 종료 연도까지 적용하고, 정상 수준 도달 연도까지 해마다 같은 비율로 정상 수준에 다가간다고 가정했습니다." % P.은(_가격말(x)))
    elif x.get("단가경로") == "연동" and x.get("연동구분"):
        따 = L_.구분이름(맥.구, x["연동구분"])
        시차 = 가정값글(맥, "55%d" % s) if 값있나(맥, "55%d" % s) else ""
        문.append("%s %s의 것에 %s 연동하고 연동 배율을 곱해 추정했습니다." % (P.은(_가격말(x)), 따, ("%s 늦게" % 시차.replace("년", "년")) if 시차 and 시차 not in ("0", "—") else "같은 해에"))
    return " ".join(문)


def 선언판매량공시(맥, s):
    """저자가 가정 파일 `구조.매출구분[].판매량공시` 에 적은 값(없으면 None — 엔진 구조의 기본값과 가른다)."""
    x = next((y for y in ((맥.가정.get("구조") or {}).get("매출구분") or []) if isinstance(y, dict) and y.get("번호") == s), {})
    return x.get("판매량공시")


def _0아닌값(v):
    """가정 칸(시나리오 · 열로 묶인 dict · list · 수)에 0 이 아닌 수가 하나라도 있나."""
    if isinstance(v, dict):
        return any(_0아닌값(x) for x in v.values())
    if isinstance(v, (list, tuple)):
        return any(_0아닌값(x) for x in v)
    n = _n(v)
    return n is not None and abs(n) > 1e-12


def 가격나뉨(맥, x):
    """매출 구분 x 가 판매량과 판매단가로 나뉘어 추정됐나(1.1.19 — 이름이 아니라 가정의 구조로 판정한다).
    수준 경로는 물량과 가격이 따로 선다. 증가율 경로는 판매량명칭이 매출 그 자체가 아니고, 그 구분의 판매단가 변동률 가정(구분 s 의 `_증가율번호` 둘째)이
    어느 시나리오 · 어느 열에서든 0 이 아닐 때만 나뉜다 — 판매단가 변동률이 없거나 모두 0 이면 하나 남은 증가율이 곧 매출 증가율이다
    (ADDER80 묶음 1 · 2 — 매출을 증가율 하나로 추정한 회사에 「판매량과 판매단가」 제목 · 「이 평가의 판매량」 표 제목이 섰다).
    가정 파일이 없는 맥(시험 흉내)은 이름으로만 본다."""
    if not isinstance(x, dict):
        return False
    if x.get("경로") == "수준":
        return True
    if x.get("경로") != "증가율" or P.매출명칭인가(x):
        return False
    가 = getattr(맥, "가정", None)
    if not isinstance(가, dict):
        return True
    s = x.get("번호")
    if s not in _증가율번호:
        return False
    return _0아닌값((가.get("가정") or {}).get("%d" % _증가율번호[s][1]))


def 매출꼴(맥):
    """→ (꼴, 판매량을 넘기나). 꼴 — 「수준」(물량과 가격이 따로 서는 구분이 있다) · 「판매량」(모든 구분이 판매량 · 판매단가의 증가율) ·
    「섞임」(판매량 · 판매단가로 나눈 구분과 매출 증가율 하나로 둔 구분이 함께) · 「매출」(매출 증가율만). 나뉨은 `가격나뉨`(가정의 구조)으로 판정한다."""
    잎 = [x for x in 맥.구.get("매출구분") or [] if isinstance(x, dict) and x.get("경로") != "합계"]
    if any(x.get("경로") == "수준" for x in 잎):
        return "수준", True
    나 = [가격나뉨(맥, x) for x in 잎 if x.get("경로") == "증가율"]
    if 나 and all(나):
        return "판매량", True
    if any(나):
        return "섞임", True
    return "매출", False


매출제목들 = {"판매량": "매출 추정 : 매출 구분별 판매량과 판매단가", "섞임": "매출 추정 : 매출 구분별 판매량 · 판매단가와 매출 증가율",
          "매출": "매출 추정 : 매출 구분별 매출 증가율"}


def 매출제목(맥):
    """4절 제목 — 경로를 따른다(수준 경로가 있으면 지금 제목 그대로)."""
    꼴, _물 = 매출꼴(맥)
    return 제목["매출"] if 꼴 == "수준" else 매출제목들[꼴]


def 대조대상말(맥, 부문=None):
    """반대 쪽 대조 표 · 문장이 부르는 「이 평가의 ○○」 — 판매량을 따로 세운 구분이면 「판매량」, 매출 증가율 하나로 추정한 구분이면 「매출」.
    부문 이름이 매출 구분 이름과 맞으면 그 구분으로, 아니면 회사 전체의 매출꼴로 판정한다(모든 구분이 매출 증가율이면 「매출」)."""
    잎 = [x for x in 맥.구.get("매출구분") or [] if isinstance(x, dict) and x.get("경로") != "합계"]
    if 부문:
        짝 = [x for x in 잎 if ("%s" % (x.get("이름") or "")).strip() and (("%s" % x.get("이름")).strip() in 부문 or 부문 in ("%s" % x.get("이름")).strip())]
        if 짝:
            return "판매량" if any(가격나뉨(맥, x) for x in 짝) else "매출"
    return "매출" if 매출꼴(맥)[0] == "매출" else "판매량"


_증가율번호 = {1: (30, 34), 2: (38, 42), 3: (46, 50), 4: (54, 58), 5: (62, 66)}     # 매출 구분 s 의 판매량 증가율 · 판매단가 변동률(증가율 경로)


def 스트림가정(x):
    s = x["번호"]
    번들 = ["6%d3" % s, "6%d8" % s, "6%d6" % s, "6%d9" % s, "6%d2" % s, "6%d4" % s, "54%d" % s, "55%d" % s]
    if x.get("경로") == "증가율" and s in _증가율번호:        # 2026-10-23 W3 — 증가율 경로 구분에도 가정 표가 서게(번들이 수준 경로 키뿐이었다)
        번들 = ["%d" % n for n in _증가율번호[s]] + 번들
    번들 += ["1%d%02d" % (s, int(j.get("번호"))) for j in x.get("배분라인") or []]
    for j in x.get("라인") or []:
        k = int(j.get("번호"))
        번들 += ["%d" % (668 + 2 * k), "%d" % (669 + 2 * k)]
    return 번들


def 스트림그림(맥, x):
    """그림 「스트림」 — 매출 구분 하나의 물량 · 가격 · 매출(시나리오 셋, 실적 점). 줄 이름 「판 · 계열」."""
    L_ = _L()
    s = x["번호"]
    이 = L_.구분이름(맥.구, s)
    S = 맥.기["4.Sales"]
    금 = P._금액줄.get(s)
    열 = [c for c in 맥.실적열 if 금 and _n((S.get(금) or {}).get(c)) is not None] + 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    줄들 = []
    판있음 = set()                                          # 그림 이름은 실린 판만(2026-10-23 W3 — 매출만 있는 구분에 「물량 · 가격」)
    물 = "1%d2" % s
    if x.get("판매량산정") == "능력" and (S.get(물) or {}):
        단 = _글(x.get("판매량단위"))
        판있음.add("물량")
        for 시 in ("비관", "기준", "낙관"):
            R = (맥.R.get(시) or {}).get("4.Sales", {}).get(물) or {}
            줄들.append(["%s(%s) · %s" % (_물량말(x), 단, 시)] + [맥.수("R:%s:4.Sales:%s:%s" % (시, 물, c), "수1") if _n(R.get(c)) is not None else "—" for c in 열])
    가 = "1%d5" % s
    if (S.get(가) or {}) and _n(맥.값(P.눈금키(맥, s))):
        판있음.add("가격")
        for 시 in ("비관", "기준", "낙관"):
            R = (맥.R.get(시) or {}).get("4.Sales", {}).get(가) or {}
            줄들.append(["%s(%s = 100) · %s" % (_가격말(x).replace(" 지수", ""), P.눈금이름(맥, x), 시)] +
                      [맥.식(["×", ["÷", "R:%s:4.Sales:%s:%s" % (시, 가, c), P.눈금키(맥, s)], 100], "수0") if _n(R.get(c)) is not None else "—" for c in 열])
    if 금:
        # 줄 이름에 돈 단위를 박지 않는다 — 칸 글이 단위를 갖는다(「1,234억 달러」 · 「68조 원」 — 2026-10-23 실측: 달러 회사에 「조 원」 이 찍혔다)
        실 = ["매출(연환산) · 실적"] + [맥.식(["÷", "R:기준:4.Sales:%s:%s" % (금, c), 맥.년(c)], "어림금액") if c in 맥.실적열 else "—" for c in 열]
        if any(v != "—" for v in 실[1:]):
            줄들.append(실)
        판있음.add("매출")
        for 시 in ("비관", "기준", "낙관"):
            R = (맥.R.get(시) or {}).get("4.Sales", {}).get(금) or {}
            줄들.append(["매출(연환산) · %s" % 시] + [맥.식(["÷", "R:%s:4.Sales:%s:%s" % (시, 금, c), 맥.년(c)], "어림금액")
                                                      if c not in 맥.실적열 and _n(R.get(c)) is not None else "—" for c in 열])
    if len(줄들) < 2:
        return []
    if getattr(맥, "_스트림범례", False):                      # 범례 설명은 첫 그림에 한 번(같은 문형을 되풀이하지 않는다)
        설 = "선의 구분과 연환산은 앞 매출 구분의 그림과 같습니다."
    else:
        맥._스트림범례 = True
        설 = "판마다 굵은 선이 기준, 긴 점선이 비관, 짧은 점선이 낙관입니다. 반기 열의 매출은 연환산입니다."
    판들 = [말 for 말 in ("물량", "가격", "매출") if 말 in 판있음]
    L = ["<!-- 그림:스트림 -->", "**그림. %s의 %s(실적과 시나리오 셋)** — %s" % (이, " · ".join(판들), 설), ""]
    L += P._표(["그림의 값"] + [맥.표기(c) for c in 열], 줄들)
    L.append("")
    return L


def 스트림덧(맥, x):
    """매출 소절(### 4.k) 끝에 붙는 것 — 공시와 방법 · 저자 덧글(절글 「매출.<구분 번호>」) · 가정 표 · 그림."""
    L = []
    g = 공시방법글(맥, x)
    if g:
        L += [g, ""]
    L += 절글(맥, "매출.%d" % x["번호"])
    L += 가정표(맥, 스트림가정(x), "%s의 가정" % _L().구분이름(맥.구, x["번호"]))
    L += 근거표(맥, 스트림가정(x))
    L += 범위띠그림(맥, 스트림가정(x), 말=_L().구분이름(맥.구, x["번호"]))     # 2026-10-25 R5 — 근거 범위 띠 · 동인 분해
    L += 출처붙여(맥, 스트림그림, 맥, x)
    L += 동인그림(맥, x)
    return L


def 묶임(맥):
    """매출 구분이 서로 묶이는 방식 — 합계(하위 구분의 합) · 배분(같은 팹의 웨이퍼를 나눠 씀) · 연동(가격이 다른 구분을 따름). 그림 「쌓기」."""
    L_ = _L()
    문 = []
    for x in 맥.구.get("매출구분") or []:
        if x.get("경로") == "합계":
            아래 = [L_.구분이름(맥.구, y["번호"]) for y in 맥.구.get("매출구분") or [] if y.get("상위") == x["번호"]]
            if 아래:
                문.append("%s 매출은 하위 구분(%s)의 합입니다." % (L_.구분이름(맥.구, x["번호"]), " · ".join(아래)))
    for x in _수준구분들(맥):
        if x.get("배분라인"):
            몫 = []
            for j in x.get("배분라인") or []:
                번 = "1%d%02d" % (x["번호"], int(j.get("번호")))
                팹 = next((y.get("이름") for z in _수준구분들(맥) for y in z.get("라인") or [] if y.get("번호") == j.get("번호")), None)
                if 팹 and 값있나(맥, 번):
                    몫.append("%s %s" % (팹, 가정값글(맥, 번)))
            if 몫:
                따 = L_.구분이름(맥.구, x.get("연동구분")) if x.get("연동구분") else "다른 구분"
                문.append("%s %s 같은 팹의 웨이퍼를 나눠 씁니다. 팹마다 %s에 배분하는 비율(%s)을 정하면 남는 웨이퍼가 %s의 판매량입니다." % (
                    P.은(L_.구분이름(맥.구, x["번호"])), P.과(따), L_.구분이름(맥.구, x["번호"]), " · ".join(몫), 따))
        if x.get("단가경로") == "연동" and x.get("연동구분") and 값있나(맥, "54%d" % x["번호"]):
            문.append("%s의 %s %s의 것에 배율 %s 곱해 추정했습니다." % (L_.구분이름(맥.구, x["번호"]), P.은(_가격말(x)), L_.구분이름(맥.구, x["연동구분"]),
                                                P.을(가정값글(맥, "54%d" % x["번호"]))))
    L = []
    잎 = [x for x in 맥.구.get("매출구분") or [] if x.get("경로") != "합계" and (x.get("번호") or 9) < 6]
    if not 문 and len(잎) >= 2:                              # 2026-10-23 W3 — 묶임이 없어도 「따로 셈했다」 는 구조의 사실이다(판단은 원고 「매출.연결」)
        이들 = " · ".join(L_.구분이름(맥.구, x["번호"]) for x in 잎)
        주어 = P.은(이들) if len(이들) <= 60 else "매출 구분 %d개는" % len(잎)      # 이름이 길면 개수로(한 문장 120자 — ⑬)
        문.append("%s 합계 · 배분 · 가격 연동으로 묶지 않고 구분마다 따로 추정했습니다." % 주어)
    연 = 절글(맥, "매출.연결")
    if 문 or 연:
        L += ["### 매출 구분 사이의 연결", ""] + ([" ".join(문), ""] if 문 else [])
        L += 연
    # 쌓기 — 매출 구분별 매출(기준, 연환산)
    S = 맥.기["4.Sales"]
    열 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    줄들 = []
    for x in 맥.구.get("매출구분") or []:
        if x.get("경로") == "합계":
            continue
        금 = P._금액줄.get(x["번호"])
        v = S.get(금) or {}
        if not 금 or not any(_n(v.get(c)) for c in 열):
            continue
        줄들.append([L_.구분이름(맥.구, x["번호"])] + [맥.식(["÷", "R:기준:4.Sales:%s:%s" % (금, c), 맥.년(c)], "어림금액") if _n(v.get(c)) is not None else "—" for c in 열])
    if len(줄들) >= 2:
        if not L:
            L += ["### 매출 구분 사이의 연결", ""]
        L += 출처달기(맥, ["<!-- 그림:쌓기 -->", "**그림. 매출 구분별 매출(기준 시나리오, 연환산)** — 막대 하나가 그해의 매출이고 칸마다 매출 구분입니다. 칸 이름은 마지막 막대 옆에 적었습니다.", ""],
                    ["R:기준:4.Sales:54:%s" % c for c in 열])
        L += P._표(["그림의 값"] + [맥.표기(c) for c in 열], 줄들)
        L.append("")
    return L


def 전방표(맥):
    """매출을 전방(고객 산업)별로 나눈 표(2026-10-31 L4 — `관측.전방매출`). 공시가 주지 않으면 「공시 없음 — 근거 종류」 한 문장."""
    v = _관(맥, "전방매출")
    if not isinstance(v, dict):
        return []
    if _글(v.get("공시없음")):
        return ["회사는 전방(고객 산업)별 매출을 공시하지 않습니다. %s" % 맥.원고글(v["공시없음"], "관측.전방매출.공시없음").rstrip(".") + ".", ""]
    표 = _원표(맥, v.get("표"), "관측.전방매출.표")
    if not 표:
        return []
    출 = ("출처: %s." % 맥.원고글(v.get("출처"), "관측.전방매출.출처").rstrip(".")) if _글(v.get("출처")) else ""
    return ["**표. 전방(고객 산업)별 매출 구성**", ""] + 표 + ([출, ""] if 출 else [])       # v27 문장(교열 71) — 표 제목 · 출처는 표 아래


def 반대대조표(맥):
    """반대 쪽 대조(2026-10-31 L3 — `관측.반대대조`) — 판매량을 생산능력으로 정한 평가는 연도별 수요 쪽, 수요 쪽에서 정한 평가는 공급 상한 쪽.
    해당없음이면 그 까닭 한 문장."""
    import 레터원고 as W                                     # noqa: PLC0415
    v = _관(맥, "반대대조")
    if isinstance(v, dict) and isinstance(v.get("구분별"), dict):     # P1 — 부문마다 방향이 갈리는 회사
        L = []
        for 이, 한 in v["구분별"].items():
            L += _반대대조한(맥, W, 한, "관측.반대대조.구분별.%s" % 이, 이)
        return L
    return _반대대조한(맥, W, v, "관측.반대대조")


def _반대대조한(맥, W, v, 자리, 부문=None):
    """반대 쪽 대조 하나(회사 하나 · 부문 하나)."""
    앞 = ("%s — " % 부문) if 부문 else ""
    까 = W.해당없음글(v)
    if 까:
        return ["%s공급 상한과의 대조는 하지 않았습니다. %s" % (앞, 맥.원고글(까, 자리 + ".해당없음").rstrip(".") + "."), ""]
    if not isinstance(v, dict):
        return []
    표 = _원표(맥, v.get("표"), 자리 + ".표")
    if not 표:
        return []
    대 = 대조대상말(맥, 부문)                                   # 1.1.19 — 매출 증가율 하나로 추정한 구분에 「판매량」 이라 쓰지 않는다(`가격나뉨`)
    머 = (("%s 생산능력을 기준으로 추정했습니다. 이 %s 고객 수요가 흡수하는지 연도별로 대조했습니다." % (P.은(대), P.을(대))) if v.get("방향") == "수요" else     # v27 문장(교열 72 · 73)
          "%s 고객 수요를 기준으로 추정했습니다. 이 %s 업계의 공급 상한과 회사의 공급 능력 안에 있는지 연도별로 대조했습니다." % (P.은(대), P.이(대)))
    출 = (" 출처: %s." % 맥.원고글(v.get("출처"), 자리 + ".출처").rstrip(".")) if _글(v.get("출처")) else ""
    L = ["### %s%s : 이 평가의 %s 연도별 대조" % ("%s " % 부문 if 부문 else "", "수요 대조" if v.get("방향") == "수요" else "공급 상한 대조", P.과(대)),
         "", 머 + 출, ""] + 표
    if _글(v.get("읽기")):
        L += [N.펴기(맥, v.get("읽기"), 자리 + ".읽기"), ""]
    return L


def 반대대조블록(맥):
    """추정 블록의 둘째 표(레터 v27 6단계) — 반대 쪽 대조 표만: 표 제목 · 표 · 표 아래 출처 한 줄 · 원고 「읽기」. 코드 문장(「판매량은 … 대조했습니다」)과
    해당없음 문장은 싣지 않는다(해당없음이면 둘째 표가 없다)."""
    import 레터원고 as W                                     # noqa: PLC0415
    v = _관(맥, "반대대조")
    짝 = ([(이, 한, "관측.반대대조.구분별.%s" % 이) for 이, 한 in v["구분별"].items()] if isinstance(v, dict) and isinstance(v.get("구분별"), dict)
          else [(None, v, "관측.반대대조")])
    L = []
    for 부문, 한, 자리 in 짝:
        if W.해당없음글(한) or not isinstance(한, dict):
            continue
        표 = _원표(맥, 한.get("표"), 자리 + ".표")
        if not 표:
            continue
        L += ["**표. %s%s — 이 평가의 %s 연도별 대조**" % ("%s " % 부문 if 부문 else "", "수요 대조" if 한.get("방향") == "수요" else "공급 상한 대조",
                                                    P.과(대조대상말(맥, 부문))), ""]       # 1.1.19 — 매출 증가율로 추정한 구분은 「이 평가의 매출과」
        L += 표
        if _글(한.get("출처")):
            L += ["출처: %s." % 맥.원고글(한.get("출처"), 자리 + ".출처").rstrip("."), ""]
        if _글(한.get("읽기")):
            L += [N.펴기(맥, 한.get("읽기"), 자리 + ".읽기"), ""]
    return L


def 매출절(맥, 번):
    L = P.매출절(맥, 번, 덧=스트림덧)
    L[0] = "## %d. %s" % (번, 매출제목(맥))
    앞 = 이음(맥, "매출") + 절머리(맥, "매출") + N이야기(맥, "매출")
    s = M.스트림문단(맥)
    if s:
        앞 += s + [""]
    L = L[:2] + 앞 + L[2:]
    L += 묶임(맥)
    L += 전방표(맥) + 반대대조표(맥)                         # 2026-10-31 요건판 3 — L4 전방별 매출 · L3 반대 쪽 대조
    import 레터고객 as _고                                  # noqa: PLC0415 — 1.1.6 고객 수 × 고객당 매출 구분의 검증 표(선언 · 옮긴 판만)
    L += P.블록소절(맥, "매출 구분과 부문 매출의 검증", _고.고객경로표(맥))      # 블록이면 소절(제목 · 설명 · 표) 통째로 부록에
    import 레터회사그림 as _회                                # noqa: PLC0415 — v27 7단계(다) 회사의 구조가 고르는 매출 그림
    L += _회.남은기간그림(맥) + _회.저량그림(맥)
    구번들 = [b for x in 맥.구.get("매출구분") or [] if isinstance(x.get("번호"), int) for b in 스트림가정(x)]
    남 = [b for b in 카드들(맥) if 항목절(맥, b) == "매출" and b not in 구번들]
    L += 근거표(맥, 남) + 범위띠그림(맥, 남, 말="매출") + 결합몫글(맥, "매출")
    L = 덧글넣기(맥, L, "매출")
    return L


# ══════════════════════════════════════════════════════════════════ 5. 영업비용 — 원가 구성 · 변동비 · 고정비 · 매출 대비 비중(Δ)

_산식성격 = {"매출액비율": ("변동", "매출에 비례", "매출 연동분"), "물량단위원가": ("변동", "판매량에 비례", "판매량 연동분"),
          "설비계수": ("계단", "설비 취득원가에 비례", "설비 연동분"), "물가연동": ("고정", "물가에 연동", "물가 연동분")}
_수준연동 = {"소비자물가": ("물가에 연동", "물가 연동분"), "임금": ("임금에 연동", "임금 연동분"),
         "인력": ("임금 × 인원에 연동", "임금 · 인원 연동분"), "자체": ("자체 단위원가 변동률에 연동", "자체 변동분")}


_비율가정 = {1: 80, 2: 84, 3: 88, 4: 92, 5: 112, 6: 116, 7: 120}       # 엔진/원가.비율가정 — 원가 줄 k 의 매출액 대비 비율
_지수가정 = {"원재료": "98", "공공요금": "102", "소비자물가": "106"}
_수준가정 = {"소비자물가": ["106"], "임금": ["504"], "인력": ["504", "501"]}


def 원가가정(x, 산식=None):
    """원가 줄 x 의 산식(주 · 보조)이 읽는 가정 번호(엔진/원가.py 머리 — 산식 넷 + 지표계수). 값이 없는 번호는 표가 거른다."""
    k = x["번호"]
    산식 = 산식 or x.get("산식")
    if 산식 == "매출액비율":
        r = ["%d" % _비율가정[k]] if k in _비율가정 else []
        if _지수가정.get(x.get("가격지수")):
            r.append(_지수가정[x["가격지수"]])
        return r
    if 산식 == "물가연동":
        return ["7%d5" % k, "7%d3" % k] + (_수준가정.get(x.get("수준지수") or "소비자물가") or ["7%d2" % k])
    if 산식 == "물량단위원가":
        return ["7%d5" % k, "7%d3" % k, "7%d2" % k, "7%d7" % k]
    if 산식 == "설비계수":
        return ["7%d1" % k]
    if 산식 == "지표계수":
        return ["7%d8" % k]
    return ["7%d1" % k, "7%d2" % k]


def 원가조각(맥):
    """성격별 원가 조각 — [{이름, 성격, 연동, 식(열 → 식), 가정, 실적(열 → 키 · 없으면 None), 부모}]. 영업비용 = 매출 − 영업이익과 맞지 않으면 빈 목록
    (조각이 틀렸을 때 싣지 않는다). 원가 줄에 보조 산식이 있으면 주 산식 몫 · 보조 산식 몫으로 가른다(엔진 1k1 · 1k2 · 1k3 —
    적용액 = ((1 − 비중) × 주 + 비중 × 보조) × 환율 계수). 갈린 조각의 실적 열은 부모(원가 줄 합계)에만 있다."""
    L_ = _L()
    열 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    조 = []
    for x in 맥.구.get("원가줄") or []:
        k = x["번호"]
        시트, 줄 = P._원가본줄.get(k, (None, None))
        if 시트 is None or not P._원가줄쓰나(맥, x):
            continue
        이 = L_.원가줄이름(맥.구, k)
        주 = _산식성격.get(x.get("산식"), ("고정", "기준 금액", "고정분"))
        if x.get("산식") == "물가연동":                      # 수준지수(엔진 원가 S4-08)를 따른 연동 — 「물가에 연동」 을 인력 · 임금 줄에 찍지 않는다
            주 = (주[0],) + _수준연동.get(x.get("수준지수") or "소비자물가", 주[1:])
        elif x.get("산식") == "매출액비율" and x.get("연동기준") == "판매량":     # 연동 기준이 판매량(불변가격 매출액)이면 판매량에 비례한다(회차 20261023 MO)
            주 = ("변동", "판매량에 비례", "판매량 연동분")
        보 = x.get("보조산식") or "없음"
        W = 맥.기[시트]
        부모 = {"이름": 이, "키": "R:기준:%s:%s:%%s" % (시트, 줄)}
        if 보 != "없음" and all(("1%d%d" % (k, j)) in W for j in (1, 2)) and _n(L_._시점값(맥.가정, "7%d4" % k, "기준")) is not None:
            환 = ("1%d3" % k) in W

            def 몫(c, j, 주몫, k=k, 시트=시트, 환=환):
                w = "S:7%d4:기준" % k
                식 = ["×", ["−", 1, w] if 주몫 else w, "R:기준:%s:1%d%d:%s" % (시트, k, j, c)]
                if 환:
                    식.append("R:기준:%s:1%d3:%s" % (시트, k, c))
                return 식
            보성 = _산식성격.get(보, ("고정", "기준 금액", "고정분"))
            # 가정 칸은 산식이 읽는 번호(2026-10-23 W3 — 7k1 · 7k2 고정이라 매출액비율 · 물가연동 줄의 핵심 가정이 「—」 였다)
            조.append({"이름": "%s — %s" % (이, 주[2]), "성격": 주[0], "연동": 주[1], "식": {c: 몫(c, 1, True) for c in 열},
                      "가정": 원가가정(x) + ["7%d4" % k, "7%d6" % k], "실적": None, "부모": 부모})
            조.append({"이름": "%s — %s" % (이, 보성[2]), "성격": 보성[0], "연동": 보성[1], "식": {c: 몫(c, 2, False) for c in 열},
                      "가정": 원가가정(x, 보) + ["7%d4" % k], "실적": None, "부모": 부모})
        else:
            조.append({"이름": 이, "성격": 주[0], "연동": 주[1], "식": {c: 부모["키"] % c for c in 열}, "가정": 원가가정(x) + ["7%d6" % k],
                      "실적": 부모["키"], "부모": None})
    조.append({"이름": "감가상각비 및 무형자산상각비", "성격": "계단", "연동": "투자에 따라", "식": {c: "R:기준:2.DCF:16:%s" % c for c in 열},
              "가정": ["850", "801", "802", "856"], "실적": "R:기준:2.DCF:16:%s", "부모": None})
    인 = (맥.구.get("인건비") or {}).get("산정방식")
    Pr = 맥.기.get("7.Payroll") or {}
    if 인 == "인원" and "34" in Pr and "43" in Pr:
        조.append({"이름": "기본 인건비(성과급 제외)", "성격": "준고정", "연동": "인원 × 1인당 급여", "식": {c: "R:기준:7.Payroll:34:%s" % c for c in 열},
                  "가정": ["503", "504", "521"], "실적": "R:기준:7.Payroll:34:%s", "부모": None})
        성기준 = "성과급 차감 후 영업이익" if (맥.구.get("인건비") or {}).get("성과급") == "차감후" else "성과급 차감 전 영업이익"
        조.append({"이름": "성과급", "성격": "이익", "연동": 성기준, "식": {c: "R:기준:7.Payroll:43:%s" % c for c in 열},
                  "가정": ["510"], "실적": "R:기준:7.Payroll:43:%s", "부모": None})
    elif 인 in ("인원", "매출액비율") and "14" in Pr:
        조.append({"이름": "인건비", "성격": "준고정" if 인 == "인원" else "변동", "연동": "인원 × 1인당 급여" if 인 == "인원" else "매출에 비례",
                  "식": {c: "R:기준:7.Payroll:14:%s" % c for c in 열}, "가정": ["503", "504"], "실적": "R:기준:7.Payroll:14:%s", "부모": None})
    if (맥.구.get("원가") or {}).get("재고변동반영") == "예" and "153" in 맥.기["5.COGS"]:
        조.append({"이름": "(−) 재고자산 변동 조정", "성격": "조정", "연동": "재고 증감", "식": {c: ["음", "R:기준:5.COGS:153:%s" % c] for c in 열},
                  "가정": ["701"], "실적": "음:R:기준:5.COGS:153:%s", "부모": None})
    for c in 열:                                            # 맞대기 — 조각의 합 = 매출 − 영업이익(예측 열 · 영구)
        합 = 0.0
        for x in 조:
            f = x["식"][c]
            합 += _n(맥.식값(f) if isinstance(f, list) else 맥.값(f)) or 0.0
        매, 영 = _n(맥.값("R:기준:2.DCF:11:%s" % c)), _n(맥.값("R:기준:2.DCF:15:%s" % c))
        if 매 is None or 영 is None or abs(합 - (매 - 영)) > max(1.0, 1e-6 * abs(매)):
            맥.알림.append("영업비용 조각의 합이 매출 − 영업이익과 맞지 않아(%s) 원가 구성 표와 변동비 · 고정비 그림을 싣지 않았다" % c)
            return []
    return 조


def _찍(맥, 식, 꼴):
    return 맥.식(식, 꼴) if isinstance(식, list) else 맥.수(식, 꼴)


def _실식(틀, c):
    """실적 열의 키 틀 → 키 또는 식(「음:」 이면 부호를 바꾼 식)."""
    if 틀.startswith("음:"):
        return ["음", 틀[2:] % c]
    return 틀 % c


def 원가구성표(맥, 조):
    """금액 — 실적 열은 성격별 공시 금액(재료비 및 경비 · 상각 · 인건비 · 성과급 · 재고 변동)과 그 밖의 나머지(넷이 다 있을 때만),
    예측 열은 조각. 갈린 원가 줄은 합계 줄 아래에 몫을 싣는다(몫은 예측 열에만). 실적이 0 인 인건비 · 성과급은 공시가 없는 해라 「—」."""
    열실 = list(맥.실적열)
    열 = 열실 + 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    D = "R:기준:2.DCF:%s:%s"

    def 실값(f):
        try:
            return _n(맥.식값(f)) if isinstance(f, list) else _n(맥.값(f))
        except (KeyError, IndexError, TypeError):
            return None
    # 기능별 표시 회사(매출원가 · 연구개발비 · 판매관리비)는 원가 줄의 실적이 감가상각비를 품는다 — 상각 줄의 실적을 또 실으면
    # 「그 밖의 영업비용」 이 −상각으로 찍힌다(이중 계상). 원가 줄 실적의 합이 상각을 뺀 합보다 영업비용에 가까우면 그 열은 상각을 품은 열이다
    상각틀 = "R:기준:2.DCF:16:%s"
    품음 = set()
    for c in 열실:
        합, 부들 = 0.0, set()
        for x in 조:
            if x["실적"] == 상각틀:
                continue
            if x["부모"]:
                if x["부모"]["이름"] in 부들:
                    continue
                부들.add(x["부모"]["이름"])
                v = 실값(x["부모"]["키"] % c)
            elif x["실적"]:
                v = 실값(_실식(x["실적"], c))
            else:
                continue
            합 += v or 0.0
        상, 매, 영 = 실값(상각틀 % c), 실값(D % ("11", c)), 실값(D % ("15", c))
        if 상 and 상 > 0 and 매 is not None and 영 is not None and 합:
            전 = 매 - 영
            if abs(합 - 전) < abs(합 + 상 - 전) and abs(합 - 전) <= max(1.0, 0.25 * 상):
                품음.add(c)
    줄들 = []
    실키 = {c: [] for c in 열실}
    빈 = {c: False for c in 열실}
    본부모 = set()
    for x in 조:
        부 = x["부모"]
        if 부 and 부["이름"] not in 본부모:                      # 갈린 원가 줄 — 합계 줄 먼저(실적 열 포함)
            본부모.add(부["이름"])
            칸 = []
            for c in 열:
                v = 실값(부["키"] % c)
                칸.append(맥.수(부["키"] % c, "금액") if v is not None else "—")
                if c in 열실:
                    if v is None:
                        빈[c] = True
                    else:
                        실키[c].append(부["키"] % c)
            줄들.append([부["이름"]] + 칸)
        칸 = []
        for c in 열:
            if c not in 열실:
                칸.append(_찍(맥, x["식"][c], "금액"))
                continue
            if not x["실적"] or (x["실적"] == 상각틀 and c in 품음):
                칸.append("—")
                continue
            f = _실식(x["실적"], c)
            v = 실값(f)
            if v is None or (x["성격"] in ("준고정", "이익") and not v):
                칸.append("—")
                빈[c] = True
                continue
            칸.append(_찍(맥, f, "금액"))
            실키[c].append(f)
        줄들.append([_성격붙임(x["이름"], x["성격"])] + 칸)
    나머지, 있다 = ["그 밖의 영업비용(실적의 나머지)"], False
    for c in 열:
        if c in 열실 and 실키.get(c) and not 빈[c]:
            식 = ["−", ["−", D % ("11", c), D % ("15", c)], ["합"] + 실키[c]]
            v = _n(맥.식값(식))
            if v is not None and abs(v) >= 0.5:
                나머지.append(맥.식(식, "금액"))
                있다 = True
                continue
        나머지.append("—")
    if 있다:
        줄들.append(나머지)
    줄들.append(["**영업비용 합계**"] + ["**%s**" % 맥.식(["−", D % ("11", c), D % ("15", c)], "금액") if _n(맥.값(D % ("15", c))) is not None else "—" for c in 열])
    줄들.append(["매출액"] + [맥.수(D % ("11", c), "금액") for c in 열])
    줄들.append(["영업이익률"] + [맥.식(["÷", D % ("15", c), D % ("11", c)], "퍼1") if _n(맥.값(D % ("15", c))) is not None else "—" for c in 열])
    빈칸 = any(빈.values())                                  # 인쇄 조건(「조건 없는 고정 문장은 결함」) — 원천이 금액을 받지 않은 실적 칸이 있을 때만
    몫들 = []
    for x in 조:                                            # 갈린 원가 줄의 산식별 몫 이름 — 이 회사에 있는 것만(2026-10-23 · 회사 무관 고정 괄호 폐기)
        if x["부모"] and " — " in x["이름"]:
            m = x["이름"].split(" — ", 1)[1]
            if m not in 몫들:
                몫들.append(m)
    # v27 문장(교열 78 · 79) — 표 설명은 표 제목(위) · 표 주석(아래)으로
    주 = ["실적은 공시 금액이고, 추정은 원가 항목별 산식으로 계산한 금액입니다."]
    if 몫들:
        주.append("산식별 구분(%s)은 추정 기간에만 나눴습니다." % " · ".join(몫들))
    if 품음:
        주.append("실적 기간의 원가 항목은 감가상각비를 포함한 기능별 금액이므로 감가상각비의 실적은 「—」로 두었습니다. 추정 기간에는 감가상각비를 따로 계산했습니다.")
    if 빈칸:
        주.append("실적 기간의 「—」는 그 해의 금액을 확인하지 못했다는 표시입니다.")
    L = ["**표. 원가 구성**", ""]
    L += P._표(["원가 구성"] + [맥.표기(c) for c in 열], 줄들)
    L += ["", " ".join(주), ""]
    return L


def 줄안이름(맥, 번, 줄이름):
    """원가 항목 줄 안에서 부르는 가정 이름 — 본편 가정 이름에서 그 줄의 원가 항목 이름(「재료비 및 경비 — 설비 연동분」 의 「재료비 및 경비」)을 뗀 것.
    떼고 남은 것이 괄호 덧말뿐이면 괄호를 걷는다(「매출원가 (매출액 대비)」 → 「매출액 대비」). 2026-10-25 레터 재구성 마무리 — 내부 번호(「A-80」) 대신."""
    이 = 이름(맥, 번)
    앞 = ("%s" % (줄이름 or "")).split(" — ", 1)[0].strip()
    if 앞 and 이.startswith(앞) and len(이) > len(앞):
        남 = 이[len(앞):].strip()
        m = re.fullmatch(r"\(([^()]+)\)", 남)
        이 = (m.group(1) if m else 남) or 이
    return 이


def 성격표(맥, 조):
    """변동비 · 고정비 구분 기준 — 원가 항목 · 원가동인 · 성격 · 가정과 기준값(가정 이름 — 번호는 부록 A 에만)."""
    줄들 = []
    for x in 조:
        가 = [("%s %s" % (줄안이름(맥, b, x["이름"]), 가정값글(맥, b))) for b in x["가정"] if 값있나(맥, b)]
        줄들.append([x["이름"], x["연동"], 분류말[x["성격"]], " · ".join(가) or "—"])
    성 = {x["성격"] for x in 조}
    갈 = [말 for 말, 있 in (("판매량 · 매출에 비례하는 비용은 변동비", "변동" in 성), ("설비 · 투자에 따라 계단식으로 늘어나는 비용은 준고정비", "계단" in 성),
                          ("인원 × 1인당 급여로 정하는 비용은 인건비", "준고정" in 성), ("이익에 따라 정하는 성과급은 이익 연동 비용", "이익" in 성),
                          ("물가 · 임금 수준에 따라 변하는 비용은 고정비", "고정" in 성),
                          ("재고 증감은 재고자산 변동 조정", "조정" in 성)) if 있]
    # 성격이 넷 이상이면 두 문장으로(한 문장이 120자를 넘지 않게 — 2026-10-23 W3 고정비 · 조정을 더하며). v27 문장(교열 80 · 81)
    L = (["원가 항목은 원가동인에 따라 변동비와 고정비로 구분했습니다. %s 분류했습니다.%s" % (     # 조사는 끝말의 받침으로(옛 판 「조정로」)
        P.으로(", ".join(갈[:3])), (" 그 밖에 %s 분류했습니다." % P.으로(", ".join(갈[3:]))) if 갈[3:] else ""), ""] if 갈 else [])
    L += P._표(["원가 항목", "원가동인", "성격", "가정과 기준값"], 줄들, ["l", "l", "l", "l"])
    L.append("")
    return L


def 쌓기원가(맥, 조):
    """그림 「쌓기」 — 성격별 영업비용(기준, 연환산 — 단위는 칸 글) + 매출(선)."""
    열 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    묶 = {}
    for x in 조:
        if x["성격"] == "조정":
            continue
        묶.setdefault(분류말[x["성격"]], []).append(x["식"])
    줄들 = []
    for 말, 식목록 in 묶.items():
        줄들.append([말] + [맥.식(["÷", ["합"] + [f[c] for f in 식목록], 맥.년(c)], "어림금액") for c in 열])
    줄들.append(["매출액 (선)"] + [맥.식(["÷", "R:기준:2.DCF:11:%s" % c, 맥.년(c)], "어림금액") for c in 열])
    L = ["<!-- 그림:쌓기 -->", "**그림. 성격별 영업비용과 매출(기준 시나리오, 연환산)** — 막대는 성격별 영업비용을 쌓은 것이고 선은 매출입니다. "
         "재고자산 변동 조정은 뺐습니다.", ""]
    L += P._표(["그림의 값"] + [맥.표기(c) for c in 열], 줄들)
    L.append("")
    return L


def _몫풀이(이):
    """원가 조각 이름 「매출원가 — 매출 연동분」 → 「매출원가 가운데 매출에 연동되는 부분」(문장 안에서 표의 줄 이름을 그대로 끼우지 않는다 — v27 문장 원칙 13)."""
    if " — " not in 이:
        return 이
    앞, 몫 = 이.split(" — ", 1)
    m = re.fullmatch(r"(.+?) 연동분", 몫)
    if m:
        뒤 = "%s에 연동되는 부분" % m.group(1)
    elif 몫 == "자체 변동분":
        뒤 = "자체 단위원가에 연동되는 부분"
    elif 몫 == "고정분":
        뒤 = "고정된 부분"
    else:
        뒤 = 몫
    return "%s 가운데 %s" % (앞, 뒤)


def 비중표(맥, 조):
    """매출 대비 비중 — 마지막 연간 실적 · 첫 예측 기간 · 최종 예측 연도 · 영구기간 · Δ(첫 예측 → 최종 예측, %p). 같은 이름의 원가 · 판관 몫은 합쳐 센다.
    가장 크게 움직인 칸을 문장으로 짚는다."""
    첫, 끝, TV, FY = 맥.첫예측, 맥.끝예측, 맥.영구열, 맥.FY끝
    D = "R:기준:2.DCF:11:%s"
    줄들, 델 = [], []
    for x in 조:
        이, 성, 식들 = x["이름"], x["성격"], x["식"]

        def 비(c, 식들=식들):
            return ["÷", 식들[c], D % c]
        줄 = [_성격붙임(이, 성)]
        줄 += [맥.식(비(첫), "퍼1"), 맥.식(비(끝), "퍼1")] + ([맥.식(비(TV), "퍼1")] if TV else [])
        d = ["−", 비(끝), 비(첫)]
        줄.append(맥.식(d, "퍼p1"))
        줄들.append(줄)
        델.append((이, 성, _n(맥.식값(d)), d, 비(첫), 비(끝), x.get("연동")))
    영 = "R:기준:2.DCF:15:%s"
    줄들.append(["**영업이익률**", "**%s**" % 맥.식(["÷", 영 % 첫, D % 첫], "퍼1"), "**%s**" % 맥.식(["÷", 영 % 끝, D % 끝], "퍼1")] +
               (["**%s**" % 맥.식(["÷", 영 % TV, D % TV], "퍼1")] if TV else []) +
               ["**%s**" % 맥.식(["−", ["÷", 영 % 끝, D % 끝], ["÷", 영 % 첫, D % 첫]], "퍼p1")])
    머 = ["매출 대비", 맥.표기(첫), 맥.표기(끝)] + ([맥.표기(TV)] if TV else []) + ["Δ (%s → %s)" % (맥.열말(첫), 맥.열말(끝))]
    # v27 문장(교열 83 · 84 · 85 · 86) — 앞 두 문장은 본문, 뒤 두 문장은 표 주석(표 바로 아래)
    L = ["금액으로 보면 매출이 늘어나는 동안 모든 원가가 함께 늘어나는 것처럼 보입니다. 원가 항목을 매출로 나눈 비율과 예측기간의 변동(Δ, %p)을 보면, "
         "영업이익률이 어느 항목 때문에 달라지는지 확인할 수 있습니다.", ""]
    L += P._표(머, 줄들)
    L += ["", "같은 이름의 항목이 매출원가와 판매비와관리비에 나뉘어 있으면 합산했습니다. 비율은 기간의 길이에 영향을 받지 않으므로 반기와 연간을 그대로 비교할 수 있습니다.", ""]
    큰 = sorted([x for x in 델 if x[2] is not None], key=lambda t: -abs(t[2]))
    if 큰:
        이, 성, v, d, a, b2, 연 = 큰[0]
        # 까닭은 움직인 방향을 따른다(2026-10-23 — 「매출이 줄어도」 · 「단가가 해마다 내려가」 를 방향 · 산식과 무관하게 찍던 고정 문장 폐기)
        # v27 문장(교열 87 · 검토 메모 1) — 방향은 부호가 아니라 낱말로(`어투.방향`) · 예측은 「~로 추정됩니다」 · 줄 이름(「X — Y 연동분」)은 풀어서
        올 = (v or 0) > 0
        까 = {"계단": "설비와 투자에 연동된 비용이 매출보다 %s 때문입니다" % ("빨리 늘어나기" if 올 else "덜 늘어나기"),
             "준고정": "인원과 급여가 매출보다 %s 때문입니다" % ("빨리 늘어나기" if 올 else "덜 늘어나기"),
             "이익": "성과급은 이익과 함께 늘고 줄기 때문입니다",
             "변동": ("판매량에 비례하는 비용이므로 비중의 변화는 단위원가와 판매단가의 변동률 차이에서 생깁니다" if 연 == "판매량에 비례"
                    else "매출에 비례하는 비용이므로 비중의 변화는 매출 대비 비율 가정의 변화에서 생깁니다"),
             "고정": "매출과 무관하게 정한 수준으로 늘어나 매출보다 %s 때문입니다" % ("빨리 커지기" if 올 else "덜 커지기"),
             "조정": "재고 증감에 따라 달라지기 때문입니다"}.get(성, "") if v else ""
        문 = ["예측기간에 매출 대비 비중이 가장 크게 달라진 항목은 %s." % P.입니다(_몫풀이(이))]
        방 = 어투.방향(v, "높아지는", "낮아지는")
        if 방:
            문.append("매출 대비 비중은 %s에서 %s %s %s 것으로 추정됩니다." % (맥.식(a, "퍼1"), P.으로(맥.식(b2, "퍼1")), 맥.식(d if 올 else ["음", d], "폭p1"), 방))
        if 까:
            문.append(까 + ".")
        영첫, 영끝 = ["÷", 영 % 첫, D % 첫], ["÷", 영 % 끝, D % 끝]
        첫글, 끝글 = 맥.식(영첫, "퍼1"), 맥.식(영끝, "퍼1")
        영방 = 어투.방향(_n(맥.식값(["−", 영끝, 영첫])), "높아지는", "낮아지는")
        if 영방 and 첫글 != 끝글:
            문.append("같은 기간 영업이익률은 %s에서 %s %s 것으로 추정됩니다." % (첫글, P.으로(끝글), 영방))
        else:
            문.append("같은 기간 영업이익률은 %s 안팎으로 추정됩니다." % 첫글)
        L += [" ".join(문), ""]
    # 그림 「비중」 — Δ 막대
    줄2 = [[x[0], 맥.식(x[3], "퍼p1")] for x in 델 if x[2] is not None]
    if len(줄2) >= 2:
        L += 출처달기(맥, ["<!-- 그림:비중 -->", "**그림. 매출 대비 비중의 변화(%s → %s, %%p)** — 오른쪽 막대는 비중이 커져 영업이익률을 낮춘 항목, 왼쪽 막대는 비중이 줄어 "
                          "영업이익률을 높인 항목입니다." % (맥.열말(첫), 맥.열말(끝)), ""], ["R:기준:5.COGS:x:%s" % 첫, "R:기준:2.DCF:11:%s" % 끝])
        L += P._표(["원가 항목", "Δ"], 줄2, ["l", "r"])
        L.append("")
    return L


def 비용절(맥, 번):
    L = 머리("비용", 번)
    L += 이음(맥, "비용") + 절머리(맥, "비용") + N이야기(맥, "비용")
    앞 = len(L)
    기 = P.비용절(맥, 번, 인건비=False)[2:]
    조 = 원가조각(맥)
    if 조:
        L += 원가구성표(맥, 조)
        L += 성격표(맥, 조)
        L += 출처붙여(맥, 쌓기원가, 맥, 조)
        L += 레버리지그림(맥, 조)                              # 2026-10-25 R5 — 고정비 몫 · 매출 대비 비중
        L += 비중표(맥, 조)
    import 레터회사그림 as _회                                # noqa: PLC0415 — v27 7단계(다) 판매량을 따르는 매출원가가 있으면 매출과 원가의 두 선
    L += _회.원가두선그림(맥)
    L += 기
    번들 = []
    for x in 맥.구.get("원가줄") or []:
        k = x["번호"]
        보 = x.get("보조산식") or "없음"
        번들 += 원가가정(x) + (원가가정(x, 보) if 보 != "없음" else []) + ["7%d4" % k, "7%d6" % k]
    번들 += ["701", "702", "168", "172"]
    L += 가정표(맥, 번들, "원가 가정")
    L += 근거블록(맥, 번들, "비용")
    L = 덧글넣기(맥, L, "비용", "판관", "인건비미분리", 앞=앞)
    맥.서술("비용.구성")
    return L


# ══════════════════════════════════════════════════════════════════ 6. 인건비

def 인건비절(맥, 번):
    L = 머리("인건비", 번)
    L += 이음(맥, "인건비") + 절머리(맥, "인건비") + N이야기(맥, "인건비")
    앞 = len(L)
    Pr = 맥.기.get("7.Payroll") or {}
    FY = 맥.FY끝
    D = "R:기준:2.DCF:%s:%s"
    if FY and _n((Pr.get("14") or {}).get(FY)) and _n(맥.값(D % ("15", FY))) is not None:
        문 = ["%s 인건비는 %s 영업비용의 %s." % (맥.열말(FY), P.으로(맥.수("R:기준:7.Payroll:14:%s" % FY, "금액")),
                                         P.입니다(맥.식(["÷", "R:기준:7.Payroll:14:%s" % FY, ["−", D % ("11", FY), D % ("15", FY)]], "퍼1")))]
        if _n((Pr.get("43") or {}).get(FY)):
            문.append("그 가운데 성과급은 %s, 이익에 연동돼 사이클에 따라 크게 달라집니다." % P.이고(맥.수("R:기준:7.Payroll:43:%s" % FY, "금액")))
        L += [" ".join(문), ""]
    인 = 맥.구.get("인건비") or {}
    범 = []
    if 인.get("급여범위") == "연결":
        범.append("급여는 연결 종업원급여")
    if 인.get("인원범위") == "본사":
        범.append("인원은 본사 인원")
    if 범:
        L += ["%s 기준입니다. 둘의 범위가 달라 1인당 평균급여는 공시된 1인 평균 급여와 다를 수 있습니다." % ", ".join(범), ""]
    L += P._인건비글(맥)
    L += 가정표(맥, ["503", "504", "510", "511", "512", "521", "134", "138", "142"], "인건비 가정")
    # 기능별 배분
    열 = [c for c in 맥.실적열 if _n((Pr.get("23") or {}).get(c)) is not None and c != 맥.실적열[0]] + 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    줄들 = []
    for 키, 말 in (("23", "매출원가 (노무비)"), ("24", "경상연구개발비 (연구원 인건비)"), ("25", "판매비와관리비 (인건비)")):
        if 키 in Pr:
            줄들.append([말] + [맥.수("R:기준:7.Payroll:%s:%s" % (키, c), "금액") if _n((Pr.get(키) or {}).get(c)) is not None else "—" for c in 열])
    # 영업비용을 한 줄로 표시하는 회사(예측 열의 매출원가가 모두 0)는 기능별 배분 표를 싣지 않는다 — 실적 열은 공시의 매출원가 노무비를,
    # 예측 열은 판매비와관리비 100% 를 실어 배분이 어긋나 보였다(2026-10-24 W10 · 회차 20261024)
    원가값 = [_n(맥.값("R:기준:5.COGS:17:%s" % c)) for c in 맥.예측열]
    단일 = bool(원가값) and all(v is not None and abs(v) < 1e-9 for v in 원가값)
    if 줄들 and 단일:
        L += ["회사는 영업비용을 한 줄로 표시하므로 인건비를 매출원가와 판매비와관리비로 나누지 않았습니다.", ""]
    elif 줄들:
        L += ["인건비는 매출원가 · 경상연구개발비 · 판매비와관리비로 나눠 배분했습니다. 배분은 표시 방법의 문제이므로 영업이익에는 영향이 없습니다.", ""]
        L += P._표(["기능별 배분"] + [맥.표기(c) for c in 열], 줄들)
        L.append("")
    독 = 근거글(맥, "956")
    if 독:
        L += [독, ""]
    if _n((Pr.get("44") or {}).get(맥.첫예측)) is not None and 맥.영구열 and _n((Pr.get("44") or {}).get(맥.영구열)) is not None:
        값 = [(c, _n((Pr.get("44") or {}).get(c))) for c in 맥.예측열 if _n((Pr.get("44") or {}).get(c)) is not None]
        lo = min(값, key=lambda t: t[1])
        첫v, 영v = _n((Pr.get("44") or {}).get(맥.첫예측)), _n((Pr.get("44") or {}).get(맥.영구열))
        R44 = "R:기준:7.Payroll:44:%s"
        if lo[0] != 맥.첫예측 and lo[1] < 첫v:               # 인쇄 조건(견본 실측: 「2026년 18.8%에서 2026년 18.8%로 내려갔다가」 · 성과급 없는 회사에 성과급 문장)
            글 = "매출 대비 인건비율은 %s %s에서 %s %s로 낮아졌다가 영구기간에는 %s 되는 것으로 추정됩니다." % (
                맥.열말(맥.첫예측), 맥.수(R44 % 맥.첫예측, "퍼1"), 맥.열말(lo[0]), 맥.수(R44 % lo[0], "퍼1"), P.이(맥.수(R44 % 맥.영구열, "퍼1")))
            D11 = "R:기준:2.DCF:11:%s"
            매줄 = _n(맥.값(D11 % 맥.끝예측)) is not None and _n(맥.값(D11 % lo[0])) is not None and _n(맥.값(D11 % 맥.끝예측)) / 맥.년(맥.끝예측) < _n(맥.값(D11 % lo[0])) / 맥.년(lo[0])
            if ((맥.구.get("인건비") or {}).get("성과급") or "없음") != "없음" and 영v is not None and 영v > lo[1] and 매줄:
                글 += " 매출이 줄어드는 동안 인원과 급여는 줄지 않고, 성과급만 이익과 함께 줄기 때문입니다."
        else:
            글 = "매출 대비 인건비율은 %s %s, 영구기간 %s 추정됩니다." % (맥.열말(맥.첫예측), 맥.수(R44 % 맥.첫예측, "퍼1"), P.으로(맥.수(R44 % 맥.영구열, "퍼1")))
        L += [글, ""]
    # 그림 — 고정층 · 성과급
    열2 = [c for c in 맥.실적열 if _n((Pr.get("34") or {}).get(c))] + 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    if "34" in Pr and "43" in Pr and len(열2) >= 3:
        줄2 = [["기본 인건비(성과급 제외)"] + [맥.식(["÷", "R:기준:7.Payroll:34:%s" % c, 맥.년(c)], "어림금액") if _n((Pr.get("34") or {}).get(c)) else "—" for c in 열2],
              ["성과급"] + [맥.식(["÷", "R:기준:7.Payroll:43:%s" % c, 맥.년(c)], "어림금액") if _n((Pr.get("43") or {}).get(c)) else "—" for c in 열2]]
        L += 출처달기(맥, ["<!-- 그림:쌓기 -->", "**그림. 인건비의 구성(기준 시나리오, 연환산)** — 아래 칸이 인원 × 1인당 급여로 정한 인건비, 위 칸이 이익에 연동한 성과급입니다.", ""],
                    ["R:기준:7.Payroll:34:%s" % c for c in 열2])
        L += P._표(["그림의 값"] + [맥.표기(c) for c in 열2], 줄2)
        L.append("")
    L += 인원그림(맥)                                         # 2026-10-25 R5 — 인원 × 1인당 평균급여(실적과 시나리오 셋)
    L += 근거블록(맥, ["503", "504", "510", "511", "512", "521", "501"], "인건비")
    L = 덧글넣기(맥, L, "인건비", 앞=앞)
    return L


# ══════════════════════════════════════════════════════════════════ 7. 설비투자와 감가상각

def _달말(t):
    """「2026-01」 → 「2026년 1월」(글 그대로 — 날짜는 값 꼴 숫자가 아니다)."""
    m = re.match(r"^(\d{4})-(\d{1,2})$", "%s" % t)
    return "%s년 %d월" % (m.group(1), int(m.group(2))) if m else "%s" % t


def _장(맥, 키):
    """생산능력(천 장/월) → 「5천 장」 · 「4만 장」(만 단위로 떨어지면 만으로)."""
    v = _n(맥.값(키))
    if v is not None and v >= 10 and abs(v / 10 - round(v / 10)) < 1e-9:
        return "%s만 장" % 맥.식(["÷", 키, 10], "수0")
    return "%s천 장" % 맥.수(키, "수0")


def 일정글(맥):
    """라인의 생산능력 일정(가정 「일정」) — 반입 꼴은 첫 반입 · 간격 · 횟수 · 단위 능력, 점 꼴은 점들. 숫자는 장부 키(G:)."""
    일 = (맥.가정.get("일정") or {}).get("라인") or {}
    글 = []
    for k in sorted(일, key=lambda t: int(t) if ("%s" % t).isdigit() else 0):
        x = 일[k]
        if not isinstance(x, dict):
            continue
        이 = 맥.원고글(x.get("_이름"), "일정.라인.%s._이름" % k) or ("%s" % k)
        if x.get("꼴") == "반입" and _글(x.get("시작")):
            간 = x.get("간격개월")
            간키 = ("G:일정:라인:%s:간격개월:기준" % k) if isinstance(간, dict) else ("G:일정:라인:%s:간격개월" % k)
            횟 = x.get("횟수")
            횟키 = ("G:일정:라인:%s:횟수:기준" % k) if isinstance(횟, dict) else ("G:일정:라인:%s:횟수" % k)
            try:
                문 = ["%s 클린룸 %s개를 %s부터 %s개월 간격으로 들이고, 클린룸 하나가 월 %s의 생산능력을 더한다고 가정했습니다." % (
                    P.은(이), 맥.수(횟키, "수0"), _달말(x["시작"]), 맥.수(간키, "수0"), _장(맥, "G:일정:라인:%s:단위능력" % k))]
                if _n(x.get("투입지연개월")):
                    문.append("반입한 클린룸은 %s개월 뒤부터 생산에 쓰인다고 가정했습니다." % 맥.수("G:일정:라인:%s:투입지연개월" % k, "수0"))
                if isinstance(간, dict) and len({("%s" % v) for v in 간.values()}) > 1:
                    문.append("반입 간격은 비관 시나리오 %s개월, 낙관 시나리오 %s개월입니다." % (
                        맥.수("G:일정:라인:%s:간격개월:비관" % k, "수0"), 맥.수("G:일정:라인:%s:간격개월:낙관" % k, "수0")))
                글.append(" ".join(문))
            except (KeyError, TypeError, ValueError):
                continue
        elif x.get("꼴") == "점" and isinstance(x.get("점"), list) and x["점"]:
            점 = []
            for j, p in enumerate(x["점"]):
                if isinstance(p, list) and len(p) == 2:
                    점.append("%s 월 %s" % (_달말(p[0]), _장(맥, "G:일정:라인:%s:점:%d:1" % (k, j))))
            if len(점) >= 2:
                글.append("%s의 생산능력은 %s을 거쳐 %s에 이른다고 가정했습니다." % (이, ", ".join(점[:-1]), 점[-1]))
    return 글


def 재투자절(맥, 번):
    L = 머리("재투자", 번)
    L += 이음(맥, "재투자") + 절머리(맥, "재투자") + N이야기(맥, "재투자")
    앞 = len(L)
    L += P.설비글(맥)
    일 = 일정글(맥)
    if 일:
        L += ["투자 금액은 생산능력 일정에 맞춰 연도별로 반영했습니다. %s" % " ".join(일), ""]
    X = 맥.기["8.CapEx"]
    프 = [x for x in (맥.구.get("투자") or {}).get("프로젝트") or [] if ("%d" % (140 + x["번호"])) in X]
    if "101" in X and 프:
        유 = ["합"] + ["R:기준:8.CapEx:101:%s" % c for c in 맥.예측열]
        증 = ["합"] + ["R:기준:8.CapEx:%d:%s" % (140 + x["번호"], c) for x in 프 for c in 맥.예측열]
        유말 = {"취득원가비율": "설비 취득원가에 유지율을 곱해", "판매량연동": "판매량에 연동해", "상각연동": "감가상각비에 연동해",
              "매출연동": "매출에 연동해", "직접": "연도별로 입력한 금액으로"}.get((맥.구.get("투자") or {}).get("유지규칙"), "")   # 인쇄 조건 — 유지 규칙대로(견본 실측: 판매량연동에 「취득원가 × 유지율」)
        환 = "(환율 조정 전)" if ((맥.구.get("환율") or {}).get("경로") or "없음") != "없음" else ""     # 환율 경로가 없는 모델에는 붙이지 않는다(2026-10-23)
        L += ["예측기간 CAPEX%s는 유지 · 공정 전환 투자 %s, 성장 투자 프로젝트 %s.%s 성장 투자 프로젝트는 %s 끝나면 멈추는 것으로 가정했습니다." % (
            환, 맥.식(유, "금액"), P.입니다(맥.식(증, "금액")), (" 유지 투자는 %s 매년 이어지고," % 유말) if 유말 else "",
            "공장 일정이" if any(x.get("판매량산정") == "능력" for x in 맥.구.get("매출구분") or []) else "투자 일정이"), ""]
    D = "R:기준:2.DCF:%s"
    if 맥.FY끝 and _n(맥.값(D % "11:%s" % 맥.끝예측)) is not None:
        순 = ["합"] + [["−", "R:기준:8.CapEx:31:%s" % c, "R:기준:8.CapEx:34:%s" % c] for c in 맥.예측열] + ["R:기준:9.WC:18:%s" % c for c in 맥.예측열]
        늘 = ["−", D % "11:%s" % 맥.끝예측, D % "11:%s" % 맥.FY끝]
        if _n(맥.식값(순)) and _n(맥.식값(순)) > 0:
            # v27 문장(교열 98) — 증감은 방향 낱말로 · 예측은 「~로 추정됩니다」 · 가정은 「~로 가정했습니다」(매출이 줄어드는 판에는 Sales-to-Capital 문장을 싣지 않는다)
            늘v = _n(맥.식값(늘)) or 0.0
            문 = ["예측기간의 순투자(CAPEX − 감가상각비 + 순운전자본 증감) 합계는 %s, 같은 기간 연 매출은 %s %s 것으로 추정됩니다(%s → %s)." % (
                P.이고(맥.식(순, "금액")), 맥.식(늘 if 늘v >= 0 else ["음", 늘], "금액"), "늘어나는" if 늘v >= 0 else "줄어드는", 맥.열말(맥.FY끝), 맥.열말(맥.끝예측))]
            if 늘v > 0:
                문.append("늘어난 매출을 순투자로 나눈 Sales-to-Capital로 보면 순투자 1%s 연 매출을 %s 늘리는 것으로 추정됩니다." % (
                    P.이(_L().통화말(맥.메타)), 맥.식(["÷", 늘, 순], "원2")))          # 통화는 표시통화(「1달러가」 — 2026-10-23)
            문.append("영구기간에는 NOPLAT의 %s 재투자한다고 가정했습니다(%s)." % (P.을(맥.수(D % "49", "퍼1")), 곳(맥, "영구") or "Terminal Value 절"))
            L += [" ".join(문), ""]
    L += 투자그림(맥)                                         # 2026-10-25 R5 — 유지 · 성장 · 프로젝트 CAPEX 와 감가상각비
    if M.팹들(맥):
        소 = ["### %s" % 공장소절, ""] + M.공장절(맥, 번)[2:] + M.공장문장(맥) + 출처붙여(맥, 공장그림, 맥)
        if getattr(맥, "_절글끔", False):                       # 레터 v27 6단계 — 추정 블록이면 소절 통째를 부록 「추정 블록의 근거 표」 의 제 이름 자리로(`블록절`)
            맥._블록소절 = (getattr(맥, "_블록소절", None) or []) + [(공장소절, 소[2:])]
        else:
            L += 소
    입증 = (맥.가성 or {}).get("증설") or []
    증 = [맥.원고글(x.get("이름"), "가격성립.증설.%d.이름" % i) for i, x in enumerate(입증)]
    증 = [x for x in 증 if x]
    if 증 and 곳(맥, "역산"):
        # 2026-10-26 — 까닭은 공표일로 가른다(날짜 둘 판은 사이 공시가 모두 평가기준일 전이다 — 「뒤에 발표된」 은 그때만)
        기준일 = "%s" % (맥.메타.get("평가기준일") or "")
        뒤 = any(("%s" % (x.get("공표일") or "")) > 기준일 for x in 입증 if 기준일 and x.get("공표일"))
        까 = ("금액과 시점이 평가기준일에 공시되지 않았거나 평가기준일 뒤에 발표된 투자입니다" if 뒤 else
              "평가기준일 전에 공시됐으나 금액 · 시점 · 생산능력을 함께 세울 공시가 없는 투자입니다")
        L += ["%s 기준 시나리오에서 제외했습니다. %s. 이 투자를 넣었을 때의 주당가치는 %s에서 다룹니다(%s)." % (
            P.은(P._나열(증)), 까, 절이름(맥, "역산"), 곳(맥, "역산")), ""]
    # 유지 규칙 · 상각 방식마다 쓰는 줄이 다르다 — 값이 있는 줄만 선다(가정표). 매출연동(851 · 867) · 판매량(854 · 855 · 858) ·
    # Sales-to-Capital(859) · 정률 상각(156 · 164) 줄이 빠져 이 구조의 회사에는 표가 서지 않았다(회차 20261023 NAVER · TSLA)
    번들 = (["850", "851", "854", "855", "858", "859", "801", "802", "156", "164", "160", "867", "852", "853", "856", "857"]
          + ["%d" % (860 + x["번호"]) for x in (맥.구.get("투자") or {}).get("프로젝트") or []])
    L += _표앞글(L, 가정표(맥, 번들, "투자 가정"), "**표. 투자 가정과 그 근거**")         # v27 문장(교열 99) — 표 제목으로
    L += 근거블록(맥, 번들, "재투자")
    L = 덧글넣기(맥, L, "재투자", "공장", 앞=앞)
    return L


공장소절 = "공장별 매출 · 투자와 ROIC"                   # 설비투자 절의 소절 — 엔진이 공장별 값(요약.공장)을 낸 때만 선다


def 공장그림(맥):
    """그림 「공장」 — 공장별 영구기간 ROIC 막대와 영구기간 WACC 선."""
    팹 = M.팹들(맥)
    W = "R:기준:요약:공장:WACC영구"
    if not 팹 or _n(맥.값(W)) is None:
        return []
    줄들 = [[M._팹이름(맥, k), 맥.수("R:기준:요약:공장:팹:%d:ROIC" % k, "퍼1")] for k, _x in 팹]
    줄들.append(["영구기간 WACC (선)", 맥.수(W, "퍼1")])
    L = ["<!-- 그림:공장 -->", "**그림. 공장별 영구기간 ROIC과 영구기간 WACC** — 막대가 선의 오른쪽에 있으면 그 공장의 투자가 자본비용보다 많이 남깁니다.", ""]
    L += P._표(["공장", "ROIC"], 줄들, ["l", "r"])
    L.append("")
    return L


# ══════════════════════════════════════════════════════════════════ 8. 운전자본

def 계정분류(맥):
    """평가기준일 재무상태표 계정의 자리 — 운전자본 · 미지급 항목 · 이자부부채 · 현금성 · 비영업 · 부채성 차감 · 제외(가정 「소비처」)."""
    소 = 맥.가정.get("소비처") or {}
    원 = 맥.가정.get("원천") or {}
    c = 맥.기준일열
    if not 소 or not c:
        return []
    이름표 = {}
    for 모듈 in ("sec_원천", "dart_원천"):                   # 뒤엣것이 앞엣것을 덮는다(국내 이름이 기준) — 둘 다 13번 원천 시트의 줄 이름
        try:
            이름표.update(dict(__import__(모듈).행이름))
        except Exception:                                    # noqa: BLE001
            pass
    자리말 = {"운전자본": "운전자본(영업)", "이자부부채": "이자부부채(브리지에서 뺌)", "현금성": "현금 및 단기금융자산(브리지에서 더함)",
            "비영업자산": "비영업자산(브리지에서 더함)", "영업자산": "영업자산(설비 · 무형)", "부채성차감": "부채성 항목(브리지에서 뺌)", "명시적 제외": "반영하지 않음"}
    줄들 = []
    for 차 in ("운전자본", "이자부부채", "부채성차감", "현금성", "비영업자산", "명시적 제외"):
        for k in sorted(소, key=lambda t: int(t) if ("%s" % t).isdigit() else 0):
            if 소[k] != 차:
                continue
            v = _n((원.get("%s" % k) or {}).get(c))
            이 = 이름표.get(int(k)) if ("%s" % k).isdigit() else None
            if not v:
                continue
            if not 이:                                       # 이름표에 없는 줄을 조용히 버리지 않는다 — 저자에게 알린다(표에는 이름 없이 싣지 않는다)
                맥.알림.append("계정 표 — 원천 %s행(%s)의 이름이 이름표에 없어 표에 싣지 못했다(`dart_원천.행이름`)" % (k, 차))
                continue
            줄들.append([이, 자리말.get(차, 차), "H:%s:%s" % (k, c)])
    if len(줄들) < 3:                                        # 싣지 않을 표는 장부에 적기 전에 비킨다(게이트 ⑦ 「초안에 없다」 — 회차 20261023 NAVER)
        return []
    줄들 = [[이, 자, 맥.수(키, "금액")] for 이, 자, 키 in 줄들]
    # v27 문장(교열 105 · 106 · 검토 메모 2) — 표 제목(위)과 분류 문장(아래) · 다른 절은 문장 끝 괄호로
    L = ["**표. %s 재무상태표 계정의 분류**" % P.재무날말(맥), ""]
    L += P._표(["재무상태표 계정", "이 평가에서의 분류", "%s 장부금액" % 맥.열말(c)], 줄들, ["l", "l", "r"])
    L += ["", "이자부부채 · 현금 · 비영업자산으로 분류한 계정은 운전자본에 넣지 않고 가치 브리지에서 더하거나 뺐습니다%s." % (
        ("(%s)" % 곳(맥, "주주가치")) if 곳(맥, "주주가치") else ""), ""]
    return L


def _기타운전(맥, W, 열):
    """순운전자본(14) − (매출채권 10 + 재고 11 − 매입채무 12) 가 어느 열이든 0 이 아니면 {열: 식} — 아니면 {}(줄을 세우지 않는다)."""
    if not all(k in W for k in ("10", "12", "14")):
        return {}
    낸, 있음 = {}, False
    for c in 열:
        v = [_n((W.get(k) or {}).get(c)) for k in ("10", "11", "12", "14")]
        if v[0] is None or v[2] is None or v[3] is None:
            continue
        식 = ["−", "R:기준:9.WC:14:%s" % c, ["합", "R:기준:9.WC:10:%s" % c] + (["R:기준:9.WC:11:%s" % c] if v[1] is not None else [])
             + [["음", "R:기준:9.WC:12:%s" % c]]]
        낸[c] = 식
        if abs(v[3] - (v[0] + (v[1] or 0.0) - v[2])) > max(0.5, 1e-6 * abs(v[3])):
            있음 = True
    return 낸 if 있음 else {}


def 운전자본절(맥, 번):
    L = 머리("운전자본", 번)
    L += 이음(맥, "운전자본") + 절머리(맥, "운전자본") + N이야기(맥, "운전자본")
    앞 = len(L)
    W = 맥.기["9.WC"]
    열 = [c for c in 맥.실적열 if _n((W.get("10") or {}).get(c)) is not None] + 맥.예측열
    줄들 = []
    기타 = _기타운전(맥, W, 열)                              # 1.1.2 — 구성 합 ≠ 순운전자본이면 그 차를 「기타 순운전자본」 줄로(숨은 구성 줄 금지 · 정합 「표 구성 합」)
    for 키, 말, 꼴 in (("10", "매출채권", "금액"), ("11", "재고자산", "금액"), ("12", "(−) 매입채무", "금액"), ("기타", "기타 순운전자본", "금액"),
                    ("14", "**순운전자본**", "금액"), ("21", "매출채권 회전일수", "일"), ("22", "재고자산 회전일수", "일"), ("23", "매입채무 회전일수", "일")):
        if 키 == "기타":
            if 기타:
                줄들.append([말] + [맥.식(기타[c], 꼴) if c in 기타 else "—" for c in 열])
            continue
        if 키 in W:
            줄들.append([말] + [(맥.수("R:기준:9.WC:%s:%s" % (키, c), 꼴) if _n((W.get(키) or {}).get(c)) not in (None, 0.0) or 꼴 == "금액" else "—")
                              if _n((W.get(키) or {}).get(c)) is not None else "—" for c in 열])
            if all(x == "—" for x in 줄들[-1][1:]):               # 그 계정을 쓰지 않는 모델(회전일수가 전부 빈칸)이면 줄을 지운다
                줄들.pop()
    if 줄들:
        실수 = len([c for c in 열 if c in 맥.실적열])
        대시 = any(x == "—" for 줄 in 줄들 if "회전일수" in 줄[0] for x in 줄[1:1 + 실수])     # 인쇄 조건 — 실적 회전일수에 「—」 가 있을 때만
        L += ["**표. 매출채권 · 재고자산 · 매입채무의 실적과 추정**", ""]          # v27 문장(교열 104) — 표 제목 · 표 주석으로
        L += P._표(["순운전자본"] + [맥.표기(c) for c in 열], 줄들)
        L.append("")
        if 대시:
            L += ["실적 기간의 회전일수가 「—」이면 그 기간의 회전 기준액(발생원가)이 공시에서 따로 구분되지 않습니다.", ""]
    L += 계정분류(맥)
    L += P.운전글(맥)
    L += 가정표(맥, ["178", "182", "186", "190", "701", "901", "902", "903"], "운전자본 가정")
    if "18" in W and 맥.예측열:
        # 방향 문장은 순운전자본의 부호를 따른다(2026-10-23 실측 — 순운전자본이 음수인 회사에도 「묶여 FCFF를 줄인다」 가 찍혔다)
        음 = (_n((W.get("14") or {}).get(맥.예측열[0])) or 0.0) < 0
        # v27 문장(교열 109) — 운전자본이 「묶이고 · 풀려」 FCFF 를 「줄이고 · 늘린다」(사람처럼 행동) → 잔액이 늘고 줄어 FCFF 가 줄고 는다
        방향 = ("순운전자본이 음수이므로 매출이 늘어나는 해에는 FCFF가 늘고, 매출이 줄어드는 해에는 FCFF가 줄어듭니다." if 음 else
              "매출이 늘어나는 해에는 운전자본이 늘어 FCFF가 줄고, 매출이 줄어드는 해에는 운전자본이 줄어 FCFF가 늘어납니다.")
        L += ["예측기간 순운전자본 증감의 합은 %s. %s" % (P.입니다(맥.식(["합"] + ["R:기준:9.WC:18:%s" % c for c in 맥.예측열], "금액")), 방향), ""]
    열2 = [c for c in 맥.실적열 if _n((W.get("10") or {}).get(c)) is not None] + 맥.예측열
    if all(k in W for k in ("10", "11", "12")) and len(열2) >= 3:
        줄2 = [["매출채권"] + [맥.수("R:기준:9.WC:10:%s" % c, "어림금액") for c in 열2],
              ["(−) 매입채무"] + [맥.식(["음", "R:기준:9.WC:12:%s" % c], "어림금액") for c in 열2],
              ["순운전자본 (선)"] + [맥.수("R:기준:9.WC:14:%s" % c, "어림금액") for c in 열2]]
        재고 = any(abs(_n((W.get("11") or {}).get(c)) or 0.0) >= 0.5 for c in 열2)     # 재고가 없는 회사(플랫폼 · 서비스)는 재고 줄 · 말을 뺀다
        if 재고:
            줄2.insert(1, ["재고자산"] + [맥.수("R:기준:9.WC:11:%s" % c, "어림금액") for c in 열2])
        기타2 = _기타운전(맥, W, 열2)
        if 기타2:
            줄2.insert(len(줄2) - 1, ["기타 순운전자본"] + [맥.식(기타2[c], "어림금액") if c in 기타2 else "—" for c in 열2])
        # 돈 단위는 칸 글이 갖는다(그림이 칸 글에서 읽는다 — 「조 원」 을 캡션에 박지 않는다 · 2026-10-23 USD 회사)
        L += 출처달기(맥, ["<!-- 그림:쌓기 -->", "**그림. 순운전자본의 구성(기준 시나리오, 기말 잔액)** — 0 위는 매출채권%s, 0 아래는 매입채무이고 선은 순운전자본입니다."
                          % ("과 재고자산" if 재고 else ""), ""], ["R:기준:9.WC:14:%s" % c for c in 열2])
        L += P._표(["그림의 값"] + [맥.표기(c) for c in 열2], 줄2)
        L.append("")
    L += 회전그림(맥)                                         # 2026-10-25 R5 — 계정별 회전일수(실적과 시나리오 셋)
    L += 근거블록(맥, ["178", "182", "186", "190", "901", "902", "903"], "운전자본")
    L = 덧글넣기(맥, L, "운전자본", 앞=앞)
    return L


# ══════════════════════════════════════════════════════════════════ 9~12. 법인세 · 할인율 · Terminal Value · 가치 브리지

def 절머리(맥, 절키):
    """항목 절 머리의 「이 절이 담은 Narrative」 줄 — 서사연결 가운데 이 절(항목 절 판정 — 인건비 · 운전자본을 따로 가른다)의 가정을 가리키는 줄."""
    return N.절머리(맥, 절키, 판정=lambda b: (항목절(맥, b) if ("%s" % b).isdigit() else N.절가정(b)))


def N이야기(맥, 절키):
    """항목 절 머리의 「이 이야기에서 이 줄은 왜 움직이나 / 왜 그대로인가」 한 문장(`이야기문장` — 2026-10-25 R4)."""
    return 이야기문장(맥, 절키)


def 감싼절(키, f, 이음키=None, 덧=None):
    def g(맥, 번):
        L = f(맥, 번)
        L[0] = "## %d. %s" % (번, 제목[키])
        머 = 이음(맥, 이음키 or 키) + 절머리(맥, 키) + N이야기(맥, 키)
        L = L[:2] + 머 + L[2:]
        if 덧:
            L += 덧(맥)
        return 덧글넣기(맥, L, 키, 앞=2 + len(머))
    return g


def _표앞글(앞, 표, 문장):
    """그림 바로 뒤에 표가 오면 사이에 한 문장(그림 블록이 뒤의 표까지 「그림의 숫자」 로 삼키지 않게 — `레터HTML._표줄들` 은 빈 줄 너머의 표를 잇는다)."""
    꼬 = next((x for x in reversed(앞 or []) if ("%s" % x).strip() and not ("%s" % x).strip().startswith("|")), "")
    return ([문장, ""] if (표 and ("%s" % 꼬).startswith(("**그림", "<!-- 그림:"))) else []) + 표


def 세금덧(맥):
    번들 = ["196", "200", "208", "940", "941"]
    import 레터회사그림 as _회                                # noqa: PLC0415
    그 = FCFF그림(맥) + _회.결손금그림(맥)                     # 2026-10-25 R5 — FCFF 다리 · v27 7단계(다) 이월결손금 사용 일정
    return 그 + _표앞글(그, 가정표(맥, 번들, "법인세 가정"), "**표. 법인세 가정과 그 근거**") + 근거블록(맥, 번들, "세금")      # v27 문장(교열 117)


def 영구덧(맥):
    번들 = ["212", "219", "213", "857"]
    그 = TV몫그림(맥) + 정합그림(맥)                            # 2026-10-25 R5 — TV 몫 · 영구 정합
    return 그 + _표앞글(그, 가정표(맥, 번들, "Terminal Value 가정"), "**표. Terminal Value 가정과 그 근거**") + 근거블록(맥, 번들, "영구")      # v27 문장(교열 154)


def 할인율덧(맥):
    return WACC그림(맥) + 베타그림(맥) + 결합몫글(맥, "할인율")                            # 2026-10-25 R5 — WACC 쌓기 · 유사기업 βU


def 브리지덧(맥):
    L = []
    그 = 출처붙여(맥, M.가치그림, 맥)
    if 그:                                                   # v27 문장(교열 157) — 그림 앞의 안내 문장은 지웠다(그림 제목이 같은 일을 한다)
        L += 그
    L += M.PER다리(맥, 가치=True)
    return L


# ══════════════════════════════════════════════════════════════════ 13. 시나리오 — 이야기에서 값까지(불릿 없이)

def _묶음본편이름(맥, 이, 번들):
    """1.1.21 — 시나리오 문장의 가정 이름. 폭포 묶음 이름은 매출 구분 이름을 뗀 짧은 이름(「판매가격 변동률」)이라, 저자가 독자 이름
    (`Narrative.독자.묶음이름`)을 주지 않았고 묶음의 가정이 한 구분 것이면 본편 가정 이름(「가 제품 판매가격 변동률」)으로 쓴다.
    여러 구분의 가정을 묶은 것이면 구분 이름을 앞에 모은다(「가 · 나 제품 판매가격 변동률」 — 셋 넘으면 짧은 이름)."""
    짧 = P._묶음이름(맥, 이)
    독 = (_N(맥).get("독자") or {}) if isinstance(_N(맥).get("독자"), dict) else {}
    if isinstance(독.get("묶음이름"), dict) and _글(독["묶음이름"].get(이)):
        return 짧
    이들 = list(dict.fromkeys(_뗀이름(맥, b) for b in 번들 or []))
    if len(이들) == 1:
        return 이들[0]
    열 = re.sub(r"\s*\([^()]*\)", "", 이).strip()
    앞들 = [x[:-len(열)].strip() for x in 이들 if 열 and x.endswith(열) and x[:-len(열)].strip()]
    if 앞들 and len(앞들) == len(이들) and len(앞들) <= 3:
        return "%s %s" % (" · ".join(앞들), 열)
    return 짧


def 시나리오서술(맥):
    """「시나리오 서술」 — 시나리오마다 이야기 → 그 이야기가 미는 칸(폭포의 큰 묶음) → 값. 불릿을 쓰지 않는다."""
    이야 = 맥.가정.get("시나리오이야기") or {}
    이름들 = ((맥.가정.get("서술") or {}).get("이름") or {})
    세 = ((맥.가정.get("서술") or {}).get("세계서술") or {})
    걸 = {}
    import 레터 as _Lm                                           # noqa: PLC0415
    묶음 = _Lm.폭포묶음(맥.가정, 맥.구)
    for 시 in ("비관", "낙관"):
        앞 = _n(맥.값("R:기준:2.DCF:68"))
        목 = []
        for k, (이, 번들) in enumerate(묶음):
            v = _n(맥.값("가:폭포:%s:%d" % (시, k)))
            if v is None or 앞 is None:
                continue
            앞k = "R:기준:2.DCF:68" if k == 0 else "가:폭포:%s:%d" % (시, k - 1)
            목.append((abs(v - 앞), 이, ["−", "가:폭포:%s:%d" % (시, k), 앞k], 번들))
            앞 = v
        걸[시] = sorted(목, key=lambda t: -t[0])
    L = []
    기 = "R:기준:2.DCF:68"
    끝 = 맥.끝예측
    괄호뜻 = False                                           # 1.1.20 — 괄호의 뜻은 한 번만
    for 시 in ("기준", "비관", "낙관"):
        나 = 맥.원고글(이름들.get(시), "서술.이름.%s" % 시) if _글(이름들.get(시)) else ""
        머 = "**%s 시나리오%s**" % (시, (" 「%s」" % 나) if 나 else "")
        한 = N.펴기(맥, (이야.get(시) or {}).get("한줄"), "시나리오이야기.%s.한줄" % 시) if (이야.get(시) or {}).get("한줄") else ""
        if not 한 and _글(세.get(시)):
            한 = N.펴기(맥, 세.get(시), "서술.세계서술.%s" % 시)
        삼 = N.시나리오3P(맥, 시)
        몸 = " ".join(x for x in ((한.rstrip(".") + ".") if 한 else "", 삼) if x).strip()
        첫 = 머 + ((" — " + 몸) if 몸 else "")
        L += [첫, ""]
        기값 = abs(_n(맥.값(기)) or 0.0)
        걸시 = [t for t in (걸.get(시) or []) if abs(_n(t[0]) or 0.0) >= 0.0005 * 기값]     # 주당가치를 거의 안 움직인 가정(「0.00달러」)은 「크게 움직인」 목록에서 뺀다
        if 시 != "기준" and 걸시:
            # 레터 v27 P6 — 괄호는 폭포 걸음(앞 묶음을 바꾼 위에서 그 묶음을 바꾼 몫 — 아래 묶음 표와 같은 값)이다. 걸음이 그 시나리오 쪽과 거꾸로면 따로 한 문장
            # 1.1.21 — 부호(「−108.69달러」) 대신 방향 낱말(「크게 낮춘 가정은 … (108.69달러)」 · 원칙 6). 가정 이름은 본편 가정 이름(구분 이름이 빠진 짧은 묶음 이름이
            #   한 구분의 가정이면 그 구분 이름까지 — `_묶음본편이름`). 괄호의 뜻은 아래 「가정 구분별 주당가치 변동」 표 주석이 말하므로 그 표가 서면 싣지 않는다
            정 = -1 if 시 == "비관" else 1
            표있음 = bool(P._폭포줄들(맥))
            뜻 = "" if (괄호뜻 or 표있음) else " 괄호 안은 앞의 가정 구분을 이 시나리오의 값으로 바꾼 상태에서 그 가정을 이 시나리오의 값으로 바꿨을 때의 주당가치 변동액입니다."
            괄호뜻 = True

            def 짓기(이름꼴):
                같, 거꾸 = [], []
                for _v, 이, 식, 번들 in 걸시[:3]:
                    값 = _n(맥.값(식[1])) - _n(맥.값(식[2]))
                    칸 = "%s(%s)" % (이름꼴(이, 번들), 맥.식(식 if 값 >= 0 else ["−", 식[2], 식[1]], "주당"))
                    (거꾸 if N.움직임(_n(맥.값(식[1])), _n(맥.값(식[2]))) == -정 else 같).append(칸)      # 걸음의 쪽(그 묶음 앞의 값 대비 · 상대 문턱)
                낸 = []
                if 같:
                    낸.append("이 시나리오에서 주당가치를 크게 %s 가정은 %s." % ("낮춘" if 정 < 0 else "높인", P.입니다(P._나열(같))))
                if 거꾸:
                    낸.append("%s 이 시나리오에서 오히려 주당가치를 %s." % (P.은(P._나열(거꾸)), "높였습니다" if 정 < 0 else "낮췄습니다"))
                return 낸
            문장 = 짓기(lambda 이, 번들: _묶음본편이름(맥, 이, 번들))
            if any(len(x) > 110 for x in 문장):                 # 본편 이름이 길어 문장이 길면(⑬ 120자) 짧은 묶음 이름으로
                문장 = 짓기(lambda 이, 번들: P._묶음이름(맥, 이))
            L += ["".join([" ".join(문장), 뜻]), ""]
        문 = []
        if 시 == "기준":
            문.append("주당가치는 %s." % P.입니다(맥.수(기, "주당")))
        else:
            k = "R:%s:2.DCF:68" % 시
            높 = (_n(맥.값(k)) or 0) >= (_n(맥.값(기)) or 0)
            문.append("주당가치는 %s이며 기준 시나리오보다 %s %s." % (맥.수(k, "주당"), 맥.식(["−", k, 기] if 높 else ["−", 기, k], "주당"), "높습니다" if 높 else "낮습니다"))
        if 맥.종가키:
            문.append("%s의 %s." % (P.종가말(맥), P.입니다(맥.식(["÷", "R:%s:2.DCF:68" % 시, 맥.종가키], "퍼0"))))
        if 시 != "기준" and 끝:                                # v27 문장(교열 275)
            문.append("최종 예측 연도의 매출은 %s(기준 시나리오 %s), 영업이익률은 %s(기준 시나리오 %s)로 추정됩니다." % (
                맥.수("R:%s:2.DCF:11:%s" % (시, 끝), "금액"), 맥.수("R:기준:2.DCF:11:%s" % 끝, "금액"),
                맥.수("R:%s:요약:마지막해영업이익률" % 시, "퍼1"), 맥.수("R:기준:요약:마지막해영업이익률", "퍼1")))
        L += [" ".join(문), ""]
    return L


def 시나리오밖줄(맥):
    """시나리오 절의 「범위 밖」 신호(1.1.3 A4) — 종가가 세 시나리오 밖이면 한 문장. 역산 절의 갭 소절(`레터갭.갭절`)이 같은 범위 밖 문장으로
    시작하는 회차는 그 문장을 되풀이하지 않고 그 자리만 부른다(1.1.19 — ADDER80 묶음 2: 같은 근거 문단이 시나리오 절 · 역산 절 두 자리에 섰다).
    범위 밖 신호는 3분 레터 · 본편 1절 결론이 이미 싣는다(게이트 갭검사 — 두 곳)."""
    import 레터갭 as _갭                                     # noqa: PLC0415
    밖 = _갭.범위밖글(맥, 어림=False)
    if not 밖:
        return []
    if 맥.절.get("역산") and _갭.갭(맥):
        return ["%s 세 시나리오 주당가치의 차이는 배수와 실측 분포로 분석했습니다(%s)." % (
            P.과(P.종가말(맥)) if 맥.종가키 else "종가와", P.곳(맥, 맥.절["역산"])), ""]      # v27 문장(교열 250 · 검토 메모 2)
    return [밖, ""]


def 시나리오절(맥, 번):
    L = 머리("시나리오", 번)
    Nn = _N(맥)
    한 = N.펴기(맥, Nn.get("한줄"), "Narrative.한줄")
    값 = N.펴기(맥, Nn.get("값으로"), "Narrative.값으로")
    if 한:
        # 1.1.20 — 「시나리오 셋은 같은 추정 구조를 쓰고, Narrative마다 바꾼 가정만 다릅니다」(서른 곳 같은 방법 설명 · 원칙 12)는 지웠다 —
        # 바꾼 가정은 바로 아래 「시나리오마다 다르게 적용한 가정」 표가 보인다
        L += ["이 레터는 %s 기준 시나리오로 삼았습니다.%s" % (P.을(한.rstrip(".")), (" " + 값) if 값 else ""), ""]
    L += 시나리오밖줄(맥)
    L += 시나리오서술(맥)
    L += 전파표(맥)                                         # 2026-10-25 R4 — 이야기가 매출 밖의 줄(원가 · 판관비 · 인건비 · CAPEX · 운전자본 · 세금)까지 어떻게 갔나
    L += 전파그림(맥)                                       # 2026-10-25 R5 — 같은 표를 기준 대비 변화율 그림으로
    몸 = P.시나리오절(맥, 번, 폭포=False)[2:]
    몸 = [x for x in 몸 if not re.match(r"^- (비관|기준|낙관) 시나리오", x)]       # 불릿 이야기는 위 서술로 옮겼다(불릿 금지)
    i전 = next((i for i, x in enumerate(몸) if x.startswith(("### 가정 묶음별 주당가치 변동", "### 가정 구분별 주당가치 변동"))), None)     # v27 — 소제목 「가정 묶음」 → 「가정 구분」(레터1부)
    if i전 is not None:                                       # 묶음 전체 표 · 보조 표는 아래 폭포절(그림 · 표 · 보조)이 싣는다
        몸 = 몸[:i전]
    L += 몸
    폭 = 출처붙여(맥, P.폭포절, 맥)
    if 폭:
        L += 폭
    L = 덧글넣기(맥, L, "시나리오", "막3")
    맥.서술("시나리오")
    return L


# ══════════════════════════════════════════════════════════════════ 14. 민감도 — 어느 변수가 어느 칸을 거쳐

_경로말 = {"매출": "매출 → 영업이익 → FCFF · Terminal Value", "비용": "영업비용 → 영업이익 → FCFF · Terminal Value",
         "재투자": "CAPEX · 순운전자본 → FCFF와 영구기간 재투자", "세금": "법인세 → NOPLAT → FCFF", "영구": "Terminal Value",
         "할인율": "현가계수 → 모든 기간의 현재가치", "주주가치": "가치 브리지"}


def 경로글(맥):
    """민감도 손잡이마다 「이 가정 → 어느 칸 → 주당가치」(같은 폭으로 움직인 값은 아래 표)."""
    글 = []
    for r in (맥.민 or {}).get("표3") or []:
        대 = ["%s" % x for x in r.get("대상") or []]
        if not 대:
            continue
        키 = "할인율" if 대[0].startswith("WACC") else N.절가정(대[0])
        길 = _경로말.get(키)
        if not 길:
            continue
        글.append("%s → %s" % (P.손잡이이름({"이름": r["이름"], "대상": r["대상"], "방식": r.get("방식")}, 맥), 길))
    if len(글) < 2:
        return []
    return (["**표. 가정별로 주당가치에 영향을 미치는 경로**", ""]      # v27 문장(교열 173 · 174) · 1.1.20 — 표 앞 예고 문장(「가정마다 … 경로가 다릅니다」)은 지웠다
            + P._표(["가정", "주당가치에 영향을 미치는 경로"], [x.split(" → ", 1) for x in 글], ["l", "l"]) + [""])


def 토네이도블록(맥):
    """모션 D 짝 그림 — 가정 하나씩 근거 범위 끝으로 옮겼을 때의 주당가치. 저자 선언 `Narrative.동인.표` [{이름, 범위, 낮음: 장부 키, 높음: 장부 키}]
    (같은 잣대 — 근거가 받치는 범위의 끝. 한쪽만 있으면 그쪽만). 줄은 주당가치가 움직인 폭이 큰 차례(그림의 차례와 같다). 선언이 없거나 키가 안
    풀리면 그림도 모션도 싣지 않는다(→ [])."""
    표 = ((맥.가정.get("Narrative") or {}).get("동인") or {}).get("표")
    기 = "R:기준:2.DCF:68"
    기값 = _n(맥.값(기))
    if 기값 is None:
        return []
    if not isinstance(표, list):                               # 2026-10-25 R3 — 선언이 없어도 지렛대 후보(같은 잣대)로 선다
        표 = 자동동인표(맥)
    항 = []
    for k, x in enumerate(표):
        if not isinstance(x, dict):
            continue
        if x.get("_자동"):
            이, 범 = x.get("이름") or "", x.get("범위") or "—"
        else:
            이 = 맥.원고글(x.get("이름"), "Narrative.동인.표[%d].이름" % k) if _글(x.get("이름")) else ""
            범 = 맥.원고글(x.get("범위"), "Narrative.동인.표[%d].범위" % k) if _글(x.get("범위")) else "—"
        쪽 = []
        for 이름 in ("낮음", "높음"):
            키 = x.get(이름)
            try:
                v = _n(맥.값(키)) if _글(키) else None
            except Exception:                                # noqa: BLE001
                v = None
            if 키 and v is None:
                맥.알림.append("Narrative.동인.표[%d].%s 의 장부 키(%s)를 못 풀었다 — 그 끝은 그림에서 뺐다" % (k, 이름, 키))
            if v is not None:
                쪽.append((v, 키))
        if not 이 or not 쪽:
            continue
        # 레터 v27 P5 — 문턱은 기준의 상대 몫(`귀속.상대문턱` — 통화 단위와 무관). 끝이 시나리오 값(「가:홀로(열):비관|낙관」)이면 값 크기가 아니라
        #   시나리오 쪽으로 붙인다(비관 → 낮은 쪽 칸 · 낙관 → 높은 쪽 칸). 비관 값이 기준보다 높거나 낙관 값이 낮으면 변화율 칸에 「(비관 값)」 · 「(낙관 값)」
        문 = N.귀속문턱()
        시쪽 = {키: m.group(1) for _v, 키 in 쪽 for m in [re.match(r"^가:홀로(?:열)?:(비관|낙관):", 키 or "")] if m}
        쪽.sort()
        낮 = [(v, 키) for v, 키 in 쪽 if N.움직임(v, 기값, 문) < 0]
        높 = [(v, 키) for v, 키 in 쪽 if N.움직임(v, 기값, 문) > 0]
        칸 = {"낮": (낮[0] + (None,)) if 낮 else None, "높": (높[-1] + (None,)) if 높 else None}
        if len(시쪽) == len(쪽):                             # 시나리오 끝 — 값 크기가 아니라 비관 · 낙관 쪽으로
            칸 = {"낮": None, "높": None}
            for v, 키 in 쪽:
                if N.움직임(v, 기값, 문) != 0:
                    칸["낮" if 시쪽[키] == "비관" else "높"] = (v, 키, 시쪽[키])
        if not 칸["낮"] and not 칸["높"]:
            continue

        def 율(t, 쪽말):
            if not t:
                return "—"
            v, 키, 시 = t
            거꾸 = (쪽말 == "낮" and v > 기값) or (쪽말 == "높" and v < 기값)
            return 맥.식(["괴리", 키, 기], "증1") + ("(%s 값)" % 시 if 거꾸 and 시 else "")
        폭 = max([v for v, _k in 쪽] + [기값]) - min([v for v, _k in 쪽] + [기값])
        항.append((폭, [이, 범, 맥.수(칸["낮"][1], "어림주당") if 칸["낮"] else "—", 맥.수(칸["높"][1], "어림주당") if 칸["높"] else "—",
                     율(칸["낮"], "낮"), 율(칸["높"], "높")]))   # v4e 리뷰 D — 변화율이 주 라벨
    if len(항) < 2:
        return []
    항.sort(key=lambda t: -t[0])
    # v4e — 모션 D 폐기(디자이너 리뷰): 「하나씩, 나머지는 고정」 은 토네이도 형식과 설명 한 문장이 이미 말한다. 정적 그림만
    L = ["<!-- 그림:토네이도 -->",
         "**그림. 가정 하나씩 근거 범위 끝으로 바꿨을 때의 주당가치(기준 시나리오에서)** — 다른 가정은 그대로 두고 가정 하나만 근거가 받치는 범위의 끝 값으로 바꿨습니다. "
         "세로선이 기준 시나리오의 주당가치이고, 주당가치가 크게 달라진 가정부터 놓았습니다.", ""]
    L += P._표(["가정", "옮긴 범위", "낮은 쪽 주당가치", "높은 쪽 주당가치", "낮은 쪽 변화율", "높은 쪽 변화율"],
              [r for _p, r in 항] + [["기준 시나리오의 주당가치", "—", 맥.수(기, "어림주당"), "—", "—", "—"]], ["l", "l", "r", "r", "r", "r"])
    L.append("")
    return L


def 자동동인표(맥):
    """지렛대 후보(근거 범위로 옮긴 가정 — 시나리오가 가른 가정은 비관 · 낙관 시나리오 값, 민감도 손잡이는 선언 범위) → 토네이도 표의 꼴
    [{이름, 범위, 낮음, 높음}] — 이름 · 범위 글은 장부를 거친 글이다(원고가 아니다 — 원고글 검수를 거치지 않게 「_글」 꼴로 둔다)."""
    d = N.지렛대(맥) or {}
    낸 = []
    for c in d.get("후보") or []:
        if c.get("잣대") == "시나리오":
            이 = N.이름묶기(맥, [N.가정말(맥, b) for b in c["번호들"] if ("%s" % b).isdigit()])
            범 = "비관 · 낙관 시나리오의 값"
        elif c.get("잣대") == "대안":                            # 1.1.7 — 할인율 대안 사양 · 영구기간 자본비용 판
            이 = N.지렛대이름(맥, c)
            범 = "할인율 절에서 비교한 세 가지 값" if c.get("대안꼴") == "영구" else "부록 B의 대안 산정 방법"     # v27 — 「대안 사양」 → 「대안 산정 방법」(레터이야기와 같은 말)
        else:
            r = (맥.민 or {}).get("표3")[c["표3"]]
            h = {"이름": r["이름"], "대상": r["대상"], "방식": r.get("방식")}
            이 = N.이름다듬기(P.손잡이이름(h, 맥))
            범 = "근거 범위 %s" % P.폭글(h, "민:표3:%d:폭" % c["표3"], 맥)
        if 이:
            낸.append({"이름": 이, "범위": 범, "낮음": c["하키"], "높음": c["상키"], "_자동": True})
    return 낸


def 민감도절(맥, 번):
    L = P.민감도절(맥, 번)
    L[0] = "## %d. %s" % (번, 제목["민감도"])
    경 = 경로글(맥)
    머 = 2 if (len(L) > 3 and N.Value드라이버문장(맥)                                          # 머리 문단(지렛대 — 2026-10-25 R3)
              and not re.sub(r"^\*\*표(?: \d+)?\. ", "", L[2]).startswith("기준 시나리오에서 가정 하나를")) else 0     # v27 — 그 자리가 표 제목(「**표. 」)이어도
    i = 2 + (2 if 머 else 0)
    토 = 출처붙여(맥, 토네이도블록, 맥)
    L = L[:i] + 토 + 경 + L[i:]                                # 지렛대 문장 → 토네이도(같은 잣대) → 경로 → 손잡이 표
    # 첫 두 변수 격자 표를 그림으로(표는 그대로 — 그림 표지와 제목만 붙인다)
    격 = []
    for i, x in enumerate(L):                                 # 2026-10-25 R5 — 정상 수준 격자가 먼저, 없으면 첫 두 변수 격자(증가율 경로 판에도 그림이 선다)
        # v27 — 격자 표 설명이 표 제목(「**표. … 함께 바꿨을 때의 주당가치**」)이거나 합쇼체 문장이어도 찾는다(평서체 옛 꼴도 그대로)
        m = re.match(r"^(?:\*\*표(?: \d+)?\. )?(.+?)\((세로|가로)\)(?:와|과) (.+?)\((가로|세로)\)(?:을|를) 함께 (?:움직인|바꿨을 때의) 주당가치(?:다\.|입니다\.|\*\*)$", x)
        if m and m.group(2) != m.group(4) and i + 2 < len(L) and L[i + 2].startswith("|"):
            세, 가 = (m.group(1), m.group(3)) if m.group(2) == "세로" else (m.group(3), m.group(1))
            격.append((0 if "정상 수준" in x else 1, i, 세.strip(), 가.strip()))
    if 격:
        _순, i, 세, 가 = min(격)
        L[i:i + 2] = 출처달기(맥, ["<!-- 그림:격자 -->", "**그림. %s %s에 따른 주당가치** — 칸의 색이 진할수록 기준에서 멉니다. 굵은 테두리가 기준 칸입니다." % (
            P.과(세), 가), ""], ["민:격자"])
    L = 덧글넣기(맥, L, "민감도")
    return L


# ══════════════════════════════════════════════════════════════════ 15. Reverse DCF

def 곡선그림(맥, b):
    """그림 「곡선」 — 주가 → 그 주가가 전제한 정상 수준(환산표와 같은 숫자)."""
    if not (b and b["풀이"] and 맥.주가 and G.셈(맥.원)):
        return []
    순 = [s for s, _x in b["구분"]]
    n = int(_n(맥.값("주:환:수")) or 0)
    줄들 = []
    for k in range(n):
        if any(_n(맥.값("주:환:백:%d:%d" % (k, s))) is None for s in 순):
            continue
        줄들.append([맥.수("주:환:가격:%d" % k, "어림주당")] + [맥.수("주:환:백:%d:%d" % (k, s), "수0") for s in 순])
    if len(줄들) < 3:
        return []
    L = ["<!-- 그림:곡선 -->", "**그림. 주가와 그 주가가 전제한 정상 수준(%s = 100)** — 가로축이 주가, 세로축이 정상 수준입니다. 가로선은 이 평가의 정상 수준입니다." % T.기간말(맥, b), ""]
    L += P._표(["주가"] + ["%s 정상 수준" % _L().구분이름(맥.구, s) for s in 순], 줄들, ["r"] * (1 + len(순)))
    L.append("")
    L += P._표(["가로선"] + [_L().구분이름(맥.구, s) for s in 순], [["이 평가의 기준"] + [T._백(맥, "S:6%d6:기준" % s, s) for s in 순]])
    L.append("")
    return L


환산머리 = "다른 날의 주가는 아래 표로"                 # 레터막.마지막종가 의 환산표 문단 머리 — 곡선 그림이 그 표를 갈음한다(v27 — 끝맺음 「읽는다 · 읽습니다」 와 무관하게 앞말로 찾는다)


def _곡선넣기(맥, 몸, b):
    """환산표(「다른 날의 주가는 아래 표로 읽는다」 문단과 표)를 곡선 그림(주가 → 그 주가가 전제한 정상 수준 · 웹 단계 슬라이더)으로 바꾼다 —
    같은 표를 두 번 싣지 않는다. 곡선이 설 수 있는데 그 문단을 못 찾으면 그대로 두고 알린다(2026-10-27 — 조용히 빠지지 않게)."""
    곡 = 출처붙여(맥, 곡선그림, 맥, b)
    i = next((k for k, x in enumerate(몸) if x.startswith(환산머리)), None)
    if 곡 and i is None:
        맥.알림.append("곡선 그림(주가와 그 주가가 전제한 정상 수준 — 웹 단계 슬라이더)을 싣지 않았다 — 「%s」 문단을 못 찾았다" % 환산머리)
    if not 곡 or i is None:
        return 몸
    j = i + 2
    while j < len(몸) and 몸[j].startswith("|"):
        j += 1
    return 몸[:i] + [몸[i].replace("아래 표로", "아래 그림으로", 1), ""] + 곡 + 몸[j + 1:]


def 역산절(맥, 번):
    L = 머리("역산", 번)
    b = T.바닥(맥)
    몸 = M.막4(맥, 4)[2:]                                     # 막 머리는 버린다(번호 4 는 머리 이름표의 자리)
    # 막4 의 끝말(다음 막으로 넘기는 말 · 절 안내)과 웹 전용 모션 자리를 뺀다 — 모션은 아래 그림에 짝으로 단다
    몸 = [x for x in 몸 if not x.startswith(("그렇다면 ", "이 가격이 성립하는 조건의 세부는")) and not x.startswith("<!-- 모션:")]
    # 「평가기준일 뒤의 정보」(날짜 하나 판 — 값에 쓰지 않은 뒤 자료)는 분석 뒤로 보낸다. 날짜 둘 판의 「재무 자료 기준일 뒤의 정보」 는 평가기준일까지
    # 알 수 있던 자료라 제자리(그림 앞)에 둔다(2026-10-26 날짜 둘 판의 차례 그대로).
    뒤i = next((i for i, x in enumerate(몸) if x.strip() == M.뒤정보머리[0]), len(몸))
    앞, 뒤 = 몸[:뒤i], 몸[뒤i:]
    # 2026-10-27 — 환산표를 곡선 그림(웹 단계 슬라이더)으로 바꾸는 일은 환산표가 어느 묶음에 있든 한다. 「평가기준일 뒤의 정보」 머리만 찾아
    # 날짜 둘 판에서 곡선 그림이 소리 없이 빠졌다(자리를 못 찾으면 알림)
    곡앞 = any(x.startswith(환산머리) for x in 앞)
    if 곡앞 and b and b["풀이"]:
        앞 = _곡선넣기(맥, 앞, b)
    L += 앞
    if b and b["풀이"]:
        import 레터모션 as _모션                            # noqa: PLC0415 — 레터모션이 레터HTML · 레터그림을 부른다(늦게 부른다)
        자 = 그림이름(출처붙여(맥, T.그림자, 맥, b))
        if 자:
            자 = _모션.표지달기(자, "C", 맥)                  # 2026-10-27 — 장면이 서야 표지를 단다(서지 않으면 알림 — 조용히 빠지지 않는다)
            L += 자
            # v4f(모션 리뷰 R3 · 상-3) — 그림 바로 아래 중립 문장 하나(결론을 시장의 생각으로 읽지 않게 — 「시장의 실제 생각은 말하지 않는다」)
            L += ["그림의 숫자는 주가마다 그 주가와 같은 주당가치가 나오는 정상 수준입니다. 어느 날의 정상 수준이 기준 시나리오와 가깝다면 두 가정이 비슷하다는 뜻이며, "
                  "기준 시나리오가 맞았다는 근거는 아닙니다.", ""]
        말 = T.가격말(맥, b)
        길 = 그림이름(출처붙여(맥, T.그림길, 맥, b, 말))
        if 길:
            길 = _모션.표지달기(길, "B", 맥)
            L += 길
        M.모션자리(맥, b)                                    # M2 · M3 장면의 장부 줄(모션 자리 표지는 위 그림에 짝으로)
    몸2 = P.역산절(맥, 번)[2:]
    역그 = 역산자그림(맥) + 역산곡선그림(맥)                     # 2026-10-25 R5 — 증가율 경로의 역산 자 · 곡선(정상 수준을 푼 판은 위 「자」 · 「곡선」)
    if 역그:
        i4 = next((k for k, x in enumerate(몸2) if x.startswith("| 가정 | 이 가격에 필요한 값 |")), None)
        if i4 is not None:
            j4 = i4
            while j4 < len(몸2) and 몸2[j4].startswith("|"):
                j4 += 1
            몸2 = 몸2[:j4] + [""] + 역그 + 몸2[j4:]
        else:
            몸2 += 역그
    L += 몸2
    L += P.역산넓힘(맥)                                      # 1.1.2 — 두 변수 동시 역산 · 보수성 점검 · 반대 논거
    if 뒤:
        if not 곡앞:
            뒤 = _곡선넣기(맥, 뒤, b)
        L += 뒤
    궤 = 출처붙여(맥, M.궤적블록, 맥)
    if 궤:
        L += T.그뒤주가(맥, 역산안=True)                    # 2026-10-31 L8 — 평가기준일 뒤 주가의 경로 문장(종전 3분 레터 종가 블록)은 역산 절 한 곳에
        L += 궤                                              # v27 문장 — 그림 앞의 안내 문장(「… 다음과 같다」)은 지웠다(그림 제목이 같은 일을 한다)
    L = 덧글넣기(맥, L, "역산", "막4")
    밖 = P._공시밖(맥, 맥.종가키)                              # 2026-10-27 — 공시 밖 사업이 메워야 할 값(발동했을 때만 · 기준 시나리오는 그대로)
    if 밖:                                                   # 저자 덧글(분석 해설) 뒤 · 「평가기준일 뒤의 정보」 앞 — 없으면 궤적 표 앞 · 그것도 없으면 끝
        분 = next((i for i, x in enumerate(L) if x.strip() == "### 평가기준일 분석"), 0)
        자리 = next((i for i, x in enumerate(L) if i > 분 and (x.strip() in M.뒤정보머리 or x.startswith(("날마다의 주가가 전제한 정상 수준은", "<!-- 그림:궤적")))), len(L))
        L = L[:자리] + 밖 + L[자리:]
    return L


# ══════════════════════════════════════════════════════════════════ 16 · 17. 모니터링 · 이해관계와 한계

def 신호절(맥, 번):
    L = 머리("신호", 번)
    고른 = T.신호고르기(맥)
    Nn = _N(맥)
    다 = N.펴기(맥, Nn.get("다음점검"), "Narrative.다음점검")
    문 = []
    if 고른:                                                 # 1.1.21 — 개수를 세는 머리 문장 대신 지표 나열 · 같은 지표(같은 가정)의 비관 · 낙관 신호는 한 번(`레터막.신호나열`)
        문 += M.신호나열(맥, 고른, 괄말="괄호는 신호가 켜질 때 주당가치가 달라지는 방향입니다.")
    if 다:
        문.append("다음 점검은 %s 뒤입니다." % 다.rstrip("."))
    if 문:
        L += [" ".join(문), ""]
    모 = [x for x in ((맥.가정.get("관측") or {}).get("모니터링") or []) if isinstance(x, dict) and _글(x.get("지표"))]
    if 모:                                                   # 모니터링 목록(관측.모니터링 · 독자층). 신호와 함께 다시 볼 지표와 경보 조건
        L += ["**표. 주기별 점검 지표와 상방 · 경보 기준**", ""]          # v27 문장(교열 221) — 표 제목으로
        L += P._표(["주기", "지표", "평가기준일 현재", "상방 신호", "경보"],
                  [[맥.원고글(x.get("주기") or "—"), 맥.원고글(x.get("지표")), N.펴기(맥, x.get("현재") or "—", "관측.모니터링.현재"),
                    N.펴기(맥, x.get("긍정") or "—", "관측.모니터링.긍정"), N.펴기(맥, x.get("경보") or "—", "관측.모니터링.경보")] for x in 모],
                  ["l", "l", "l", "l", "l"]) + [""]                     # 1.1.4(R21) — 장부 키를 편다
    L += 분포자리그림(맥, "남은")                           # 항목 절이 없는 비율 자리만(2026-10-23 W3 — 항목 절로 옮겼다)
    L += T.볼숫자(맥, 머리말=True)
    if N.신호들(맥):
        L += N.이야기점검절(맥, 번)[2:]
        L += M.도장(맥)
    L += _신호아래길(맥)
    L = 덧글넣기(맥, L, "신호", "막5", "이야기점검")
    맥.서술("Narrative.점검")
    return L


def _신호아래길(맥):
    """모니터링 절 끝의 「값이 아래로 틀릴 길」(`레터1부._아래길`). 1.1.21 — 그 앞 문장(「다른 가정을 그대로 둘 때 WACC 값이 0.50%p 높으면 …」)은 민감도 절의
    손잡이 표와 같은 값을 문장으로 되풀이한다(ADDER80 백테스트 서른 곳 · 원칙 11). 민감도 절과 그 표(표 Ⅲ)가 이 레터에 있으면 저자 글(`Narrative.틀림.아래`)만 싣는다."""
    if not (맥.절.get("민감도") and (맥.민 or {}).get("표3")):
        return P._아래길(맥)
    틀 = _N(맥).get("틀림") if isinstance(_N(맥).get("틀림"), dict) else {}
    아래 = N.펴기(맥, 틀.get("아래"), "Narrative.틀림.아래") if 틀.get("아래") else ""
    return [아래 if 아래.endswith(".") else 아래 + ".", ""] if 아래 else []


def 분포자리그림(맥, 절키=None):
    """그림 「분포자리」(2026-10-23) — 기저율 비율 자리(회전일수 · CAPEX 비율 · 상각률)가 같은 집단 분포의 어디에 서나. 재료(가정 곁 `_raw/기저율.json`)가
    없거나 자리가 서지 않으면 빈 목록. 숫자는 장부 키 「파일:기저율:비율자리:i:집단별:j:qNN」 · 「…:자리:k:값」 으로 적는다(게이트 ⑦ 이 같은 파일을 다시 읽어 맞댄다).
    절키 — 그 항목 절의 비율 자리만(W3 — 운전자본 · 재투자 절). 「남은」 이면 항목 절이 이 레터에 없는 자리만(모니터링 절). None 이면 전부."""
    기 = (맥.원.get("파일") or {}).get("기저율") or {}
    항목들 = 기.get("비율자리") or []
    줄들 = []
    for i, x in enumerate(항목들):
        if not isinstance(x, dict) or not x.get("자리") or not x.get("집단별"):
            continue
        if 절키:
            k = 항목절(맥, x.get("번호"))
            if (절키 == "남은" and k and 맥.절.get(k)) or (절키 != "남은" and k != 절키):
                continue
        꼴 = "일" if (x.get("척도") or "") == "일" else "퍼1"
        집단들 = [(j, g) for j, g in enumerate(x["집단별"]) if isinstance(g, dict) and g.get("q10") is not None and (g.get("관측수") or 0) >= 30]
        쓸 = [c for c in 집단들 if c[1].get("집단") == "전체"] + [c for c in 집단들 if c[1].get("집단") != "전체"][-1:]
        for j, g in 쓸:
            자리 = [(k, a) for k, a in enumerate(x["자리"]) if isinstance(a, dict) and a.get("집단") == g.get("집단")]
            첫 = next((k for k, a in 자리 if ("%s" % a.get("열")).startswith("첫")), None)
            끝 = next((k for k, a in 자리 if ("%s" % a.get("열")).startswith("끝")), None)
            if 첫 is None and 끝 is None:
                continue
            키 = "파일:기저율:비율자리:%d:" % i
            줄 = [x.get("이름") or (이름(맥, x["번호"]) if x.get("번호") else "—"),            # 이름이 없으면 본편 가정 이름(내부 번호는 부록 A 에만 — 2026-10-25 마무리)
                  "%s(%s곳)" % (g.get("집단"), "{:,}".format(int(g.get("관측수") or 0)))]
            줄 += [맥.수(키 + "집단별:%d:q%02d" % (j, q), 꼴) for q in (10, 25, 50, 75, 90)]
            줄.append(맥.수(키 + "자리:%d:값" % 첫, 꼴) if 첫 is not None else "—")
            줄.append(맥.수(키 + "자리:%d:값" % 끝, 꼴) if 끝 is not None else "—")
            줄들.append(줄)
    if not 줄들:
        return []
    # 1.1.2 — 절마다 같은 그림을 내면 제목이 겹친다(정합 「같은 그림 제목」) — 줄 이름을 제목에 넣는다
    대상말 = " · ".join(dict.fromkeys(x[0] for x in 줄들))
    대상말 = 대상말 if len(대상말) <= 40 else "%s 외 %d개 항목" % (줄들[0][0], len({x[0] for x in 줄들}) - 1)
    L = ["<!-- 그림:분포자리 -->",
         "**그림. %s 가정이 같은 집단의 분포에서 서는 자리** — 옅은 띠는 같은 집단 회사들의 P10~P90 구간, 진한 띠는 P25~P75(가운데 절반), 세로선은 중앙값(P50)입니다. "
         "빈 점은 이 평가 기준 시나리오의 첫 예측 열 값, 찬 점은 마지막 예측 열 값입니다. 집단 안의 위치는 판단의 재료이지 정답이 아니며, 집단 밖에 선 가정은 그 까닭을 가정 표의 근거에 적었습니다." % 대상말, ""]
    L += P._표(["항목", "집단", "P10", "P25", "P50", "P75", "P90", "기준 첫", "기준 끝"], 줄들, ["l", "l"] + ["r"] * 7)
    L.append("")
    return L


def 자리절(맥, 번):
    L = 머리("자리", 번)
    L += N.자리절(맥, 번)[2:]
    L += ["### 평가의 한계", ""]
    L += P.한계절(맥, 번)[2:]
    L = 덧글넣기(맥, L, "자리", "한계")
    return L


def 고친제목(키, f):
    def g(맥, 번):
        L = f(맥, 번)
        L[0] = "## %d. %s" % (번, 제목[키])
        return L
    return g



# ══════════════════════════════════════════════════════════════════ 근거 한 줄 — 가정 표 근거 칸 · 결론 「근거」 줄의 원천(2026-10-25 레터 재구성 R7)
# 차례: 독자근거 → 서사연결 → 그 가정의 항목 절 절글 가운데 요소 「범위」 문단이 그 가정을 부르면 그 첫 문장 → 변수 카드(같은 업종 상장사 가운데 자리 ·
# 상장사 띠 · 근거 범위). 본문 범위 문단이 있어도 표 칸이 「—」 로 비던 결함(회차 20261024 MO 6절 · 진단 3-1)을 메운다. 지어내지 않는다 — 넷 다 없으면 빈 글.
_절글키 = {"매출": ("매출", "매출.1", "매출.2", "매출.3", "매출.4", "매출.5"), "비용": ("비용", "판관"), "인건비": ("인건비", "비용"),
         "재투자": ("재투자",), "운전자본": ("운전자본",), "세금": ("세금",), "영구": ("영구",), "할인율": ("할인율",), "주주가치": ("주주가치",)}


def _첫문장(글):
    """원문(장부 자리표시가 든 글)의 첫 문장 — 「다.」 · 「다 」 끝에서 자른다(자리표시 안에서는 자르지 않는다)."""
    깊이, i = 0, 0
    while i < len(글):
        ch = 글[i]
        if ch == "{":
            깊이 += 1
        elif ch == "}":
            깊이 = max(0, 깊이 - 1)
        elif 깊이 == 0 and 글.startswith("다.", i) and (i + 2 == len(글) or 글[i + 2] in " \n"):
            return 글[:i + 2]
        i += 1
    return 글


def 범위첫문장(맥, 번):
    """그 가정의 항목 절 절글 가운데 요소 「범위」 문단이 그 가정을 부르면(자리표시 {A:번: · {S:번: 또는 가정 이름) 그 문단의 첫 문장(펴서) — 없으면 ""."""
    번 = "%s" % 번
    J = (_N(맥).get("절글") or {}) if isinstance(_N(맥).get("절글"), dict) else {}
    키 = "할인율" if 번 == "WACC" else 항목절(맥, 번)
    if not 키:
        return ""
    패 = re.compile(r"[{\s]([AS]):%s:" % re.escape(번)) if 번.isdigit() else None
    이 = "WACC" if 번 == "WACC" else 이름(맥, 번)
    짧 = 짧은이름(맥, 번) if 번.isdigit() else ""
    for k in _절글키.get(키, (키,)):
        for j, x in enumerate(J.get(k) or []):
            if not isinstance(x, dict):
                continue
            요 = x.get("요소")
            요 = [요] if isinstance(요, str) else list(요 or [])
            글 = ("%s" % (x.get("글") or "")).strip()
            if "범위" not in 요 or not 글:
                continue
            if not ((패 and 패.search(글)) or (이 and 이 in 글) or (짧 and len(짧) >= 4 and 짧 in 글)):
                continue
            g = N.펴기(맥, _첫문장(글), "Narrative.절글.%s[%d]" % (k, j))
            if g:
                return g
    return ""


def 카드근거(맥, 번):
    """변수 카드의 사실 한 줄 — 같은 업종 상장사 가운데 자리 · 상장사 띠(칸 단위) · 근거 범위(같은 잣대일 때만). 없으면 ""."""
    카 = 카드들(맥).get("%s" % 번)
    if not 카:
        return ""
    i, c = 카
    키 = "파일:변수카드:카드:%d:" % i
    자 = _집단자리(c)
    if 자:
        j, a = 자
        return "같은 업종 상장사(%s) 가운데 백분위 %s" % (맥.엔진글(키 + "같은집단자리:%d:집단" % j), 맥.식(["×", 키 + "같은집단자리:%d:백분위" % j, 100], "수0"))
    띠 = c.get("같은집단띠")
    if isinstance(띠, dict) and 띠.get("칸단위") and isinstance(띠.get("범위"), list):
        밖 = _띠같은잣대(c, 띠, _칸값들(맥, 번)) is False
        return "상장사 띠 %s ~ %s(%d년 뒤)%s" % (_칸글(맥, 번, 키 + "같은집단띠:범위:0"), _칸글(맥, 번, 키 + "같은집단띠:범위:1"), 띠.get("k") or 1,
                                          " 밖" if 밖 else " 안")
    if _범위쓰나(맥, 번, c):
        꼬리 = _범위원천(c)[0]
        return "근거 범위 %s ~ %s" % (_칸글(맥, 번, 키 + 꼬리 + ":0"), _칸글(맥, 번, 키 + 꼬리 + ":1"))
    return ""


def 근거한줄(맥, 번):
    """가정 하나의 독자용 근거 — `근거글`(독자근거 → 서사연결) → 절글 「범위」 문단의 첫 문장 → 변수 카드의 사실. 넷 다 없으면 빈 글."""
    return 근거글(맥, 번) or 범위첫문장(맥, 번) or 카드근거(맥, 번)


# ══════════════════════════════════════════════════════════════════ 변수 연결도 — 동인 그래프의 설명체인에서(2026-10-25 레터 재구성 R4)
# 가정마다 첫 엣지가 들어가는 시트로 단계를 정한다(매출 · 원가 · 세금 · 재투자 · 할인). 시나리오가 가른 가정이 먼저, 그다음 번호 차례 · 단계마다 다섯까지.
# `_raw/동인그래프.json` 이 없으면 종전의 고정 목록으로 짓고 저자에게 알린다.
_단계시트 = {"4.Sales": "매출", "5.COGS": "원가", "6.SG&A": "원가", "7.Payroll": "원가", "8.CapEx": "세금 · 재투자", "9.WC": "세금 · 재투자",
          "10.Tax": "세금 · 재투자", "2.DCF": "할인", "3.WACC": "할인"}
_연결고정 = {"매출": ("601",), "원가": ("711", "712", "714", "850", "503", "504", "510", "521"), "세금 · 재투자": ("196", "178", "182", "186", "850"),
          "할인": ("212", "219")}


def 그래프단계가정(맥):
    """`_raw/동인그래프.json` 의 설명체인 → {단계: [가정 번호 …]}(갈린 가정 먼저) 또는 None(재료 없음)."""
    G = (맥.원.get("파일") or {}).get("동인그래프")
    if not isinstance(G, dict) or not G.get("설명체인"):
        return None
    판 = {}
    for e in G.get("엣지") or []:
        판.setdefault(e.get("이름"), []).append(e)
    낸 = {}
    for ch in G.get("설명체인") or []:
        아 = "%s" % (ch.get("노드") or "")
        번 = 아[2:] if 아.startswith("A-") else ""
        if not 번.isdigit() or not ch.get("읽힘") or not ch.get("주당가치에닿나") or not 값있나(맥, 번):
            continue
        es = [e for e in 판.get(ch.get("첫엣지")) or [] if 아 in (e.get("손잡이") or [])] or 판.get(ch.get("첫엣지")) or []
        시트 = next((("%s" % x).split(":")[0] for e in es for x in e.get("하류") or [] if ":" in "%s" % x), None)
        단 = _단계시트.get(시트)
        if 단:
            낸.setdefault(단, []).append((0 if ch.get("갈림") else 1, 시트, int(번), 번))
    결 = {}
    for k, v in 낸.items():                                 # 갈린 가정이 먼저, 그다음 시트마다 하나씩 돌아가며(세금 · 재투자 칸에 CAPEX · 운전자본 · 세금이 다 서게)
        v = sorted(v)
        갈 = [b for g, _s, _n, b in v if g == 0]
        남 = {}
        for g, s, _n, b in v:
            if g:
                남.setdefault(s, []).append(b)
        차 = []
        while any(남.values()):
            for s in sorted(남, key=lambda s: list(_단계시트).index(s) if s in _단계시트 else 99):
                if 남[s]:
                    차.append(남[s].pop(0))
        결[k] = 갈 + 차
    return 결


# ══════════════════════════════════════════════════════════════════ 13-2. 이야기 전파 — 시나리오 × 줄별 변화와 「무엇이 밀었나」(2026-10-25 레터 재구성 R4)
# 시나리오 절의 표 한 장과 항목 절마다의 「이 이야기에서 이 줄은 왜 움직이나 / 왜 그대로인가」 한 문장이 같은 셈(`전파`)을 쓴다. 값은 엔진 세 시나리오의
# 최종 예측 연도 열(장부 키 R:<시>:2.DCF:<줄>:<열>), 까닭은 선언(시나리오이야기.<쪽>.driver · 딸린행 · 그대로[]) · 동인 그래프의 전파(`_raw/동인그래프.json`).
# 움직이지 않는 줄의 까닭이 비면 저자에게 알린다(원고 요건은 `레터원고` · R1 이 센다). 지어내지 않는다 — 까닭이 없으면 구조의 사실(닿지 않는다 · 닿지만 같다)만 적는다.

_전파줄 = (("매출", "매출", "2.DCF:11", "매출", "매출"), ("원가", "매출원가", "2.DCF:12", "원가", "비용"),
         ("판관", "판매비와관리비", "2.DCF:14", "판관", "비용"), ("인건비", "인건비", "7.Payroll:14", "인건비", "인건비"),
         ("영업이익", "영업이익", "2.DCF:15", None, None), ("세금", "법인세", "2.DCF:18", "세금", "세금"),
         ("감가", "감가상각비", "2.DCF:20", "CAPEX", "재투자"), ("CAPEX", "CAPEX", "2.DCF:21", "CAPEX", "재투자"),
         ("운전자본", "순운전자본 증감", "2.DCF:22", "운전자본", "운전자본"), ("미지급", "미지급 항목 증감", "2.DCF:111", "운전자본", "운전자본"),
         ("한시적", "한시적 현금흐름(세후)", "2.DCF:112", None, "세금"), ("FCFF", "FCFF", "2.DCF:23", None, None),
         ("주당", "주당가치", "2.DCF:68", None, None))
_시트머리 = {"매출": ("4.Sales:",), "원가": ("5.COGS:",), "판관": ("6.SG&A:",), "인건비": ("7.Payroll:",), "CAPEX": ("8.CapEx:",),
          "운전자본": ("9.WC:",), "세금": ("10.Tax:",)}
_시트말 = {"매출": ("매출", "매출액"), "원가": ("원가", "매출원가"), "판관": ("판관", "판관비", "판매비와관리비"), "인건비": ("인건비",),
         "CAPEX": ("CAPEX", "설비투자", "투자"), "운전자본": ("운전자본", "순운전자본"), "세금": ("세금", "법인세")}
_합말 = {"영업이익": "매출 − 매출원가 − 판매비와관리비", "FCFF": "영업이익 − 법인세 + 감가상각비 − CAPEX − 순운전자본 증감",
       "주당": "FCFF와 Terminal Value의 현재가치"}
전파쪽 = ("비관", "낙관")


움직임문턱 = 0.001          # 예측 열 어디서든 기준과 0.1% 넘게 다르면 「움직였다」(시나리오전파.py · 자체검사 ㊻ 과 같은 문턱)


def _줄값들(맥, 시, 줄):
    """시나리오 시 의 그 줄(시트:줄) 예측 열 값들(한 값 줄 — 주당가치 — 은 [값]) — 없으면 None."""
    시트, _, 번 = 줄.partition(":")
    v = ((맥.R.get(시) or {}).get(시트) or {}).get(번)
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return [_n(v)]
    if not isinstance(v, dict):
        return None
    return [_n(v.get(c)) for c in 맥.예측열]


def _움직였나(맥, 시, 줄):
    """예측 열 어디서든 기준과 0.1% 넘게 다른가(척도는 그 줄의 가장 큰 값의 1% 아래로 내리지 않는다 — 0 근처 줄이 작은 차로 「움직였다」 가 되지 않게)."""
    b, x = _줄값들(맥, "기준", 줄), _줄값들(맥, 시, 줄)
    if b is None or x is None:
        return None
    b = [v or 0.0 for v in b]
    x = [v or 0.0 for v in x]
    척 = max([abs(v) for v in b + x] + [0.0])
    if 척 < 1e-12:
        return False
    return max(abs(p - q) / max(abs(q), 0.01 * 척, 1e-12) for p, q in zip(x, b)) > 움직임문턱


def _그래프(맥):
    return (getattr(맥, "원", None) or {}).get("파일", {}).get("동인그래프") if isinstance((getattr(맥, "원", None) or {}).get("파일"), dict) else None


def _간엣지(G, 근원, 시, 시트):
    """동인 그래프의 전파(시나리오:근원) 가운데 그 시트로 들어가는 엣지 이름(가정 칸이 붙은 엣지가 먼저) — 없으면 None."""
    e = ((G or {}).get("전파") or {}).get("%s:A-%s" % (시, 근원)) or {}
    if not any(n.startswith(_시트머리[시트]) for n in e.get("닿는노드") or []):
        return None
    지난 = [x.get("이름") for x in e.get("지난엣지") or [] if x.get("이름")]
    판 = {}
    for g in (G or {}).get("엣지") or []:
        판.setdefault(g.get("이름"), []).append(g)
    후 = [(0 if any(g.get("손잡이") for g in 판.get(n) or []) else 1, k, n) for k, n in enumerate(지난)
         if any(any(h.startswith(_시트머리[시트]) for h in g.get("하류") or []) for g in 판.get(n) or [])]
    if not 후:
        return ""
    n = sorted(후)[0][2]
    return re.sub(r"\s+", " ", re.sub(r"\([^()]*\)", "", n)).replace("원가 줄", "원가").strip()


def _그대로까닭(맥, 시, 시트, 번들):
    """시나리오이야기.<시>.그대로[] 가운데 그 시트(이름 · 「시트:줄」) 또는 그 절의 가정 번호를 덮는 칸의 까닭(10자 이상 · 펴서) — 없으면 ""."""
    for i, x in enumerate(((맥.가정.get("시나리오이야기") or {}).get(시) or {}).get("그대로") or []):
        if not isinstance(x, dict):
            continue
        줄 = ("%s" % (x.get("줄") or "")).replace("A-", "").strip()
        덮 = (줄 in 번들) or (줄 in _시트말.get(시트, ())) or any(줄.startswith(m) for m in _시트머리.get(시트, ()))
        까 = ("%s" % (x.get("까닭") or "")).strip()
        if 덮 and len(까) >= 10:
            g = N.펴기(맥, 까, "시나리오이야기.%s.그대로[%d].까닭" % (시, i))
            if g:
                return g.rstrip(".")
    return ""


def _이름들(맥, 번들, n=3):
    번들 = [b for b in 번들 if ("%s" % b).isdigit()]
    if not 번들:
        return ""
    이 = N.이름묶기(맥, list(dict.fromkeys(N.가정말(맥, b) for b in 번들[:n])))
    return 이 + (" 외 %d개" % (len(번들) - n) if len(번들) > n else "")


_M1시트 = ("매출", "원가", "판관", "인건비", "CAPEX", "운전자본", "세금")      # 시나리오전파(M1)가 판정하는 시트 — 감가상각비 · 미지급 · 한시적 줄은 레터가 판정한다


def 전파산출(맥):
    """시나리오전파 산출(형식 「시나리오전파/1」 — M1) → {(쪽, 시트): 표 줄}. 가정 곁 `_raw/시나리오전파.json`(장부 재료)이 먼저, 없으면
    `시나리오전파.짓기(가정, 결과들 = 레터의 세 시나리오 결과)`(같은 셈 · 엔진을 다시 돌리지 않는다). 못 지으면 빈 dict(레터가 스스로 판정한다)."""
    if hasattr(맥, "_전파산출"):
        return 맥._전파산출
    낸 = (getattr(맥, "원", None) or {}).get("파일", {}).get("시나리오전파") if isinstance((getattr(맥, "원", None) or {}).get("파일"), dict) else None
    if not isinstance(낸, dict):
        try:
            import importlib                                  # noqa: PLC0415
            낸, _까 = importlib.import_module("시나리오전파").짓기(맥.가정, getattr(맥, "경로", None), 결과들=dict(맥.R))
        except Exception:                                    # noqa: BLE001
            낸 = None
    표 = {}
    for 쪽, v in ((낸 or {}).get("쪽") or {}).items():
        for r in (v or {}).get("표") or []:
            if isinstance(r, dict) and r.get("시트"):
                표[(쪽, r["시트"])] = r
    맥._전파산출 = 표
    return 표


def _번이름(맥, 글들, 머리):
    """시나리오전파 「밀었나」(「driver A-30」 · 「딸린행 A-711」 · 「구조 연동(A-30)」) 가운데 그 머리의 번호 → 본편 이름들."""
    번 = []
    for g in 글들 or []:
        m = re.match(r"^%s\s*\(?A-(\d+)\)?" % re.escape(머리), "%s" % g)
        if m and m.group(1) not in 번:
            번.append(m.group(1))
    return _이름들(맥, 번, 3) if 번 else ""


def _밀었나(맥, 행, 시, 갈린):
    """(상태, 글, 문장) — 상태: 합 · driver · 딸린행 · 다른가정 · 구조 · 그대로 · 그대로(까닭 없음) · 해당없음. 글은 표 칸(독자용 · 내부 번호 없음),
    문장은 항목 절 머리 문장의 「… 을 따라」 조각(움직인 줄) 또는 까닭(그대로인 줄). 이름을 괄호에 넣지 않는다(이름의 괄호와 겹친다)."""
    키, _이름, 줄, 시트, 절 = 행
    if 키 in _합말:
        return "합", _합말[키], ""
    움 = _움직였나(맥, 시, 줄)
    m1 = 전파산출(맥).get((시, 시트)) if (시트 in _M1시트 and 키 not in ("감가", "미지급")) else None
    if m1 and m1.get("움직임") is not None and bool(m1.get("움직임")) == bool(움):     # M1 의 판정이 레터의 판정과 같으면 그 상태 · 까닭을 쓴다(같은 문턱)
        상 = m1.get("상태") or ""
        if 상 == "driver" or 상 == "딸린행":
            말 = "시나리오 가정" if 상 == "driver" else "연동 변경 항목"
            이 = _번이름(맥, m1.get("밀었나"), "driver" if 상 == "driver" else "딸린행")
            if 이:
                return 상, "%s: %s" % (말, 이), "%s 따라. 그 가정은 %s" % (P.을(말), P.입니다(이))
        elif 상 == "구조 연동":
            e = next((g.get("엣지") for g in m1.get("닿은길") or [] if g.get("엣지")), "")
            e = re.sub(r"\s+", " ", re.sub(r"\([^()]*\)", "", e or "")).replace("원가 줄", "원가").strip()
            return "구조", ("산식 연동: %s" % e) if e else "산식 연동", ("산식 「%s」로 시나리오 가정을 따라" % e) if e else "산식으로 시나리오 가정을 따라"
        elif 상 in ("닿음 · 안 움직임", "따라가야 · 안 닿음", "그대로(규칙 밖)"):
            작 = any(abs((_n(v) or 0.0) - (_n(w) or 0.0)) > 1e-12 for v, w in zip(_줄값들(맥, 시, 줄) or [], _줄값들(맥, "기준", 줄) or []))
            머 = "기준과 0.1% 안" if 작 else "같음"
            까 = N.펴기(맥, m1.get("까닭"), m1.get("까닭출처") or "시나리오이야기.%s.그대로" % 시) if m1.get("까닭") else ""
            if 까:
                return "그대로", "%s — %s" % (머, 까.rstrip(".")), 까.rstrip(".")
            말 = ("시나리오 가정이 산식으로 이어지지만 값은 기준과 같습니다" if 상 == "닿음 · 안 움직임"
                 else "시나리오 가정이 %s의 산식에 들어가지 않습니다" % _이름)
            return "그대로(까닭 없음)" if 상 != "그대로(규칙 밖)" else "그대로", "%s — %s" % (머, 말), 말
    이야 = (맥.가정.get("시나리오이야기") or {}).get(시) or {}
    drv = ["%s" % d for d in 이야.get("driver") or []]
    딸 = ["%s" % d for d in 이야.get("딸린행") or []]
    내 = [b for b in 갈린 if 항목절(맥, b) == 절]
    if 움:
        조각 = []
        a = [b for b in 내 if b in drv]
        f = [b for b in 내 if b in 딸 and b not in drv]
        o = [b for b in 내 if b not in drv and b not in 딸]
        for 번, 말 in ((a, "시나리오 가정"), (f, "연동 변경 항목"), (o, "시나리오마다 다르게 둔 가정")):
            if 번:
                조각.append("%s: %s" % (말, _이름들(맥, 번)))
        if 조각:
            주 = "시나리오 가정" if a else "연동 변경 항목" if f else "시나리오마다 다르게 둔 가정"
            모 = a + f + o
            문 = "%s 따라. 그 가정은 %s" % (P.을(주), P.입니다(_이름들(맥, 모, 3)))     # 두 문장 — 이름이 길면 한 문장이 130자를 넘는다
            return ("driver" if a else "딸린행" if f else "다른가정"), " · ".join(조각), 문
        G = _그래프(맥)
        for d in drv + 딸:
            e = _간엣지(G, d, 시, 시트) if 시트 else None
            if e is not None:
                return "구조", ("산식 연동: %s" % e) if e else "산식 연동", ("산식 「%s」로 시나리오 가정을 따라" % e) if e else "산식으로 시나리오 가정을 따라"
        return "구조", "산식 연동", "산식으로 앞 항목을 따라"
    if 움 is None:
        return "해당없음", "—", ""
    까 = _그대로까닭(맥, 시, 시트, set(내))
    작 = any(abs((_n(v) or 0.0) - (_n(w) or 0.0)) > 1e-12 for v, w in zip(_줄값들(맥, 시, 줄) or [], _줄값들(맥, "기준", 줄) or []))
    머 = "기준과 0.1% 안" if 작 else "같음"
    if 까:
        return "그대로", "%s — %s" % (머, 까), 까
    G = _그래프(맥)
    닿 = G and any((((G.get("전파") or {}).get("%s:A-%s" % (시, d)) or {}).get("닿는노드") or []) and
                  any(n.startswith(_시트머리.get(시트, ("~",))) for n in ((G.get("전파") or {}).get("%s:A-%s" % (시, d)) or {}).get("닿는노드") or [])
                  for d in drv + 딸)
    말 = "시나리오 가정이 산식으로 이어지지만 값은 기준과 같습니다" if 닿 else "시나리오 가정이 %s의 산식에 들어가지 않습니다" % _이름
    return "그대로(까닭 없음)", "%s — %s" % (머, 말), 말


def 전파(맥):
    """→ {"열", "줄": [{키, 이름, 시트, 절, 기준키, 쪽: {시: {키, 움직임, 상태, 글}}}]} — 비관 · 낙관이 기준과 같은 판이면 None. 한 번 셈해 맥에 둔다."""
    if hasattr(맥, "_전파"):
        return 맥._전파
    끝 = 맥.끝예측
    import 레터 as _Lm                                      # noqa: PLC0415
    if not 끝 or not any(abs((_n(맥.값("R:%s:2.DCF:68" % s)) or 0) - (_n(맥.값("R:기준:2.DCF:68")) or 0)) > 1e-12 for s in 전파쪽):
        맥._전파 = None
        return None
    import importlib                                          # noqa: PLC0415
    _M = importlib.import_module("엔진.민감도")
    갈린 = {시: sorted({"%s" % b for v in _M.시나리오갈림(맥.가정, 쪽들=(시,)).values() for b in v}) for 시 in 전파쪽}    # 그 쪽에서 기준과 다른 번호
    줄들 = []
    for 행 in _전파줄:
        키, 이름, 줄, 시트, 절 = 행
        값 = _줄값들(맥, "기준", 줄)
        if 값 is None or (키 in ("미지급", "한시적") and all(v is None for s in ("비관", "기준", "낙관") for v in (_줄값들(맥, s, 줄) or [None]))):
            continue                                         # 미지급 항목 · 한시적 현금흐름은 선언한 판에만 선다(엔진 FCFF 식과 같다)
        if 키 == "인건비" and not 맥.절.get("인건비"):            # 인건비를 따로 세우지 않은 구조 — 원가 · 판관 줄 안에 있다
            continue
        한 = {"키": 키, "이름": 이름, "시트": 시트, "절": 절, "줄": 줄,
             "기준키": ("R:기준:%s" % 줄) + ("" if 키 == "주당" else ":%s" % 끝), "쪽": {}}
        for 시 in 전파쪽:
            상, 글, 문 = _밀었나(맥, 행, 시, 갈린[시])
            한["쪽"][시] = {"키": ("R:%s:%s" % (시, 줄)) + ("" if 키 == "주당" else ":%s" % 끝), "움직임": bool(_움직였나(맥, 시, 줄)), "상태": 상, "글": 글,
                          "문장": 문}
        줄들.append(한)
    덤 = [r["이름"] for r in 줄들 if r["키"] in ("미지급", "한시적")]        # 선언한 판의 FCFF 덤 줄만 식에 적는다(선언하지 않은 갈래의 낱말을 쓰지 않는다 — 게이트 ⑧)
    for r in 줄들:
        if r["키"] == "FCFF" and 덤:
            for 시 in 전파쪽:
                r["쪽"][시]["글"] = _합말["FCFF"] + "".join(" + %s" % x for x in 덤)
    맥._전파 = {"열": 끝, "줄": 줄들}
    return 맥._전파


def 전파표(맥):
    """시나리오 절의 표 — 줄 · 기준 · 비관 − 기준 · 낙관 − 기준 · 무엇이 밀었나(최종 예측 연도). 장부에 그 셈의 키를 남긴다(게이트 ⑰ 이 합을 다시 셈한다)."""
    d = 전파(맥)
    if not d:
        return []
    표 = []
    for r in d["줄"]:
        꼴 = "주당" if r["키"] == "주당" else "금액"
        칸 = [r["이름"], 맥.수(r["기준키"], 꼴)]
        for 시 in 전파쪽:
            s = r["쪽"][시]
            차 = (_n(맥.값(s["키"])) or 0.0) - (_n(맥.값(r["기준키"])) or 0.0)
            칸.append(맥.식(["−", s["키"], r["기준키"]], "부호주당" if 꼴 == "주당" else "부호금액") if abs(차) > 1e-12 else "같음")
        글들 = [r["쪽"][시]["글"] for 시 in 전파쪽]
        칸.append(글들[0] if 글들[0] == 글들[1] else " · ".join("%s: %s" % (시, g) for 시, g in zip(전파쪽, 글들)))
        표.append(칸)
    if len(표) < 3:
        return []
    맥._전파표 = {"열": d["열"], "줄": [{"키": r["키"], "기준키": r["기준키"], **{시: r["쪽"][시]["키"] for 시 in 전파쪽},
                                    "움직임": {시: r["쪽"][시]["움직임"] for 시 in 전파쪽}, "상태": {시: r["쪽"][시]["상태"] for 시 in 전파쪽}} for r in d["줄"]]}
    for r in d["줄"]:
        for 시 in 전파쪽:
            if r["쪽"][시]["상태"] == "그대로(까닭 없음)":
                말 = "시나리오 전파 — %s 시나리오에서 %s 줄이 기준과 같은데 까닭(시나리오이야기.%s.그대로[] — {\"줄\", \"까닭\"})이 없다" % (시, r["이름"], 시)
                if 말 not in 맥.알림:
                    맥.알림.append(말)
    # v27 문장(교열 162 · 163 · 164 · 검토 메모 6) — 표 제목 · 표 주석으로. 표 머리 「무엇이 밀었나」 → 「변동 원인」 · 소제목 「줄 변화와 그 까닭」 → 「항목 변동」
    #   (게이트 ⑰ · 레터인터랙티브 의 전파 표 찾기가 표 머리를 본다 — 조정 갈래에 알림)
    L = ["### 시나리오별 항목 변동", "", "**표. 시나리오별 항목 변동과 그 원인**", ""]
    L += P._표(["항목", "기준", "비관 − 기준", "낙관 − 기준", "변동 원인"], 표, ["l", "r", "r", "r", "l"])
    L += ["", "금액은 최종 예측 연도(%s) 기준이고, 비관 · 낙관 시나리오는 기준 시나리오와의 차이입니다. "
          "「변동 원인」에는 항목이 달라진 원인(시나리오 가정 · 연동 변경 항목 · 산식 연동)을 적었고, 달라지지 않은 항목에는 그 이유를 적었습니다." % 맥.열말(d["열"]), ""]
    return L


_절줄 = {"매출": ("매출",), "비용": ("원가", "판관"), "인건비": ("인건비",), "재투자": ("CAPEX", "감가"), "운전자본": ("운전자본", "미지급"),
        "세금": ("세금", "한시적")}


def 이야기문장(맥, 절키):
    """항목 절 머리의 시나리오 문단(R4 · 계약 0절 4). 시나리오가 갈리지 않는 판 · 줄이 없는 절은 빈 목록.
    레터 v27 문장(교열 58 · 94 · 95 · 103 · 113 · 120 · 121 · 140 · 141 · 272) — 줄마다 「시나리오가 바뀌면 X는 산식 「…」로 시나리오 가정을 따라
    움직인다 · 최종 예측 연도에서 기준 대비 …」 를 되풀이하던 문장은 지웠다(시나리오 절의 시나리오별 항목 변동 표가 항목별 차이 · 산식 · 까닭을 싣는다 —
    원칙 11). 매출 절만 매출 한 줄을 남기고(방향은 부호가 아니라 낱말로 — 원칙 6), 할인율 · Terminal Value 절은 그 절의 값(WACC · 영구기간
    영업이익률)이 시나리오마다 같은지 · 얼마인지를 쓴다. 게이트 ⑰ 의 「시나리오가 바뀌」 검사는 이 문장 꼴을 따라 고쳐야 한다(조정 갈래)."""
    import 레터 as _Lm                                      # noqa: PLC0415
    d = 전파(맥)
    if not d:
        return []
    if 절키 == "매출":
        r = next((r for r in d["줄"] if r["키"] == "매출"), None)
        if not r:
            return []
        움 = [시 for 시 in 전파쪽 if r["쪽"][시]["움직임"]]
        if not 움:
            까 = r["쪽"]["비관"]["문장"].rstrip(".")
            return ["매출은 세 시나리오에서 같습니다.%s" % ((" %s." % 까) if 까 else ""), ""]
        문 = ["시나리오 가정을 바꾸면 매출이 달라집니다."]
        조 = r["쪽"][움[0]]["문장"]
        if ". 그 가정은 " in 조:
            문.append("그 가정은 %s." % 조.split(". 그 가정은 ", 1)[1].rstrip("."))
        조각 = []
        for 시 in 움:
            차 = (_n(맥.값(r["쪽"][시]["키"])) or 0.0) - (_n(맥.값(r["기준키"])) or 0.0)
            말 = 어투.방향(차, "많", "적")
            if 말:
                조각.append((시, 맥.식(["−", r["쪽"][시]["키"], r["기준키"]] if 차 > 0 else ["−", r["기준키"], r["쪽"][시]["키"]], "금액"), 말))
        if 조각:
            앞 = "".join("%s 시나리오에서 %s %s고, " % t for t in 조각[:-1])
            문.append("최종 예측 연도의 매출은 기준 시나리오보다 %s%s 시나리오에서 %s %s습니다." % ((앞,) + 조각[-1]))
        return [" ".join(문), ""]
    if 절키 in _절줄:
        return []
    if 절키 == "할인율":
        갈 = any(abs((_n(맥.값("R:%s:WACC:예측기간:WACC" % s)) or 0) - (_n(맥.값("R:기준:WACC:예측기간:WACC")) or 0)) > 1e-12 for s in 전파쪽)
        if 갈:
            return ["WACC 값은 시나리오마다 다르게 산정했습니다. 비관 시나리오 %s, 기준 시나리오 %s, 낙관 시나리오 %s." % (
                tuple(맥.수("R:%s:WACC:예측기간:WACC" % s, "퍼2") for s in ("비관", "기준")) + (P.입니다(맥.수("R:낙관:WACC:예측기간:WACC", "퍼2")),)), ""]
        까 = _그대로까닭(맥, "비관", "할인율", {"WACC"}) or ""
        return ["세 시나리오에 같은 WACC 값을 적용했습니다. %s." % (까 or "시나리오마다 다르게 둔 가정 가운데 할인율 산정에 쓰이는 항목은 없습니다"), ""]
    if 절키 == "영구":
        키 = "R:%s:2.DCF:42"
        if _n(맥.값(키 % "기준")) is None:
            return []
        움 = [s for s in 전파쪽 if abs((_n(맥.값(키 % s)) or 0) - (_n(맥.값(키 % "기준")) or 0)) > 1e-12]
        입력 = (맥.구.get("영구가치") or {}).get("영구이익기준") == "입력"
        갈213 = "213" in [b for _이, 번들 in _Lm.폭포묶음(맥.가정, 맥.구) for b in 번들]
        if 움:
            까 = (" Normalization 영업이익률은 시나리오마다 다르게 가정했습니다." if 갈213 else
                  "" if 입력 else " 영구기간 손익은 최종 예측 연도의 매출과 원가를 기준으로 계산했습니다.")
            값들 = ["기준 시나리오 %s" % 맥.수(키 % "기준", "퍼1")] + ["%s 시나리오 %s" % (s, 맥.수(키 % s, "퍼1")) for s in 움]
            return ["영구기간 영업이익률은 %s.%s" % (P.입니다(", ".join(값들)), 까), ""]
        까 = _그대로까닭(맥, "비관", "영구", {"212", "213", "219"})
        return ["영구기간 영업이익률은 세 시나리오에서 같습니다(%s).%s" % (맥.수(키 % "기준", "퍼1"), (" %s." % 까) if 까 else ""), ""]
    return []


# ══════════════════════════════════════════════════════════════════ 2026-10-25 R5 — 변수 절 그림 · 그림마다 출처 줄(연구/레터재구성_20261025/조문_그림.md)
# 그림은 표지 줄 + 굵은 제목(단위 · 시나리오를 괄호에) + 설명 + 「출처: …」 + 표다. 그림의 숫자는 모두 장부 키(`맥.수` · `맥.식`)이고, 출처 줄은 그 그림이 찍은
# 장부 키에서 짓는다(`_키기록` → `출처글` — 엔진 결과는 「평가 모델의 ○○ 계산」, 실적 열은 「회사 공시 실적」, 재료 파일은 그 재료의 말). 내부 이름(키 · 파일 이름)은
# 독자 글에 쓰지 않는다 — 키와 재료 파일 해시는 장부가 갖고 게이트 ⑦ 이 같은 키로 다시 셈한다. 그림이 서야 할 절 · 출처 줄 · 단위는 `레터그림검사.절검사`
# (편집 등급)가 센다. 회사 · 업종 이름 없음 — 그림은 구조 · 재료가 있는 판에만 선다.

@contextlib.contextmanager
def _키기록(맥):
    """그 사이에 `맥.수` · `맥.식` 이 찍은 장부 키(식 안의 키까지)를 모은다 — 그림의 출처 줄을 그림 숫자의 키에서 짓는다. 맥의 메서드를 잠깐 덮고 되돌린다."""
    모 = []
    있던 = {k: 맥.__dict__[k] for k in ("수", "식") if k in getattr(맥, "__dict__", {})}
    원수, 원식 = 맥.수, 맥.식

    def 수(키, 꼴, 값=None):
        모.append(키)
        return 원수(키, 꼴) if 값 is None else 원수(키, 꼴, 값)

    def 식(식_, 꼴):
        모.extend(_식키(식_))
        return 원식(식_, 꼴)
    맥.수, 맥.식 = 수, 식
    try:
        yield 모
    finally:
        for k in ("수", "식"):
            if k in 있던:
                setattr(맥, k, 있던[k])
            else:
                try:
                    delattr(맥, k)
                except AttributeError:
                    pass


def _식키(식):
    """식 [연산, 피연산자…] 안의 장부 키(글)."""
    if isinstance(식, str):
        return [식]
    if not isinstance(식, list):
        return []
    낸 = []
    for x in 식[1:]:
        낸 += _식키(x)
    return 낸


_출처시트말 = {"4.Sales": "매출", "5.COGS": "원가", "6.SG&A": "원가", "7.Payroll": "인건비", "8.CapEx": "설비투자", "9.WC": "운전자본",
           "10.Tax": "법인세", "2.DCF": "손익 · FCFF", "3.WACC": "자본비용", "WACC": "자본비용", "요약": "가치", "11.NOA": "가치 브리지"}
_출처재료말 = {"변수카드": "같은 업종 상장사 재무제표에서 잰 범위", "기저율": "상장사 재무제표에서 잰 같은 집단 분포",
           "결합민감도": "가정을 함께 움직여 본 계산", "계수사전": "업종 값과 회사 자료", "시나리오전파": "평가 모델의 시나리오 계산"}


def 출처글(맥, 키들):
    """그림 숫자의 장부 키 → 출처 한 문장(「출처: 평가 모델의 매출 계산(시나리오 셋) · 회사 공시 실적.」). 키가 없으면 빈 글. 숫자를 쓰지 않는다."""
    계산, 시들, 실적, 덧 = [], set(), False, []
    실열 = set(getattr(맥, "실적열", []) or [])

    def 더(말):
        if 말 and 말 not in 덧:
            덧.append(말)
    for k in 키들 or []:
        if not isinstance(k, str):
            continue
        부 = k.split(":")
        머 = 부[0]
        if 머 == "R" and len(부) >= 3:
            시들.add(부[1])
            말 = _출처시트말.get(부[2])
            if 부[-1] in 실열:
                실적 = True
            elif 말 and 말 not in 계산:
                계산.append(말)
        elif 머 in ("A", "S", "T", "G", "N"):
            더("이 평가의 가정")
        elif 머 == "H":
            실적 = True
        elif 머 == "파일" and len(부) > 1:
            더(_출처재료말.get(부[1], "이 평가의 재료"))
        elif 머 == "민":
            더("평가 모델의 Reverse DCF 계산" if len(부) > 1 and 부[1] == "표4" else "평가 모델의 민감도 계산")
        elif 머 == "가":
            더("가정을 바꿔 다시 셈한 평가 모델")
        elif 머 == "W":
            더("자본비용 입력")
        elif 머 == "주":
            더("일별 주가")                                    # 「종가」 는 날짜와 함께만 쓴다(게이트 ⑫) — 출처 줄은 「주가」
    시말 = "시나리오 셋" if ({"비관", "낙관"} & 시들) else "기준 시나리오"
    부분 = (["평가 모델의 %s 계산(%s)" % (" · ".join(계산[:3]), 시말)] if 계산 else []) + (["회사 공시 실적"] if 실적 else []) + 덧
    return ("출처: %s." % " · ".join(부분)) if 부분 else ""


def 출처달기(맥, L, 키들):
    """그림 줄들(L) 가운데 표지 바로 아래 굵은 제목 줄마다 출처 문장을 덧붙인다(이미 있으면 두지 않는다). 키가 없으면 그대로."""
    글 = 출처글(맥, 키들)
    if not 글:
        return L
    L = list(L)
    for i in range(len(L) - 1):
        if ("%s" % L[i]).startswith("<!-- 그림:") and ("%s" % L[i + 1]).startswith("**그림") and "출처:" not in L[i + 1]:
            t = L[i + 1].rstrip()
            L[i + 1] = t + ("" if t.endswith((".", "**")) else ".") + " " + 글
    return L


def 출처붙여(맥, f, *a, **k):
    """그림을 짓는 함수 f 를 돌리며 장부 키를 모아 그 그림들에 출처 줄을 단다."""
    with _키기록(맥) as 키들:
        L = f(*a, **k)
    return 출처달기(맥, L or [], 키들)


def _그림블록(맥, 종, 제목, 설명, 머, 줄들, 정렬=None, 덧표=(), 키들=()):
    """그림 블록 — 표지 · 굵은 제목(단위는 괄호에) · 설명 · 출처 · 표(덧표는 둘째 · 셋째 표)."""
    줄들 = [r for r in 줄들 if any(("%s" % c).strip() not in ("—", "-", "") for c in r[1:])]     # 「—」 만 있는 줄은 빈 칸이다(구조검수 「빈슬롯」)
    if not 줄들:
        return []
    L = ["<!-- 그림:%s -->" % 종, "**그림. %s** — %s" % (제목, 설명), ""]
    L += P._표(머, 줄들, 정렬)
    L.append("")
    for m2, r2 in 덧표:
        L += P._표(m2, r2)
        L.append("")
    return 출처달기(맥, L, 키들)


_연간줄 = {1: "12", 2: "20", 3: "26", 4: "32", 5: "38"}                 # 엔진/매출 — 구분 s 의 연간 기준 매출(수준 경로 = 연환산)
_증가율줄 = {1: ("10", "11"), 2: ("18", "19"), 3: ("24", "25"), 4: ("30", "31"), 5: ("36", "37")}    # 판매량 증가율 · 판매단가 변동률(수준 경로 = 지수의 전 열 대비)


def 동인그림(맥, x):
    """① 매출 증가율의 동인 분해(그림 「동인」 — 쌓기) — 매출 구분 하나의 열마다 판매량 증가 몫 · 판매단가 변동 몫 · 겹친 몫(수준 경로는 환율 · 조정 계수
    포함)을 쌓고 매출 증가율을 선으로. 실적 열(연간)은 매출 증가율만. 매출 명칭만 있는 구분(증가율 하나)은 나눌 것이 없어 서지 않는다."""
    s = x.get("번호")
    if not isinstance(s, int) or s not in _증가율줄 or x.get("경로") not in ("증가율", "수준") or not 가격나뉨(맥, x):
        return []                                             # 1.1.19 — 판매단가 변동률이 없거나 모두 0 인 구분도 나눌 것이 없다(`가격나뉨`)
    S = 맥.기.get("4.Sales") or {}
    q행, p행 = _증가율줄[s]
    a행 = _연간줄[s]
    A, Q, Pr = S.get(a행) or {}, S.get(q행) or {}, S.get(p행) or {}
    순 = [c for c in 맥.열 if _n(A.get(c)) is not None and (c not in 맥.실적열 or c in 맥.FY실적)]
    if len(순) < 3:
        return []
    수준 = x.get("경로") == "수준"
    머, 줄q, 줄p, 줄x, 줄g, 겹 = [], [], [], [], [], []
    R = "R:기준:4.Sales:%s:%s"
    with _키기록(맥) as 키들:
        for 앞, c in zip(순, 순[1:]):
            실 = c in 맥.실적열
            q, p = _n(Q.get(c)), _n(Pr.get(c))
            if not 실 and (q is None or p is None):
                continue
            if _n(A.get(앞)) in (None, 0.0):
                continue
            g식 = ["괴리", R % (a행, c), R % (a행, 앞)]
            머.append(맥.표기(c))
            if 실:
                줄q.append("—")
                줄p.append("—")
                줄x.append("—")
            else:
                줄q.append(맥.수(R % (q행, c), "증1"))
                줄p.append(맥.수(R % (p행, c), "증1"))
                x식 = ["−", ["−", g식, R % (q행, c)], R % (p행, c)]
                겹.append(abs(_n(맥.식값(x식)) or 0.0))
                줄x.append(맥.식(x식, "증1"))
            줄g.append(맥.식(g식, "증1"))
        if sum(1 for 칸 in 줄q if 칸 != "—") < 2:
            return []
        량, 가 = _물량말(x), _가격말(x).replace(" 지수", "")
        줄들 = [["%s 증가 몫" % 량] + 줄q, ["%s 변동 몫" % 가] + 줄p]
        if max(겹 + [0.0]) >= 0.0005:
            줄들.append([("겹친 몫 · 환율 · 조정 계수" if 수준 else "두 변동이 겹친 몫")] + 줄x)
        줄들.append(["매출 증가율 (선)"] + 줄g)
    실있음 = any(c in 맥.실적열 for c in 순[1:])
    구이 = _L().구분이름(맥.구, s)
    긴 = len(구이) > 16                                       # 긴 구분 이름은 제목 밖 첫 문장으로(제목 + 첫 문장이 한 문장으로 세어진다 — ⑬ 131자)
    제목 = ("%s… 매출 증가율의 분해(기준 시나리오, 전 열 대비 %%)" % 구이[:12].rstrip()) if 긴 else "%s 매출 증가율의 분해(기준 시나리오, 전 열 대비 %%)" % 구이     # 1.1.2 — 같은 그림 제목 금지(긴 이름 구분이 여럿이면 번호로 가른다)
    앞 = ("%s 매출입니다. " % 구이) if 긴 else ""
    if getattr(맥, "_동인범례", False):                       # 둘째 그림부터 — 읽는 법은 앞 그림과 같다 · 구분 이름이 든 문장으로 문형이 갈린다(구조검수 「문형 3회」)
        설 = 앞 + "막대와 선의 뜻은 앞 매출 구분의 그림과 같습니다." + ("" if 긴 else " %s의 판매량과 판매단가 가정은 위 표에 있습니다." % 구이)
    else:
        맥._동인범례 = True
        설 = 앞 + "막대는 %s 증가 몫과 %s 변동 몫이고, 선은 매출 증가율입니다.%s%s" % (
            량, 가, " 실적 열은 공시가 판매량과 판매단가를 나눠 주지 않아 매출 증가율만 적었습니다." if 실있음 else "",
            " 겹친 몫에는 환율 조정과 매출 조정 계수의 변동이 함께 들어 있습니다." if 수준 and len(줄들) == 4 else "")
    return _그림블록(맥, "동인", 제목, 설, ["그림의 값"] + 머, 줄들, 키들=키들)


_범위띠말 = {"매출": "매출", "비용": "원가", "인건비": "인건비", "재투자": "투자", "운전자본": "운전자본", "세금": "법인세", "영구": "Terminal Value", "할인율": "할인율"}


def 범위띠그림(맥, 번들, 절키=None, 말=None):
    """② 근거 범위 띠(그림 「범위띠」) — 이 절 가정의 값이 회사 실적 범위 · 같은 정의의 상장사 띠 · 근거 범위의 어디에 서나(변수 카드 재료 — 근거 표와 같은
    판정: 근거 범위는 `_범위쓰나`, 상장사 띠는 칸 단위일 때만). 점은 첫 예측 열 값(빈 점)과 마지막 예측 열(한 값 가정은 그 값 — 찬 점). 줄마다 제 눈금."""
    카 = 카드들(맥)
    if not 카:
        return []
    차례 = list(dict.fromkeys("%s" % b for b in 번들))
    if 절키:
        차례 += [b for b in sorted(카, key=lambda x: int(x)) if b not in 차례 and 항목절(맥, b) == 절키]
    고른 = []
    for 번 in 차례:
        if 번 not in 카 or not 값있나(맥, 번):
            continue
        i, c = 카[번]
        키 = "파일:변수카드:카드:%d:" % i
        칸 = {}
        실 = c.get("회사실적")
        if isinstance(실, dict) and isinstance(실.get("범위"), list) and len(실["범위"]) == 2 and all(_n(v) is not None for v in 실["범위"]):
            칸["실적"] = (키 + "회사실적:범위:0", 키 + "회사실적:범위:1")
        띠 = c.get("같은집단띠")
        if isinstance(띠, dict) and 띠.get("칸단위") and isinstance(띠.get("범위"), list) and len(띠["범위"]) == 2:
            칸["띠"] = (키 + "같은집단띠:범위:0", 키 + "같은집단띠:범위:1")
        if _범위쓰나(맥, 번, c):
            꼬리 = _범위원천(c)[0]
            칸["범위"] = (키 + 꼬리 + ":0", 키 + 꼬리 + ":1")
        if not 칸:
            continue
        값 = c.get("값") if isinstance(c.get("값"), dict) else {}
        점 = {}
        if _n(값.get("첫예측")) is not None and _n(값.get("끝예측")) is not None:
            점["첫"] = 키 + "값:첫예측"
        if _n(값.get("끝예측")) is not None:
            점["끝"] = 키 + "값:끝예측"
        elif _n(값.get("값")) is not None:
            점["끝"] = 키 + "값:값"
        if "끝" not in 점:
            continue
        고른.append((번, 칸, 점))
    if not 고른:
        return []
    띠들 = [(k, 말) for k, 말 in (("실적", "회사 실적 범위"), ("띠", "같은 정의의 상장사 분포 구간"), ("범위", "근거 범위")) if any(k in 칸 for _b, 칸, _p in 고른)]
    점들 = [(k, 말) for k, 말 in (("첫", "첫 예측 값"), ("끝", "이 평가의 값")) if any(k in p for _b, _c, p in 고른)]
    머 = ["가정"] + [x for _k, 말 in 띠들 for x in ("%s 아래" % 말, "%s 위" % 말)] + [말 for _k, 말 in 점들]
    with _키기록(맥) as 키들:
        줄들 = []
        for 번, 칸, 점 in 고른:
            r = [이름(맥, 번)]
            for k, _말 in 띠들:
                r += [_칸글(맥, 번, 칸[k][0]), _칸글(맥, 번, 칸[k][1])] if k in 칸 else ["—", "—"]
            r += [_칸글(맥, 번, 점[k]) if k in 점 else "—" for k, _말 in 점들]
            줄들.append(r)
    말 = 말 or _범위띠말.get(절키 or "", "")
    제목 = "%s가정의 값이 근거 범위에서 서는 자리" % (("%s " % 말) if (말 and len(말) <= 40) else "")   # 1.1.8 — 16 이면 영문 부문 이름이 떨어져 그림 제목이 겹쳤다(⑳ 같은 제목)
    이들목록 = [이름(맥, b) for b, _c, _p in 고른]
    설 = "이 그림의 가정은 %d개입니다." % len(이들목록)
    for k in (3, 2, 1):                                       # 제목 + 첫 문장(한 문장으로 세어진다)이 115자를 넘지 않게 이름을 줄인다(⑬ 131자)
        이들 = " · ".join(이들목록[:k]) + (" 외 %d개" % (len(이들목록) - k) if len(이들목록) > k else "")
        후보 = "이 그림의 가정은 %s." % P.입니다(이들)
        if len(제목) + 3 + len(후보) <= 115:
            설 = 후보
            break
    if not getattr(맥, "_범위띠범례", False):                 # 읽는 법은 첫 그림에 한 번(같은 문형을 되풀이하지 않는다)
        맥._범위띠범례 = True
        설 += (" 줄마다 가로축의 범위가 다릅니다. 띠는 그 가정의 근거가 받치는 범위이고, 점은 이 평가의 값입니다(빈 점은 첫 예측 열, 찬 점은 마지막 예측 열이나 한 값). "
              "상장사 띠는 위 표와 같은 정의로 잰 띠만 실었습니다.")
    return _그림블록(맥, "범위띠", 제목, 설, 머, 줄들, ["l"] + ["r"] * (len(머) - 1), 키들=키들)


_성격차례 = ("변동", "계단", "준고정", "이익", "고정", "조정")


def 레버리지그림(맥, 조):
    """③ 원가 · 판관비 레버리지(그림 「레버리지」 — 쌓기) — 열마다 매출 = 100% 를 영업이익과 성격별 영업비용의 몫으로 쌓는다(고정비 몫이 매출과 함께 어떻게
    줄고 느나). 장부 「가:레버리지」(고정비 몫 · 판매량을 올린 판의 영업레버리지도 — 자체검사 ㉔ 와 같은 셈)가 서면 설명에 한 문장."""
    열 = 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    묶 = {}
    for x in 조:
        묶.setdefault(x["성격"], []).append(x["식"])
    차례 = [성 for 성 in _성격차례 if 성 in 묶]
    if len(차례) < 2 or len(열) < 2:
        return []
    D = "R:기준:2.DCF:%s:%s"
    with _키기록(맥) as 키들:
        줄들 = [["영업이익"] + [맥.식(["÷", D % ("15", c), D % ("11", c)], "퍼1") for c in 열]]
        for 성 in 차례:
            줄들.append([분류말[성]] + [맥.식(["÷", ["합"] + [f[c] for f in 묶[성]], D % ("11", c)], "퍼1") for c in 열])
        덧 = ""
        try:
            몫, dol, 실dol = (_n(맥.값("가:레버리지:%s" % k)) for k in ("몫", "DOL", "실적DOL"))
        except Exception:                                    # noqa: BLE001
            몫 = dol = 실dol = None
        if 몫 is not None and dol is not None:
            덧 = (" 첫 예측 기간 영업비용(감가상각비 · 재고 변동 제외) 가운데 매출 · 판매량에 비례하지 않는 비용의 비중은 %s입니다. 판매량을 %s 올린 경우 영업이익 변화율은 "
                 "매출 변화율의 %s입니다.%s" % (맥.수("가:레버리지:몫", "퍼0"), 맥.수("상:0.1", "퍼0"), 맥.수("가:레버리지:DOL", "배1"),
                                       (" 실적 연도의 같은 비율은 %s였습니다." % 맥.수("가:레버리지:실적DOL", "배1")) if 실dol is not None else ""))
    설 = "막대 하나가 그 기간의 매출이고, 칸은 매출 대비 영업이익과 성격별 영업비용의 몫입니다. 고정비 · 준고정비의 몫이 매출보다 덜 자라면 영업이익률이 오릅니다." + 덧
    return _그림블록(맥, "레버리지", "매출 대비 영업이익과 성격별 영업비용(기준 시나리오, 매출 = 100%)", 설,
                  ["그림의 값"] + [맥.표기(c) for c in 열], 줄들, 키들=키들)


def 인원그림(맥):
    """④ 인건비(그림 「인원」 — 스트림) — 평균 인원 · 1인당 평균급여 · 인건비(연환산)의 실적과 시나리오 셋. 인건비를 인원으로 세운 판에만(인건비 절이 서는 판)."""
    Pr = 맥.기.get("7.Payroll") or {}
    if not (Pr.get("11") and Pr.get("12")):
        return []
    열 = [c for c in 맥.실적열 if (_n((Pr.get("11") or {}).get(c)) or 0) > 0] + 맥.예측열 + ([맥.영구열] if 맥.영구열 else [])
    if len([c for c in 열 if c not in 맥.실적열]) < 2:
        return []
    판들 = (("11", "평균 인원(명)", "명", False), ("12", "1인당 평균급여", "금액", False), ("14", "인건비(연환산)", "어림금액", True))     # 급여는 자릿수를 남긴다(어림이면 계단으로 보인다)
    with _키기록(맥) as 키들:
        줄들 = []
        for 행, 말, 꼴, 연 in 판들:
            if not Pr.get(행):
                continue

            def 칸(시, c, 행=행, 꼴=꼴, 연=연):
                v = _n(((맥.R.get(시) or {}).get("7.Payroll", {}).get(행) or {}).get(c))
                if v is None or (행 == "11" and v <= 0):
                    return "—"
                k = "R:%s:7.Payroll:%s:%s" % (시, 행, c)
                return 맥.식(["÷", k, 맥.년(c)], 꼴) if 연 else 맥.수(k, 꼴)
            실 = ["%s · 실적" % 말] + [칸("기준", c) if c in 맥.실적열 else "—" for c in 열]
            if any(x != "—" for x in 실[1:]):
                줄들.append(실)
            for 시 in ("비관", "기준", "낙관"):
                줄들.append(["%s · %s" % (말, 시)] + ["—" if c in 맥.실적열 else 칸(시, c) for c in 열])
    if len(줄들) < 4:
        return []
    설 = "판마다 굵은 선이 기준, 긴 점선이 비관, 짧은 점선이 낙관이고 점은 실적입니다. 급여는 평균 인원과 1인당 평균급여로 정했고 반기 열의 인건비는 연환산입니다."
    return _그림블록(맥, "인원", "평균 인원 · 1인당 평균급여 · 인건비(실적과 시나리오 셋)", 설, ["그림의 값"] + [맥.표기(c) for c in 열], 줄들, 키들=키들)


def 투자그림(맥):
    """⑤ CAPEX(그림 「투자」 — 쌓기) — 열마다 유지 CAPEX · 성장 CAPEX(매출 연동) · 프로젝트 투자 · 그 밖(환율 조정 · 무형 취득)을 쌓고 감가상각비를 선으로.
    실적 열은 CAPEX 합계 하나. 연환산(반기 열 ÷ 기간)."""
    X = 맥.기.get("8.CapEx") or {}
    if not X.get("31"):
        return []
    열 = [c for c in 맥.실적열 if _n((X.get("31") or {}).get(c)) is not None] + [c for c in 맥.예측열 + ([맥.영구열] if 맥.영구열 else []) if _n((X.get("31") or {}).get(c)) is not None]
    예 = [c for c in 열 if c not in 맥.실적열]
    if len(예) < 2:
        return []
    K = "R:기준:8.CapEx:%s:%s"
    부품 = []
    if X.get("101"):
        부품.append(("유지 CAPEX", "101"))
    if X.get("102") and any(abs(_n((X.get("102") or {}).get(c)) or 0) > 0 for c in 예):
        부품.append(("성장 CAPEX(매출 연동)", "102"))
    프 = [(x, "%d" % (140 + x["번호"])) for x in (맥.구.get("투자") or {}).get("프로젝트") or [] if isinstance(x, dict) and isinstance(x.get("번호"), int)]
    프 = [(x, r) for x, r in 프 if X.get(r) and any(abs(_n((X.get(r) or {}).get(c)) or 0) > 0 for c in 예)]
    이름있 = [(x, r) for x, r in 프 if _글(x.get("이름"))]
    if 프 and len(이름있) == len(프) and len(프) <= 4:
        부품 += [(_글(x["이름"]), r) for x, r in 프]
    elif 프:
        부품.append(("성장 투자 프로젝트", [r for _x, r in 프]))
    if not 부품:
        return []

    def 값(c, 행):
        if isinstance(행, list):
            return ["합"] + [K % (h, c) for h in 행]
        return K % (행, c)

    def 연(식_, c):
        return ["÷", 식_, 맥.년(c)]
    with _키기록(맥) as 키들:
        줄들 = [["CAPEX 실적"] + [맥.식(연(K % ("31", c), c), "어림금액") if c in 맥.실적열 else "—" for c in 열]]
        for 말, 행 in 부품:
            줄들.append([말] + ["—" if c in 맥.실적열 or _n(맥.식값(값(c, 행) if isinstance(행, list) else ["합", 값(c, 행)])) is None
                              else 맥.식(연(값(c, 행), c), "어림금액") for c in 열])
        나머지 = {c: ["−", K % ("31", c), ["합"] + [K % (h, c) for _m, 행 in 부품 for h in (행 if isinstance(행, list) else [행])]] for c in 예}
        if any(abs(_n(맥.식값(나머지[c])) or 0.0) > 0.005 * abs(_n(맥.값(K % ("31", c))) or 1.0) for c in 예):
            줄들.append(["그 밖(환율 조정 · 무형 취득)"] + ["—" if c in 맥.실적열 else 맥.식(연(나머지[c], c), "어림금액") for c in 열])
        if not any(x != "—" for x in 줄들[0][1:]):
            줄들 = 줄들[1:]
        if X.get("34"):
            줄들.append(["감가상각비 (선)"] + [맥.식(연(K % ("34", c), c), "어림금액") if _n((X.get("34") or {}).get(c)) is not None else "—" for c in 열])
    정의 = 맥.원고글(((맥.가정.get("Narrative") or {}).get("열정의") or {}).get("CAPEX") or "", "Narrative.열정의.CAPEX")         if isinstance((맥.가정.get("Narrative") or {}).get("열정의"), dict) else ""
    설 = ("막대는 CAPEX를 투자의 종류별로 쌓은 것이고 선은 감가상각비입니다. 실적 열은 공시 현금흐름표의 유형 · 무형자산 취득액 합계로 정의했고, 추정 열은 "
         "이 평가의 유지 · 성장 CAPEX 가정의 합입니다. 반기 열은 연환산입니다." + ((" " + 정의.strip()) if 정의 and 정의.strip() else ""))
    return _그림블록(맥, "투자", "CAPEX의 구성과 감가상각비(기준 시나리오, 연환산)", 설, ["그림의 값"] + [맥.표기(c) for c in 열], 줄들, 키들=키들)


def 회전그림(맥):
    """⑥ 운전자본(그림 「회전」 — 스트림) — 계정별 회전일수의 실적과 시나리오 셋(판마다 계정 하나)."""
    W = 맥.기.get("9.WC") or {}
    열 = [c for c in 맥.실적열 if any(_n((W.get(k) or {}).get(c)) for k in ("21", "22", "23"))] + 맥.예측열
    if len([c for c in 열 if c not in 맥.실적열]) < 2:
        return []
    with _키기록(맥) as 키들:
        줄들 = []
        for 행, 말 in (("21", "매출채권 회전일수"), ("22", "재고자산 회전일수"), ("23", "매입채무 회전일수")):
            if not any(_n((W.get(행) or {}).get(c)) for c in 맥.예측열):
                continue

            def 칸(시, c, 행=행):
                v = _n(((맥.R.get(시) or {}).get("9.WC", {}).get(행) or {}).get(c))
                return 맥.수("R:%s:9.WC:%s:%s" % (시, 행, c), "일") if v else "—"
            실 = ["%s(일) · 실적" % 말] + [칸("기준", c) if c in 맥.실적열 else "—" for c in 열]
            if any(x != "—" for x in 실[1:]):
                줄들.append(실)
            for 시 in ("비관", "기준", "낙관"):
                줄들.append(["%s(일) · %s" % (말, 시)] + ["—" if c in 맥.실적열 else 칸(시, c) for c in 열])
    if len(줄들) < 3:
        return []
    설 = "판마다 굵은 선이 기준, 긴 점선이 비관, 짧은 점선이 낙관이고 점은 실적입니다. 회전일수가 늘면 같은 매출에 묶이는 운전자본이 커집니다."
    return _그림블록(맥, "회전", "계정별 회전일수(실적과 시나리오 셋, 일)", 설, ["그림의 값"] + [맥.표기(c) for c in 열], 줄들, 키들=키들)


def FCFF그림(맥):
    """⑦ FCFF 다리(그림 「FCFF」 — 쌓기) — 예측 열마다 NOPLAT · 감가상각비(더해진 몫, 0 위)와 CAPEX · 순운전자본 증가(빠진 몫, 0 아래), 선언한 판의 미지급 ·
    한시적 몫을 쌓고 FCFF 를 선으로(엔진 FCFF 식과 같은 줄 · 연환산)."""
    D = 맥.기.get("2.DCF") or {}
    열 = [c for c in 맥.예측열 if _n((D.get("23") or {}).get(c)) is not None]
    if len(열) < 2 or not all(D.get(k) for k in ("19", "20", "21", "22")):
        return []
    K = "R:기준:2.DCF:%s:%s"
    with _키기록(맥) as 키들:
        줄들 = []
        for 행, 말, 부호 in (("19", "NOPLAT", 1), ("20", "감가상각비", 1), ("21", "CAPEX", -1), ("22", "순운전자본 증감", -1),
                          ("111", "미지급 항목 증감", 1), ("112", "한시적 현금흐름(세후)", 1)):
            v = D.get(행) or {}
            if 행 in ("111", "112") and not any(abs(_n(v.get(c)) or 0.0) > 0 for c in 열):
                continue
            줄들.append([말] + [맥.식(["÷", K % (행, c) if 부호 > 0 else ["음", K % (행, c)], 맥.년(c)], "어림금액") if _n(v.get(c)) is not None else "—" for c in 열])
        줄들.append(["FCFF (선)"] + [맥.식(["÷", K % ("23", c), 맥.년(c)], "어림금액") for c in 열])
    설 = "0 위의 칸은 FCFF에 더해진 몫, 0 아래의 칸은 빠진 몫이고 선은 FCFF입니다. CAPEX와 순운전자본 증가는 NOPLAT에서 빠지는 재투자입니다. 반기 열은 연환산입니다."
    return _그림블록(맥, "FCFF", "NOPLAT에서 FCFF까지(기준 시나리오, 연환산)", 설, ["그림의 값"] + [맥.표기(c) for c in 열], 줄들, 키들=키들)


def WACC그림(맥):
    """⑧ WACC 쌓기(그림 「WACC」 — 가로쌓기) — 자기자본비용 = 무위험이자율 + Levered Beta × MRP(+ 그 밖의 프리미엄) · 세전 타인자본비용 = 무위험이자율 + 그 위의 몫 ·
    WACC = 자기자본 몫 + 타인자본 몫(예측기간). 숫자는 엔진 WACC 결과의 키 — 셈 글이 막대 아래에 선다."""
    W = "R:기준:WACC:예측기간:%s"
    if any(_n(맥.값(W % k)) is None for k in ("Rf", "ERP", "베타l", "Ke", "Kd", "Kd세후", "자기자본비중", "타인자본비중", "WACC")):
        return []
    할 = 맥.구.get("할인") or {}
    스말 = "신용스프레드" if 할.get("타인자본비용") != "관측수익률" else "무위험이자율 위의 몫"
    with _키기록(맥) as 키들:
        bm = ["×", W % "베타l", W % "ERP"]
        그밖 = ["−", ["−", W % "Ke", W % "Rf"], bm]
        줄들 = [["자기자본비용 (Ke)", "무위험이자율", 맥.수(W % "Rf", "퍼2")], ["자기자본비용 (Ke)", "Levered Beta × MRP", 맥.식(bm, "퍼2")]]
        if abs(_n(맥.식값(그밖)) or 0.0) >= 0.00005:
            줄들.append(["자기자본비용 (Ke)", "그 밖의 프리미엄", 맥.식(그밖, "퍼2")])
        줄들.append(["자기자본비용 (Ke)", "합계", 맥.수(W % "Ke", "퍼2")])
        if (_n(맥.값(W % "타인자본비중")) or 0) > 0:
            줄들 += [["세전 타인자본비용 (Kd)", "무위험이자율", 맥.수(W % "Rf", "퍼2")], ["세전 타인자본비용 (Kd)", 스말, 맥.식(["−", W % "Kd", W % "Rf"], "퍼2")],
                   ["세전 타인자본비용 (Kd)", "합계", 맥.수(W % "Kd", "퍼2")]]
        줄들 += [["WACC", "자기자본 몫 (Ke × 자기자본 비중)", 맥.식(["×", W % "Ke", W % "자기자본비중"], "퍼2")]]
        if (_n(맥.값(W % "타인자본비중")) or 0) > 0:
            줄들.append(["WACC", "타인자본 몫 (세후 Kd × 타인자본 비중)", 맥.식(["×", W % "Kd세후", W % "타인자본비중"], "퍼2")])
        줄들.append(["WACC", "합계", 맥.수(W % "WACC", "퍼2")])
    설 = "막대마다 아래 셈의 칸을 쌓았습니다. 자기자본비용은 무위험이자율에 Levered Beta × MRP를 더한 값이고, WACC 값은 두 자본비용을 자본 비중으로 가중한 값입니다."
    return _그림블록(맥, "WACC", "자본비용의 구성(예측기간, %)", 설, ["막대", "칸", "값"], 줄들, ["l", "l", "r"], 키들=키들)


def 베타그림(맥):
    """⑧ 유사기업 βU 분포(그림 「표본」) — Peer group 회사마다 Unlevered Beta(엔진 3번 111~120) 점, 중앙값 · 평균 · 이 평가의 채택값(3번 10)은 세로선.
    Peer group 표가 둘 이상 서는 판에만(업종 베타를 바로 쓴 판은 표본이 없다)."""
    W3 = 맥.기.get("3.WACC") or {}
    W = "R:기준:3.WACC:%s:%s"
    점 = []
    for x in (맥.구.get("할인") or {}).get("유사기업") or []:
        if not isinstance(x, dict) or not isinstance(x.get("번호"), int):
            continue
        키 = "%d" % (110 + x["번호"])
        v = W3.get(키)
        if isinstance(v, dict) and v and _글(x.get("이름")):
            칸 = list(v.keys())[0]
            if _n(v.get(칸)) is not None:
                점.append((_글(x["이름"]), W % (키, 칸)))
    if len(점) < 2:
        return []
    선 = []
    for 키, 말 in (("122", "중앙값"), ("121", "평균")):
        v = W3.get(키)
        if isinstance(v, dict) and v and _n(list(v.values())[0]) is not None:
            선.append([말, W % (키, list(v.keys())[0])])
    채 = W % ("10", "예측값")
    if _n(맥.값(채)) is None:
        return []
    같 = next((s for s in 선 if abs((_n(맥.값(s[1])) or 0) - (_n(맥.값(채)) or 0)) < 1e-9), None)
    if 같:
        같[0] += " · 이 평가의 채택값"
    else:
        선.append(["이 평가의 채택값", 채])
    with _키기록(맥) as 키들:
        줄들 = [[이, 맥.수(k, "지수3")] for 이, k in 점] + [["%s (선)" % 말, 맥.수(k, "지수3")] for 말, k in 선]
    설 = "점은 Peer group 회사의 Unlevered Beta이고, 세로선은 중앙값 · 평균과 이 평가가 채택한 값입니다. 베타는 단위가 없는 계수입니다."
    return _그림블록(맥, "표본", "Peer group의 Unlevered Beta와 채택값(예측기간)", 설, ["Peer group", "Unlevered Beta"], 줄들, ["l", "r"], 키들=키들)


def TV몫그림(맥):
    """⑨ TV 몫(그림 「TV몫」 — 쌓기) — 시나리오마다 영업가치 = 예측기간 FCFF 현재가치 + Terminal Value 현재가치(+ 그 밖의 조정)."""
    K = "R:%s:2.DCF:%s"
    if any(_n(맥.값(K % (시, k))) is None for 시 in ("비관", "기준", "낙관") for k in ("40", "54", "58")):
        return []
    with _키기록(맥) as 키들:
        줄들 = [["예측기간 FCFF의 현재가치"] + [맥.수(K % (시, "40"), "어림금액") for 시 in ("비관", "기준", "낙관")],
              ["Terminal Value의 현재가치"] + [맥.수(K % (시, "54"), "어림금액") for 시 in ("비관", "기준", "낙관")]]
        그밖 = {시: ["−", K % (시, "58"), ["합", K % (시, "40"), K % (시, "54")]] for 시 in ("비관", "기준", "낙관")}
        if any(abs(_n(맥.식값(그밖[시])) or 0.0) > 0.005 * abs(_n(맥.값(K % (시, "58"))) or 1.0) for 시 in 그밖):
            줄들.append(["그 밖의 조정(지급 시점 · 상각 · 세액공제 이월)"] + [맥.식(그밖[시], "어림금액") for 시 in ("비관", "기준", "낙관")])
        몫 = " · ".join("%s %s" % (시, 맥.식(["÷", K % (시, "54"), K % (시, "58")], "퍼0")) for 시 in ("비관", "기준", "낙관"))
    설 = "막대 하나가 그 시나리오의 영업가치입니다. 영업가치 가운데 Terminal Value 현재가치의 몫은 %s입니다." % 몫
    return _그림블록(맥, "TV몫", "시나리오별 영업가치의 구성(현재가치)", 설, ["그림의 값", "비관", "기준", "낙관"], 줄들, 키들=키들)


def 정합그림(맥):
    """⑨ 영구 정합(그림 「정합」 — 가로 막대와 기준선) — 영구성장률 · 재투자율(g ÷ ROIC) · 영구기간 ROIC(새 투자) · 기존 자본의 수익률을 막대로,
    영구기간 WACC 를 세로선으로(ROIC 이 선의 오른쪽이면 성장이 가치를 더한다)."""
    D = "R:기준:2.DCF:%s"
    if any(_n(맥.값(D % k)) is None for k in ("46", "47", "48", "49")):
        return []
    with _키기록(맥) as 키들:
        줄들 = [["영구성장률 (g)", 맥.수(D % "47", "퍼1")], ["재투자율 (g ÷ 영구기간 ROIC)", 맥.수(D % "49", "퍼1")], ["영구기간 ROIC (새 투자)", 맥.수(D % "48", "퍼1")]]
        if _n(맥.값(D % "86")) and _n(맥.값(D % "45")) is not None:
            줄들.append(["기존 자본의 수익률", 맥.식(["÷", D % "45", D % "86"], "퍼1")])
        줄들.append(["영구기간 WACC (선)", 맥.수(D % "46", "퍼1")])
    설 = "막대가 세로선(영구기간 WACC)의 오른쪽이면 그 수익률이 자본비용보다 높습니다. 재투자율은 영구성장률을 영구기간 ROIC으로 나눈 값입니다."
    return _그림블록(맥, "정합", "영구성장률 · 재투자율 · ROIC과 영구기간 WACC(%)", 설, ["항목", "값"], 줄들, ["l", "r"], 키들=키들)


def 전파그림(맥):
    """⑪ 시나리오 전파(그림 「전파」) — 시나리오 × 줄별 변화 표(`전파`)를 기준 대비 변화율로. 기준과 같은 줄은 「같음」(빈 점), 기준이 0 이하이거나
    매출의 2% 미만인 금액 줄은 변화율로 견주지 않는다(「—」 — 금액은 위 표)."""
    d = 전파(맥)
    if not d:
        return []
    기매 = abs(_n(맥.값("R:기준:2.DCF:11:%s" % d["열"])) or 0.0)
    with _키기록(맥) as 키들:
        줄들 = []
        for r in d["줄"]:
            기 = _n(맥.값(r["기준키"]))
            칸 = [r["이름"]]
            for 시 in 전파쪽:
                v = _n(맥.값(r["쪽"][시]["키"]))
                if v is not None and 기 is not None and abs(v - 기) <= 1e-12 * max(1.0, abs(기)):
                    칸.append("같음")
                elif v is None or 기 is None or 기 <= 0 or (r["키"] != "주당" and 기 < 0.02 * 기매):
                    칸.append("—")
                else:
                    칸.append(맥.식(["괴리", r["쪽"][시]["키"], r["기준키"]], "증1"))
            if any(c != "—" for c in 칸[1:]):                 # 두 쪽 다 「—」 인 줄은 싣지 않는다(금액은 위 표)
                줄들.append(칸)
        작 = 맥.수("상:0.02", "퍼0") if any("—" in r[1:] for r in 줄들) else ""
    if len(줄들) < 3:
        return []
    설 = "막대는 비관 · 낙관 시나리오의 값이 기준 시나리오와 다른 정도이고, 빈 점은 기준과 같은 항목입니다. 원인은 위 표의 「변동 원인」에 있습니다."
    if 작:
        설 += " 「—」는 기준이 0 이하이거나 매출의 %s에 못 미쳐 변화율로 비교하지 않은 항목입니다." % 작
    return _그림블록(맥, "전파", "시나리오별 항목 변동(%s, 기준 대비 %%)" % 맥.열말(d["열"]), 설, ["항목", "비관 − 기준", "낙관 − 기준"], 줄들, ["l", "r", "r"], 키들=키들)


def _실적이익률식(맥):
    """실적 열마다 영업이익률 식 → [(식, 값)] (값이 있는 열만). 1.1.20 — 범위 잣대이므로 회계연도 열만(반기 · 분기 열은 빼고 · `레터1부.연간실적열`)."""
    낸 = []
    for c in P.연간실적열(맥):
        식 = ["÷", "R:기준:2.DCF:15:%s" % c, "R:기준:2.DCF:11:%s" % c]
        v = 맥.식값(식)
        if v is not None:
            낸.append((식, v))
    return 낸


def 역산자그림(맥):
    """⑩ 증가율 경로의 역산 자(그림 「역산자」 — 범위띠) — 표 Ⅳ(가정 하나씩 푼 역산)의 줄마다 이 가격에 필요한 값 · 채택값 · 비관 · 낙관 시나리오의 값과
    실적 · Normalization 범위(이익률 줄). 정상 수준을 푼 판(수준 경로 — 그림 「자」 · 「곡선」 이 선다)과 종가가 없는 판에는 서지 않는다."""
    if not 맥.종가키:
        return []
    b = T.바닥(맥)
    if b and b.get("풀이"):
        return []
    L_ = _L()
    with _키기록(맥) as 키들:
        표4 = P._표4줄들(맥)
        줄들 = []
        for r in 표4:
            if r["내재"] is None or r["비고"]:
                continue
            g, 꼴 = r["갈래"], r["꼴"]
            대 = "%s" % (r["h"]["대상"] or [""])[0]
            실, 정, 시값 = ["—", "—"], ["—", "—"], {}
            if g in ("영구이익률가감", "Normalization"):
                쌍 = _실적이익률식(맥)
                if 쌍:
                    lo, hi = min(쌍, key=lambda t: t[1]), max(쌍, key=lambda t: t[1])
                    실 = [맥.식(lo[0], "퍼1"), 맥.식(hi[0], "퍼1")]
                if _n(L_._시점값(맥.가정, "950", "기준")) is not None and _n(L_._시점값(맥.가정, "951", "기준")) is not None:
                    정 = [맥.수("S:950:기준", "퍼1"), 맥.수("S:951:기준", "퍼1")]
                시값 = {시: ("R:%s:2.DCF:42" % 시, "퍼1") for 시 in ("비관", "낙관")}
            elif g.startswith("WACC"):
                시값 = {시: ("R:%s:WACC:예측기간:WACC" % 시, "퍼2") for 시 in ("비관", "낙관")}
            elif 대.isdigit() and 대 in (맥.가정.get("시점가정") or {}):
                시값 = {시: ("S:%s:%s" % (대, 시), 꼴) for 시 in ("비관", "낙관") if _n(L_._시점값(맥.가정, 대, 시)) is not None}
            elif 대.isdigit() and 대 in (맥.가정.get("가정") or {}) and 맥.끝예측:
                시값 = {시: ("A:%s:%s:%s" % (대, 시, 맥.끝예측), 꼴) for 시 in ("비관", "낙관") if _n(L_._가정값(맥.가정, 대, 시, 맥.끝예측)) is not None}
            줄들.append([r["이름"]] + 실 + 정 + [맥.수(시값[시][0], 시값[시][1]) if 시 in 시값 else "—" for 시 in ("비관", "낙관")]
                       + [r["적용"], r["내재"]])
    if not 줄들:
        return []
    머 = ["가정", "실적 아래", "실적 위", "Normalization 범위 아래", "Normalization 범위 위", "비관", "낙관", "채택", "이 가격에 필요한 값"]
    설 = ("가정 하나만 풀고 다른 가정은 채택값대로 둔 값입니다. 줄마다 가로축의 범위가 다르고, 점과 띠의 뜻은 그림 위에 적었습니다. 이 그림은 %s 맞는지 판정하지 않습니다."
         % P.이(P.종가말(맥)))
    return _그림블록(맥, "역산자", "%s에 필요한 값과 실적 · 시나리오의 범위" % P.종가말(맥), 설, 머, 줄들, ["l"] + ["r"] * 8, 키들=키들)


def 역산곡선그림(맥):
    """⑩ 증가율 경로의 역산 곡선(그림 「곡선」) — 영구기간 영업이익률을 격자 값으로 둘 때의 주당가치(장부 키 「가:이익률:<m>」 — 게이트가 같은 셈을 다시 돈다)를
    가로축(주가)에, 그 이익률을 세로축에. 가로선은 이 평가의 값, 세로선은 평가기준일 종가. 표 Ⅳ 에 영구기간 영업이익률 줄이 풀린 판에만."""
    if not 맥.종가키:
        return []
    b = T.바닥(맥)
    if b and b.get("풀이"):
        return []
    줄4 = next((x for x in ((맥.민 or {}).get("표4") or {}).get("줄") or [] if x.get("대상") in (["영구이익률가감"], ["213"]) and _n(x.get("내재값")) is not None), None)
    기 = _n(맥.값("R:기준:2.DCF:42"))
    if 줄4 is None or 기 is None:
        return []
    값들 = [_n(줄4["내재값"]), 기] + [_n(맥.값("R:%s:2.DCF:42" % 시)) for 시 in ("비관", "낙관")] + [v for _s, v in _실적이익률식(맥)]
    값들 = [v for v in 값들 if v is not None]
    lo, hi = min(값들), max(값들)
    걸 = max(0.005, math.ceil(((hi - lo) / 6.0) / 0.005) * 0.005)
    처음 = math.floor(lo / 0.005) * 0.005
    ms = [round(처음 + 걸 * k, 4) for k in range(7)]
    ms = [m for m in ms if 0 < m < 1]
    if len(ms) < 4:
        return []
    with _키기록(맥) as 키들:
        줄들 = []
        for m in ms:
            v = _n(맥.값("가:이익률:%.4f" % m))
            if v is None:
                continue
            줄들.append([맥.수("가:이익률:%.4f" % m, "주당"), 맥.수("상:%.4f" % m, "퍼1")])
        덧 = [(["가로선", "영구기간 영업이익률"], [["이 평가의 기준", 맥.수("R:기준:2.DCF:42", "퍼1")]]),
             (["세로선", "주가"], [[P.종가말(맥), 맥.수(맥.종가키, "주당")]])]
    if len(줄들) < 4:
        return []
    설 = ("가로축이 주가, 세로축이 그 주가가 맞으려면 필요한 영구기간 영업이익률입니다. 영구기간 영업이익률 말고 다른 가정은 기준 그대로 두었습니다. "
         "세로선은 %s이고 가로선은 이 평가의 값입니다." % P.종가말(맥))
    return _그림블록(맥, "곡선", "주가와 그 주가가 전제한 영구기간 영업이익률(%)", 설, ["주가", "영구기간 영업이익률"], 줄들, ["r", "r"], 덧표=덧, 키들=키들)


# ══════════════════════════════════════════════════════════════════ 절 첫 줄 — 결론 한 문장 + 그 결론이 주당가치를 움직이는 폭 (2026-10-31 L8)

def 업황가정(맥):
    """업황 절의 판단이 닿는 가정 — 경쟁 · 업황 문단의 「가정」 목록(값이 있는 번호)."""
    절 = _N(맥).get("절글") if isinstance(_N(맥).get("절글"), dict) else {}
    낸 = []
    for 키 in ("업황", "경쟁"):
        for x in 절.get(키) or []:
            for b in (x.get("가정") or []) if isinstance(x, dict) else []:
                b = ("%s" % b).replace("A-", "")
                if b.isdigit() and 값있나(맥, b) and b not in 낸:
                    낸.append(b)
    return 낸


def _뗀이름(맥, 번):
    """가정 이름에서 괄호 덧말을 걷는다(절 첫 줄 — 괄호 안 괄호를 만들지 않는다 · ⑬ 겹괄호)."""
    return re.sub(r"\s*\([^()]*\)", "", 이름(맥, 번)).strip() or 이름(맥, 번)


def _이름묶(맥, 번들):
    return "%s%s" % (_뗀이름(맥, 번들[0]), (" 외 %d개" % (len(번들) - 1)) if len(번들) > 1 else "")


_수관형 = {2: "두", 3: "세", 4: "네", 5: "다섯", 6: "여섯", 7: "일곱", 8: "여덟", 9: "아홉", 10: "열"}


def 가정수말(n):
    """1.1.21 — 앞에 이름을 든 가정을 다시 가리키는 말을 가정 수에 맞춘다: 1 → 「이 가정」 · 2 → 「이 두 가정」 · 3 → 「이 세 가정」 · 11 이상 → 「이 11개 가정」
    (ADDER80 백테스트: 지렛대 · 절 가정이 둘 이상인데 「이 가정만 …」 — 지시불명 · 원칙 8)."""
    n = int(n or 0)
    if n <= 1:
        return "이 가정"
    return "이 %s 가정" % _수관형[n] if n in _수관형 else "이 %d개 가정" % n


def _이름나열(맥, 번들, 상한=4):
    """1.1.21 — 가정 이름을 「외 N개」 로 줄이지 않고 바로 나열한다(「A · B · C」). 상한을 넘으면 앞 (상한 − 1)개와 「등 N개」."""
    이들 = [_뗀이름(맥, b) for b in 번들]
    if len(이들) <= 상한:
        return " · ".join(이들)
    return "%s 등 %d개" % (" · ".join(이들[:상한 - 1]), len(이들))


def _열가름글(맥, 시, 번들):
    """레터 v27 P2 — 그 시나리오 값을 예측기간 열 · 영구기간 열에만 옮긴 주당가치 한 문장(장부 키 「가:홀로열」). 가를 수 없으면 빈 글."""
    if not N.열갈리나(맥.가정, 번들):
        return ""
    한 = N.가를수없는한값(맥.가정, 번들)
    return "예측기간 값만 바꾸면 %s, 영구기간 값만 바꾸면 %s%s." % (
        맥.수(N.홀로열키(시, "예측", 번들), "주당"), P.입니다(맥.수(N.홀로열키(시, "영구", 번들), "주당")),
        ("(%s 두 계산에서 기준 값)" % P.은(_이름나열(맥, 한))) if 한 else "")


def 절폭글(맥, 절키):
    """그 절 가정(시나리오마다 값이 다른 번호 — `레터.폭포묶음`)만 비관 · 낙관의 값으로 옮기고 다른 가정은 기준 그대로 둔 주당가치의 폭 한 문장
    (장부 키 「가:홀로:<시>:<번+번>」 — 결론 「갈림」 줄과 같은 잣대 · 게이트가 같은 함수로 다시 셈한다). 업황 절은 경쟁 · 업황 문단이 닿는 가정.
    갈리는 가정이 없거나 값이 없으면 빈 글.
    레터 v27(R5 P2 · P4) — 값은 늘 비관 → 낙관 차례로 쓴다. 두 끝이 기준의 상대 문턱(`귀속.상대문턱`) 안이거나 표시 반올림이 같으면 「거의 움직이지 않는다」.
    비관 값이 기준보다 높거나 낙관 값이 낮으면(역방향) 그렇다고 쓰고 예측기간 · 영구기간 열로 가른 값(「가:홀로열」)을 붙인다. 순방향인데 묶음의 끝이
    성분 하나의 끝보다 기준에 가까우면 거꾸로 움직인 성분 이름을 붙인다(상쇄). 딸린행(`시나리오이야기.<쪽>.딸린행`)은 축이 같은 절에 없으면 홀로 옮기지 않는다."""
    import 레터 as _L                                       # noqa: PLC0415
    묶음 = _L.폭포묶음(맥.가정, 맥.구)
    갈린 = {b for _이, bs in 묶음 for b in bs}
    if 절키 == "업황":
        고른 = [b for b in 업황가정(맥) if b in 갈린]
    else:
        고른 = [b for b in 갈린 if 항목절(맥, b) == 절키]
    고른 = sorted(set(고른), key=lambda x: (len(x), int(x) if x.isdigit() else 0, x))
    if not 고른:
        # 인쇄 조건 — 그 절에 값이 있는 가정이 있는데 시나리오마다 갈리는 것이 없을 때만(할인율 · 업황은 번호 밖의 입력이라 찍지 않는다)
        import 레터원고 as W                                 # noqa: PLC0415
        층 = W.층번호들(맥).get(절키) if 절키 not in ("할인율", "업황") else None
        if 층:                                               # 절마다 다른 글이 되게 가정 이름을 든다(구조검수 「문형 3회 반복」)
            안닿 = _L.값안닿는번호(맥.가정, 맥.구)          # v27 P3 — 갈려도 값에 쓰이지 않는 대조값은 「같다」 고 세지 않는다
            이들 = [_뗀이름(맥, b) for b in 층 if 값있나(맥, b) and b not in 안닿]
            # v27 문장(교열 75 · 91 · 100 · 111 · 265) — 「이 절의 가정」 은 그 절의 가정 이름(투자 가정 · 운전자본 가정 …)으로
            return ("%s 가정은 %s%s 모두 세 시나리오에 같은 값을 적용했습니다. 시나리오별 주당가치 차이는 다른 가정에서 생깁니다." % (
                _범위띠말.get(절키) or "이 절의", 이들[0], (" 외 %d개" % (len(이들) - 1)) if len(이들) > 1 else "")) if 이들 else ""
        return ""
    # v27 문장(교열 270) — 「갈리는 · 옮기고 · 움직인다」 → 「다르게 둔 · 바꾸고 · 달라집니다」, 「이 절에서」 는 그 절의 가정 이름으로
    머말 = ("시나리오마다 값을 다르게 둔 %s 가정은" % _범위띠말[절키]) if 절키 in _범위띠말 else "업황과 경쟁 판단을 반영한 가정 가운데 시나리오마다 값을 다르게 둔 가정은"
    셀, 딸 = N.딸림뺀(맥.가정, 고른)
    # 1.1.21 — 다시 가리키는 말(「이 가정만」)은 가정 수에 맞춘다(`가정수말` — 두 가정 이상인데 「이 가정만」 이던 지시불명 · 원칙 8)
    딸말 = "다른 가정의 시나리오 값에 연동되는 항목이므로 %s만 바꾼 주당가치는 따로 산정하지 않았습니다." % 가정수말(len(딸))
    딸글 = ("%s %s" % (P.은(_이름나열(맥, 딸)), 딸말)) if 딸 else ""
    if not 셀:
        return "%s %s. %s %s" % (머말, P.입니다(_이름나열(맥, 딸)), P.은(가정수말(len(딸))), 딸말)
    키 = "+".join(셀)
    기 = "R:기준:2.DCF:68"
    a, c = "가:홀로:비관:%s" % 키, "가:홀로:낙관:%s" % 키
    va, vc, 기v = _n(맥.값(a)), _n(맥.값(c)), _n(맥.값(기))
    if va is None or vc is None or 기v is None:
        return 딸글
    문 = N.귀속문턱()
    머 = "%s %s." % (머말, P.입니다(_이름나열(맥, 셀)))                # 1.1.21 — 「A 외 N개」 대신 이름을 바로 나열
    if len(머) > 110:                                         # 이름이 길면(영문 구분 이름) ⑬ 문장 길이 — 머리말을 줄이고, 그래도 길면 「A 외 N개」
        머 = "시나리오마다 값을 다르게 둔 가정은 %s." % P.입니다(_이름나열(맥, 셀))
        if len(머) > 110 and len(셀) > 1:
            머 = "시나리오마다 값을 다르게 둔 가정은 %s 외 %d개입니다." % (_이름나열(맥, 셀[:1]), len(셀) - 1)
    이말 = 가정수말(len(셀))
    ja, jc = N.움직임(va, 기v, 문), N.움직임(vc, 기v, 문)
    꼴 = lambda v: _L.꼴글(v, "주당", 맥.메타)                # noqa: E731 — 표시 반올림(장부에 적지 않는다)
    if (ja == 0 and jc == 0) or 꼴(va) == 꼴(vc) == 꼴(기v):
        return " ".join(x for x in (머, "%s 세 시나리오의 값으로 바꿔도 주당가치는 거의 달라지지 않습니다(기준의 %s 미만)." % (P.을(이말), 맥.수("상:%r" % 문, "퍼1")), 딸글) if x)
    if ja <= 0 <= jc:                                       # 순방향 — 비관 값에서 낙관 값까지
        글 = ("%s %s만 비관 · 낙관 시나리오의 값으로 바꾸고 다른 가정은 기준 시나리오대로 두면 주당가치는 %s에서 %s까지 달라집니다." % (
            머, 이말, 맥.수(a, "주당"), 맥.수(c, "주당")))
        상 = []
        _축, 딸린 = N.축딸린(맥.가정)
        성분 = [[b for b in bs if b in 셀] for _이, bs in 묶음]
        성분 = [s for s in 성분 if s and len(s) < len(셀) and not set(s) <= 딸린]      # 딸린행만의 성분은 홀로 귀속을 이름하지 않는다(P4)
        for 시, 끝키, 끝v, 정 in (("비관", a, va, -1), ("낙관", c, vc, 1)):
            if len(성분) < 2:
                break
            거꾸 = []
            for s in 성분:
                k = N.홀로키(시, s)
                v = _n(맥.값(k))
                if v is not None and N.움직임(v, 기v, 문) == -정:
                    거꾸.append((s, k))
            먼 = max((abs((_n(맥.값(N.홀로키(시, s))) or 기v) - 기v) for s in 성분), default=0.0)
            if 거꾸 and abs(끝v - 기v) < 먼:
                상.append("그 가운데 %s %s 시나리오의 값으로 바꾸면 주당가치가 오히려 %s %s 범위가 좁아집니다." % (
                    P.을(_이름나열(맥, 거꾸[0][0])), 시, P.으로(맥.수(거꾸[0][1], "주당")), "올라" if 정 < 0 else "내려"))
        return " ".join([글] + 상 + ([딸글] if 딸글 else []))
    문장 = [머]                                             # 역방향 — 비관 → 낙관 차례로, 거꾸로 간 쪽은 예측기간 · 영구기간으로 가른다
    if ja > 0:
        문장 += ["%s만 비관 시나리오의 값으로 바꾸고 다른 가정은 기준 시나리오대로 두면 주당가치는 오히려 %s 오릅니다." % (이말, P.으로(맥.수(a, "주당"))),
               _열가름글(맥, "비관", 셀)]
    else:
        문장 += ["%s만 비관 시나리오의 값으로 바꾸고 다른 가정은 기준 시나리오대로 두면 주당가치는 %s." % (이말, P.입니다(맥.수(a, "주당")))]
    if jc < 0:
        문장 += ["낙관 시나리오의 값으로 바꾸면 오히려 %s 내립니다." % P.으로(맥.수(c, "주당")), _열가름글(맥, "낙관", 셀)]
    else:
        문장 += ["낙관 시나리오의 값으로 바꾸면 %s." % P.입니다(맥.수(c, "주당"))]
    return " ".join(x for x in 문장 + [딸글] if x)


# ══════════════════════════════════════════════════════════════════ 추정 블록의 꼴(레터 v27 6단계 D)
# 추정 블록(매출 · 영업비용 · 인건비 · 설비투자 · 운전자본 · 법인세와 FCFF · 할인율 · Terminal Value · 가치 브리지)은 같은 차례로 선다 —
#   머리(절 결론 + 원고 「머리」 한 문단) → 「가정과 결과」 표(`레터추정표` — 블록마다 한 장, 매출은 반대 쪽 대조 표가 둘째 표) →
#   원고 통째(줄 문단은 근거표의 줄 차례 → 연결 → 인건비 → 결과와 대조 → 한계 → 시나리오 반응) → 그 절의 사업 그림.
# 코드가 블록에 쓰는 글은 표 제목 · 표 아래 열 정의뿐이다. 옛 절이 싣던 표(세 시나리오 가정표 · 근거 범위표 · 범위띠 · 원가 구성표 · 계정 배치표 ·
# 전방별 매출표 따위)는 부록 「추정 블록의 근거 표」 로 옮기고, 옛 절의 조립 문장은 싣지 않는다. 근거표를 짓지 못하면 옛 절 그대로(알림).

블록원고차례 = {"줄": 1, "표": 2, "연결": 3, "인건비": 4, "대조": 5, "한계": 6, "시나리오": 7}


def 블록꼴(맥):
    """추정 블록을 새 꼴로 짓나 — 근거표가 서면 참."""
    import 레터원고 as W                                     # noqa: PLC0415
    return W.근거표(맥) is not None


def _옛조각나누기(L):
    """옛 절의 줄들(머리 두 줄 뺀) → (그림 덩이 [(종, 줄들)], 표 덩이 [줄들]). 산문 · 소제목 · 조립 문장은 버린다."""
    그림, 표 = [], []
    L = ["%s" % x for x in L]
    i, n = 0, len(L)
    while i < n:
        x = L[i]
        if x.startswith("<!-- 그림:"):
            j = i + 1
            while j < n and L[j].strip() and not L[j].startswith("|"):
                j += 1
            while j < n and not L[j].strip():
                j += 1
            while j < n and L[j].startswith("|"):
                j += 1
                if j + 1 < n and not L[j].strip() and L[j + 1].startswith("|"):       # 덧표(둘째 · 셋째 표)
                    j += 1
            종 = x[len("<!-- 그림:"):].split("-->")[0].strip()
            그림.append((종, L[i:j] + [""]))
            i = j
            continue
        if x.startswith("**표.") or x.startswith("|"):
            j = i + 1 if x.startswith("**표.") else i
            while x.startswith("**표.") and j < n and not L[j].strip():
                j += 1
            if j < n and L[j].startswith("|"):
                while j < n and L[j].startswith("|"):
                    j += 1
                k = j + 1 if j < n and not L[j].strip() else j          # 표 바로 아래 한 문단이 표 주석(표의 말을 「」 로 짚어 읽는 법을 적은 글)이면 표와 함께 옮긴다
                if k < n and L[k].strip() and not L[k].startswith(("|", "**", "<!--", "#")) and "「" in L[k]:
                    표.append(L[i:j] + ["", L[k], ""])
                    i = k + 1
                    continue
                표.append(L[i:j] + [""])
                i = j
                continue
        i += 1
    return 그림, 표


def _자리표시글(맥, 글):
    """원고 글의 장부 자리표시마다 [{키, 글}] — 장부가 찍은 글(편집 대조가 블록에 그 숫자가 남았나를 본다)."""
    import 레터원고 as W                                     # noqa: PLC0415
    낸 = []
    for m in W._자리표시.finditer("%s" % (글 or "")):
        키 = W.원고키들(m.group(0))
        if not 키:
            continue
        try:
            찍 = N.키풀어글(맥.원, m.group(0), 맥.메타)
        except Exception:                                    # noqa: BLE001
            continue
        if 찍 and 찍 != m.group(0) and 찍 != "—":
            낸.append({"키": 키, "글": 찍})
    return 낸


def _원고자리적기(맥, 절키, 번, i, x, 새):
    if not isinstance(getattr(맥, "원고자리", None), dict):
        return
    요 = x.get("요소") if isinstance(x, dict) else None
    맥.원고자리["%s[%d]" % (절키, i)] = {
        "글": " ".join(l for l in 새 if l.strip() and not l.startswith("|")),
        "요소": [요] if isinstance(요, str) else [e for e in (요 or []) if isinstance(e, str)],
        "자리": x.get("자리") if isinstance(x, dict) else None, "줄": (x.get("줄") if isinstance(x, dict) else None),
        "절": 절키, "번": 번, "원문": (x.get("글") if isinstance(x, dict) else x) or "",
        "자리표시": _자리표시글(맥, x.get("글") if isinstance(x, dict) else x)}


def 블록원고(맥, 절키, 번, 머리뺌=True):
    """블록 원고(머리 뺀 나머지)를 차례대로 → 줄들. 블록의 꼴(자리)이 아니면 적힌 차례 그대로(옛 꼴 원고 · 「뒤」 는 보지 않는다)."""
    import 레터원고 as W                                     # noqa: PLC0415
    조각 = W._절조각(맥.가정, 절키)
    새꼴 = W.블록꼴인가(맥.가정, 절키)
    근 = W.근거표(맥) or {}
    줄차례 = {z["id"]: k for k, (_b, z) in enumerate(W.블록줄들(근, W.블록절.get(절키, ())))}
    항 = []
    for i, x in enumerate(조각):
        if 새꼴:
            자 = x.get("자리") if isinstance(x, dict) else None
            if 자 == "머리" and 머리뺌:
                continue
            if 자 is None:
                자 = "표" if isinstance(x, dict) and isinstance(x.get("표"), dict) else None
            if 자 not in 블록원고차례:
                continue
            항.append(((블록원고차례[자], 줄차례.get(x.get("줄"), 999) if 자 == "줄" else 0, i), i, x))
        else:
            항.append(((0, 0, i), i, x))
    L = []
    for _k, i, x in sorted(항, key=lambda t: t[0]):
        새 = M.절글줄(맥, "Narrative.절글.%s[%d]" % (절키, i), x)
        if not 새:
            continue
        _원고자리적기(맥, 절키, 번, i, x, 새)
        L += 새
    if not 새꼴:                                              # 옛 꼴 원고 — 그 절에 함께 실리던 옛 키(매출 구분 · 판관 · 인건비미분리)도 적힌 차례로
        절글 = (_N(맥).get("절글") or {}) if isinstance(_N(맥).get("절글"), dict) else {}
        덧키 = {"매출": sorted((k for k in 절글 if k.startswith("매출.")), key=lambda k: (k == "매출.연결", k)),
              "비용": ["판관", "인건비미분리"]}.get(절키, [])
        for k in 덧키:
            for i, x in enumerate(W._절조각(맥.가정, k)):
                새 = M.절글줄(맥, "Narrative.절글.%s[%d]" % (k, i), x)
                if 새:
                    _원고자리적기(맥, k, 번, i, x, 새)
                    L += 새
    return L


def 열정의덧(맥, 표줄):
    """실적 열과 추정 열이 함께 선 블록 표에 CAPEX · 차입 같은 정의가 갈리는 줄(`정합설정.json` 「열정의」 이름)이 있으면 표 바로 뒤에 두 열의 정의 한 줄 —
    처음은 두 열의 정의(표 설명 — 투자 그림의 열 정의와 같은 말) 뒤에 원고(`Narrative.열정의.CAPEX` — 무엇을 포함 · 제외했나), 그 뒤 표는 같은 기준이라는 표 설명 한 줄."""
    import 레터정합 as J                                     # noqa: PLC0415
    이름 = (J.설정().get("열정의") or {}).get("이름") or []
    머 = next((x for x in 표줄 if x.startswith("| 줄 |")), "")
    if "실적" not in 머 or not ("추정" in 머 or "예측" in 머):
        return []
    if not any(x.startswith("|") and any(w in x.split("|")[1] for w in 이름) for x in 표줄):
        return []
    if getattr(맥, "_CAPEX열정의", False):
        return ["열 정의 — 이 표의 CAPEX 는 실적 · 추정 열 모두 설비투자와 감가상각 블록의 표와 같은 기준입니다."]
    맥._CAPEX열정의 = True
    원 = ((_N(맥).get("열정의") or {}).get("CAPEX")) if isinstance(_N(맥).get("열정의"), dict) else None
    글 = N.펴기(맥, 원, "Narrative.열정의.CAPEX") if _글(원) else ""
    return (["열 정의 — 실적 열의 CAPEX 는 공시 현금흐름표의 유형 · 무형자산 취득액 합계로 정의했고, 추정 열은 유지 · 성장 CAPEX 가정의 합입니다."]
            + ([글] if 글 else []))


def 블록머리글(맥, 절키, 번):
    """블록 첫 문단 — 절 결론(`Narrative.절결론.<절>`) + 원고 「머리」. 둘 다 없으면 빈 글."""
    import 레터원고 as W                                     # noqa: PLC0415
    결론 = (_N(맥).get("절결론") or {}) if isinstance(_N(맥).get("절결론"), dict) else {}
    글 = N.펴기(맥, 결론.get(절키), "Narrative.절결론.%s" % 절키) if _글(결론.get(절키)) else ""
    글 = (글.rstrip() + ("" if 글.rstrip().endswith(".") else ".")) if 글 else ""
    머 = ""
    for i, x in enumerate(W._절조각(맥.가정, 절키)):
        if isinstance(x, dict) and x.get("자리") == "머리":
            새 = M.절글줄(맥, "Narrative.절글.%s[%d]" % (절키, i), x)
            if 새:
                _원고자리적기(맥, 절키, 번, i, x, 새)
                머 = " ".join(l for l in 새 if l.strip())
            break
    return " ".join(t for t in (글, 머) if t)


def 블록절(맥, 번, 절키, 옛, 둘째표=()):
    """추정 블록 하나 — 옛 절(같은 절 함수가 지은 줄들)에서 제목 · 사업 그림만 가져오고 나머지는 새 꼴로 짓는다."""
    import 레터원고 as W                                     # noqa: PLC0415
    import 레터추정표 as Q                                   # noqa: PLC0415
    근 = W.근거표(맥)
    L = [옛[0] if 옛 and ("%s" % 옛[0]).startswith("## ") else "## %d. %s" % (번, 제목[절키]), ""]
    첫 = 블록머리글(맥, 절키, 번)
    if 첫:
        L += [첫, ""]
    for b in W.블록절[절키]:
        t = Q.가정결과표(근, b, 맥.원, 정의=False)
        if not t:
            continue
        정 = Q.브리지열정의() if b == "브리지" else (None if getattr(맥, "_블록열정의", False) else Q.첫열정의(근))
        if 정 and b != "브리지":
            맥._블록열정의 = True                                  # 열 정의는 첫 표에 한 번(같은 문형을 블록마다 되풀이하지 않는다)
        본 = Q.펴기(맥, t + ([정] if 정 else [])).split("\n")
        L += 본 + 열정의덧(맥, 본) + [""]
    둘 = [x for x in (둘째표 or []) if ("%s" % x).strip()]
    if 둘:
        L += list(둘째표) + [""]
    L += 블록원고(맥, 절키, 번)
    if 절키 == "주주가치":                                     # 날짜 둘 고지(이월 한 줄 · 평가기준일 후 사건) — 정의 · 고지 문장이라 블록에 둔다(옛 판이면 빈 목록)
        L += P.이월글(맥) + P.후사건(맥)
    if 절키 == "세금":                                         # 시나리오에서만 서는 영업가치 조정(이월 세액공제)의 고지 — 기준 시나리오 표에는 0 으로만 보인다
        L += P.세액공제조정글(맥)
    그림, 표 = _옛조각나누기(옛[2:] if 옛 else [])
    둘줄 = {("%s" % x).strip() for x in 둘 if ("%s" % x).startswith("|")}
    옮김 = [d for d in 표 if not any(("%s" % x).strip() in 둘줄 for x in d if ("%s" % x).startswith("|"))]
    for 종, 덩 in 그림:
        if 종 in ("범위띠", "분포자리"):                          # 근거 범위의 그림은 부록(본편은 「가정과 결과」 표 한 장)
            옮김.append(덩)
        else:
            L += 덩
    if 옮김:
        getattr(맥, "블록부록", []).append((절키, L[0][3:].split(". ", 1)[-1].strip(), 옮김))
    for 이름, 소 in getattr(맥, "_블록소절", None) or []:          # 옛 절이 블록 밖으로 내놓은 소절(제목 · 표 주석 · 표 · 그림 통째) — 부록에 제 이름으로
        getattr(맥, "블록부록", []).append((절키, 이름, [list(소)]))
    if getattr(맥, "_블록소절", None):
        맥._블록소절 = []
    getattr(맥, "블록절들", set()).add(절키)
    return L


def 블록감싸기(절키, f, 둘째=None):
    """옛 절 함수 f 를 블록의 꼴로 감싼다 — 근거표가 서지 않으면 f 그대로."""
    def g(맥, 번):
        if not 블록꼴(맥):
            return f(맥, 번)
        맥._절글끔 = True                                     # 옛 절은 제목 · 그림 · 옮길 표만 쓴다 — 원고는 블록원고가 한 번 놓는다
        앞수 = len(맥.장부.줄)
        try:
            옛 = f(맥, 번)
        finally:
            맥._절글끔 = False
        뒤수 = len(맥.장부.줄)
        L = 블록절(맥, 번, 절키, 옛, 둘째(맥) if 둘째 else ())
        장부거두기(맥, 앞수, 뒤수, L + [x for _k, _이, 덩들 in (getattr(맥, "블록부록", None) or []) if _k == 절키 for d in 덩들 for x in d])
        return L
    return g


def 장부거두기(맥, 앞수, 뒤수, 남은줄):
    """옛 절을 짓는 동안 장부에 적힌 줄 가운데 남은 줄(블록 · 부록으로 옮긴 표)에 글이 없는 것을 거둔다 — 버린 조립 문장의 숫자가
    장부에 남으면 게이트 ⑦ 이 「글이 초안에 없다」 로 막는다. 거둔 키는 뒤에 다시 적을 수 있게 본 목록에서도 뺀다."""
    글 = "\n".join("%s" % x for x in 남은줄)
    남, 거둠 = [], 0
    for i, x in enumerate(맥.장부.줄):
        if 앞수 <= i < 뒤수 and x.get("글") and x["글"] not in 글:
            맥.장부._본.discard((x["키"], x["꼴"]))
            거둠 += 1
            continue
        남.append(x)
    맥.장부.줄[:] = 남
    return 거둠


def 블록부록(맥):
    """부록 「추정 블록의 근거 표」 — 본편 블록에서 옮긴 표(세 시나리오 가정표 · 근거 범위표 · 범위띠 · 구성표 · 계정 배치표 · 전방별 매출표 따위)."""
    줄 = []
    for _절키, 이름, 덩들 in getattr(맥, "블록부록", None) or []:
        줄 += ["### %s" % 이름, ""]
        for d in 덩들:
            줄 += list(d)
    return 줄


def 절첫줄넣기(맥, 키, 줄):
    """절 머리 바로 아래에 「결론 한 문장(`Narrative.절결론.<절>`) + 주당가치 폭(`절폭글`)」 한 문단을 둔다. 둘 다 없으면 그대로."""
    import 레터원고 as W                                     # noqa: PLC0415
    if 키 not in {k for k, _g in W.절결론절} or not 줄 or not ("%s" % 줄[0]).startswith("## "):
        return 줄
    if 키 in (getattr(맥, "블록절들", None) or set()):            # 레터 v27 6단계 — 추정 블록은 머리 문단을 블록절이 짓는다(절 결론 + 원고 머리)
        return 줄
    결론 = (_N(맥).get("절결론") or {}) if isinstance(_N(맥).get("절결론"), dict) else {}
    글 = N.펴기(맥, 결론.get(키), "Narrative.절결론.%s" % 키) if _글(결론.get(키)) else ""
    글 = (글.rstrip() + ("" if 글.rstrip().endswith(".") else ".")) if 글 else ""
    폭 = 절폭글(맥, 키)
    첫 = " ".join(x for x in (글, 폭) if x)
    if not 첫:
        return 줄
    return list(줄[:2]) + [첫, ""] + list(줄[2:])


# ══════════════════════════════════════════════════════════════════ 짜임

def 절목록(맥):
    """[(키, 함수)] — 이 회사에 해당하는 절만."""
    인 = (맥.구.get("인건비") or {}).get("산정방식")
    절들 = [("결론", 결론절)]
    if 맥.원.get("지난") is not None:                      # 지난 평가와의 차이 — 결론 바로 뒤(이번 값이 지난 값에서 무엇 때문에 움직였나)
        절들.append(("다리", 고친제목("다리", N.다리절)))
    # 2026-10-31 L8 — 독자가 읽는 차례: 업황 · 경쟁 → (추정 구조) → 매출 → 비용 → 투자 → 할인 → 가치. 업황 절은 지수 · 배분율(추정 구조)보다 먼저 선다
    # 레터 v27 6단계 — 추정 블록은 `블록감싸기`(근거표가 서면 머리 · 「가정과 결과」 표 · 원고 통째 · 사업 그림 / 옛 표는 부록)
    절들 += [("Narrative", 서사절), ("업황", 업황절), ("구조", 구조절), ("매출", 블록감싸기("매출", 매출절, 둘째=반대대조블록)),
           ("비용", 블록감싸기("비용", 비용절))]
    if 인 == "인원":
        절들.append(("인건비", 블록감싸기("인건비", 인건비절)))
    절들 += [("재투자", 블록감싸기("재투자", 재투자절)), ("운전자본", 블록감싸기("운전자본", 운전자본절)),
           ("세금", 블록감싸기("세금", 감싼절("세금", P.세금절, 덧=세금덧))), ("할인율", 블록감싸기("할인율", 감싼절("할인율", P.할인율절, 덧=할인율덧))),
           ("영구", 블록감싸기("영구", 감싼절("영구", P.영구절, 덧=영구덧))),
           ("주주가치", 블록감싸기("주주가치", 감싼절("주주가치", P.주주가치절, 덧=브리지덧))),
           ("시나리오", 시나리오절), ("민감도", 민감도절)]
    if 맥.종가키:
        절들.append(("역산", 역산절))
    절들 += [("신호", 신호절), ("자리", 자리절), ("점검", 고친제목("점검", P.점검절)), ("파일", 고친제목("파일", P.파일절))]
    return 절들


def 쓰기(맥):
    """머리 · 3분 레터 · 본편(목차 · 절들). 절 번호는 본편의 차례(1부터)."""
    종가 = _n((맥.민.get("표4") or {}).get("종가"))
    맥.종가키 = "민:표4:종가" if 종가 and 종가 > 0 else None
    맥.개요 = P.개요문단(맥)
    제목.clear()                                              # 구조에 따라 제목의 뒤(「그 절이 하는 일」)가 달라지는 절 — 선언하지 않은 갈래의 말을 넣지 않는다
    제목.update(_제목기본)
    if not ((맥.구.get("운전자본") or {}).get("미지급항목")):
        제목["운전자본"] = "운전자본 추정 : 계정별 회전일수"
    인 = 맥.구.get("인건비") or {}
    if 인.get("산정방식") != "인원" or 인.get("성과급") == "없음" or 인.get("인원경로") == "수준":     # 1.1.4 — 게이트 ⑧ 의 성과급 선언 조건과 같은 판정(제목이 선언 밖 낱말을 쓰던 자리)
        제목["인건비"] = "인건비 추정 : 인원과 1인당 급여" if 인.get("산정방식") == "인원" else "인건비 추정 : 인건비의 추정 기준"
    능 = any(x.get("판매량산정") == "능력" for x in 맥.구.get("매출구분") or [])
    프 = bool((맥.구.get("투자") or {}).get("프로젝트"))
    if not 능:                                               # 공장이 없는 회사에 「공장별 투자 일정」 을 쓰지 않는다(견본 실측)
        제목["재투자"] = "설비투자와 감가상각 : 투자 일정과 유지 투자" if 프 else "설비투자와 감가상각 : 유지 투자와 감가상각"
    절들 = 절목록(맥)
    맥.절 = {k: i + 1 for i, (k, _f) in enumerate(절들)}
    맥.블록부록, 맥.블록절들, 맥._블록열정의, 맥._CAPEX열정의, 맥._블록소절 = [], set(), False, False, []      # 레터 v27 6단계 — 추정 블록에서 옮긴 표 · 새 꼴로 선 블록 · 열 정의 한 번
    맥.막번 = set()
    for 옛, 새 in (("막1", "역산"), ("막2", "Narrative"), ("막3", "주주가치"), ("막4", "역산"), ("막5", "신호"), ("이야기점검", "신호"),
                  ("실적", "구조"), ("방법", "구조"), ("공장", "재투자"), ("한계", "자리")):
        if 새 in 맥.절:
            맥.절.setdefault(옛, 맥.절[새])
    L = P._머리(맥)
    맥.층 = "독자"                                          # 3분 레터 — 지수 · 배수 없이(눈금 = 100 · 돈 · 과거 비교)
    L += T.쓰기(맥)
    L += [본편머리, ""]
    맥.층 = "깊이"
    몸, 목 = [], []
    for 키, f in 절들:
        줄 = 절첫줄넣기(맥, 키, f(맥, 맥.절[키]))
        목.append("- [%s](#s%d)" % (줄[0][3:].strip(), 맥.절[키]))
        몸 += 줄
    # v27 문장(교열 9 · 10) — 본편의 짜임을 설명하던 문단은 지웠다(목차가 같은 일을 한다)
    L += 목 + ["- [부록](#부록)", ""]
    L += 몸
    return L
